def number(value, default=0.0):
    """Convertit une saisie en nombre (accepte « 1 234,56 », « 1,234.56 », « 1.234,56 », « 20 % », « 12 € »).
    Les valeurs non finies (nan, inf) et les textes invalides renvoient `default`."""
    if isinstance(value, bool):
        return default
    if isinstance(value, (int, float)):
        return float(value) if math.isfinite(value) else default
    text = str(value).strip()
    for junk in ("€", "%", "\u00a0", "\u202f", " "):
        text = text.replace(junk, "")
    if not text:
        return default
    if "," in text and "." in text:
        # Le dernier séparateur rencontré est le séparateur décimal.
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        text = text.replace(",", ".")
    try:
        result = float(text)
    except ValueError:
        return default
    return result if math.isfinite(result) else default


def dst_transitions(year):
    """Changements d'heure en France : (passage à l'heure d'été, passage à l'heure d'hiver).
    Ce sont les derniers dimanches de mars et d'octobre (règle européenne, toujours 2 h -> 3 h / 3 h -> 2 h)."""
    def last_sunday(month):
        day = date(year, month, 31)          # mars et octobre ont 31 jours
        return day - timedelta(days=(day.weekday() + 1) % 7)
    return last_sunday(3), last_sunday(10)


def dst_hour_factor(a, b, start, end):
    """Coefficient de durée réelle d'une tranche [a, b[ incluse dans la période [start, end[.

    0 : tranche dans l'heure qui n'existe pas (2h-3h, dernier dimanche de mars)
    2 : tranche dans l'heure vécue deux fois (2h-3h, dernier dimanche d'octobre), si la période
        commence avant 2h et finit après 3h (une heure saisie « 02:30 » est ambiguë : comptée une fois)
    1 : tous les autres cas
    """
    spring, autumn = dst_transitions(a.year)
    if datetime(spring.year, spring.month, spring.day, 2) <= a and b <= datetime(spring.year, spring.month, spring.day, 3):
        return 0
    lo = datetime(autumn.year, autumn.month, autumn.day, 2)
    hi = datetime(autumn.year, autumn.month, autumn.day, 3)
    if lo <= a and b <= hi and start < lo and end > hi:
        return 2
    return 1


def dst_shift_minutes(start, end):
    """Minutes à ajouter (ou retrancher) à la durée « horloge » d'une période pour obtenir sa durée réelle."""
    total = 0.0
    for year in range(start.year, end.year + 1):
        spring, autumn = dst_transitions(year)
        s2 = datetime(spring.year, spring.month, spring.day, 2)
        s3 = datetime(spring.year, spring.month, spring.day, 3)
        overlap = (min(end, s3) - max(start, s2)).total_seconds() / 60.0
        if overlap > 0:
            total -= overlap
        a2 = datetime(autumn.year, autumn.month, autumn.day, 2)
        a3 = datetime(autumn.year, autumn.month, autumn.day, 3)
        if start < a2 and end > a3:
            total += 60.0
    return total


def euro(value):
    """Arrondi commercial au centime (0,5 centime -> arrondi supérieur), sans erreur de virgule flottante."""
    try:
        return float(
            Decimal(repr(round(float(value), 6))).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        )
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return 0.0


def money(value):
    return f"{value:,.2f}".replace(",", "X").replace(".", ",").replace("X", " ")


def parse_datetime(value):
    if not value:
        return None

    for fmt in ("%d/%m/%Y %H:%M", "%Y-%m-%d %H:%M"):
        try:
            return datetime.strptime(str(value).strip(), fmt)
        except ValueError:
            continue

    return None


def french_holidays(year):
    fixed = {
        date(year, 1, 1),
        date(year, 5, 1),
        date(year, 5, 8),
        date(year, 7, 14),
        date(year, 8, 15),
        date(year, 11, 1),
        date(year, 11, 11),
        date(year, 12, 25),
    }

    # Calcul de Pâques — algorithme de Meeus/Jones/Butcher.
    a = year % 19
    b = year // 100
    c = year % 100
    d = b // 4
    e = b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i = c // 4
    k = c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    month = (h + l - 7 * m + 114) // 31
    day = ((h + l - 7 * m + 114) % 31) + 1

    easter = date(year, month, day)
    fixed.add(easter + timedelta(days=1))
    fixed.add(easter + timedelta(days=39))
    fixed.add(easter + timedelta(days=50))
    return fixed


def holidays_between(start, end):
    result = set()
    for year in range(start.year, end.year + 1):
        result.update(french_holidays(year))
    return result


