def parse_date(value):
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(str(value).strip(), fmt).date()
        except ValueError:
            continue
    return None


def fmt_date(value):
    return value.strftime("%d/%m/%Y") if value else ""


def fmt_dt(value):
    return value.strftime("%d/%m/%Y %H:%M")


def fmt_hm(value):
    return value.strftime("%Hh%M")


def fmt_h(value):
    """Heures décimales -> texte lisible (ex. 7,5 h)."""
    return f"{value:.2f}".rstrip("0").rstrip(".").replace(".", ",") + " h" if value else "0 h"


def add_months(day, months):
    total = day.month - 1 + int(months)
    year = day.year + total // 12
    month = total % 12 + 1
    last = calendar.monthrange(year, month)[1]
    return date(year, month, min(day.day, last))


def monday_of(day):
    return day - timedelta(days=day.weekday())


def week_monday(key):
    """Lundi de la semaine ISO (année, semaine) — compatible Python 3.7."""
    return datetime.strptime("%d-W%02d-1" % (key[0], key[1]), "%G-W%V-%u").date()


def iso_week_key(day):
    iso = day.isocalendar()
    return (iso[0], iso[1])


def employee_label(emp):
    return (str(emp.get("prenom", "")).strip() + " " + str(emp.get("nom", "")).strip()).strip()


def normalize_qualifications(values):
    """CQP APS / CQP AS sont remplacés par TFP APS (sans doublon)."""
    result = []
    for item in values or []:
        text = str(item).strip()
        if not text:
            continue
        if text.upper().replace(" ", "") in ("CQPAPS", "CQPAS"):
            text = "TFP APS"
        if text not in result:
            result.append(text)
    return result


def cert_status(cert, ref=None):
    """Retourne (fin_validité, prochain_recyclage, libellé, niveau 0/1/2)."""
    ref = ref or date.today()
    obtention = parse_date(cert.get("obtention", ""))
    validite = int(number(cert.get("validite_mois"), 0))
    periodic = int(number(cert.get("recyclage_mois"), 0))
    last_recycl = parse_date(cert.get("dernier_recyclage", "")) or obtention
    end_validity = add_months(obtention, validite) if obtention and validite > 0 else None
    next_recycl = add_months(last_recycl, periodic) if last_recycl and periodic > 0 else None
    level, label = 0, "Valide"
    if not obtention:
        return end_validity, next_recycl, "Date manquante", 1
    if end_validity is None and next_recycl is None:
        return end_validity, next_recycl, "Illimitée", 0
    for limit, what in ((end_validity, "Validité"), (next_recycl, "Recyclage")):
        if limit is None:
            continue
        if limit < ref:
            return end_validity, next_recycl, what + " expirée", 2
        if (limit - ref).days <= 90 and level < 1:
            level, label = 1, what + " < 90 j"
    return end_validity, next_recycl, label, level


def required_cert_tokens(profile):
    p = str(profile or "").lower()
    tokens = []
    if "aps" in p or "agent" in p:
        tokens += ["carte pro", "tfp aps"]
    for key in ("ssiap 1", "ssiap 2", "ssiap 3"):
        if key in p:
            tokens.append(key)
    if "pse" in p or "secouriste" in p:
        tokens.append("pse")
    return tokens


def expired_required_cert(emp, profile, ref_day):
    """Nom de la première carte / certification exigée par le profil et expirée à la date donnée."""
    tokens = required_cert_tokens(profile)
    if not tokens:
        return None
    for cert in emp.get("certifications") or []:
        name = str(cert.get("nom", "")).lower()
        if any(tok in name for tok in tokens):
            if cert_status(cert, ref_day)[3] == 2:
                return cert.get("nom", "")
    return None


def agent_matches_profile(emp, profile):
    profile = str(profile or "").strip().lower()
    if not profile:
        return True
    if str(emp.get("profil", "")).strip().lower() == profile:
        return True
    return any(str(q).strip().lower() == profile for q in emp.get("qualifications") or [])


def night_minutes(start, end):
    """Minutes travaillées dans la plage 21h-6h (travail de nuit)."""
    total = 0
    cursor = start
    step = timedelta(minutes=15)
    while cursor < end:
        if cursor.hour >= 21 or cursor.hour < 6:
            total += 15
        cursor += step
    return total


def weekly_rest_ok(intervals, start, end, need_hours):
    """Vérifie qu'aucune fenêtre glissante de 7 jours ne perd sa plage de repos consécutif."""
    need = timedelta(hours=need_hours)
    near = [(a, b) for a, b in intervals
            if b > start - timedelta(days=8) and a < end + timedelta(days=8)]
    near.append((start, end))
    near.sort()
    day0 = datetime.combine(start.date(), datetime.min.time())
    for k in range(7):
        w0 = day0 - timedelta(days=k)
        w1 = w0 + timedelta(days=7)
        cursor, best = w0, timedelta(0)
        for a, b in near:
            if b <= w0 or a >= w1:
                continue
            a2, b2 = max(a, w0), min(b, w1)
            if a2 > cursor:
                best = max(best, a2 - cursor)
            cursor = max(cursor, b2)
        best = max(best, w1 - cursor)
        if best < need:
            return False
    return True


def shift_days(start, end):
    """Jours calendaires touchés par une vacation."""
    days = [start.date()]
    last = (end - timedelta(minutes=1)).date()
    while days[-1] < last:
        days.append(days[-1] + timedelta(days=1))
    return days


class HRScheduler:
    """Génère un planning respectant le Code du travail, avec rotation des postes."""

    def __init__(self, employees, settings, missions):
        self.settings = settings
        self.employees = employees
        self.missions = missions
        self.states = {}
        for emp in employees:
            label = employee_label(emp)
            if not label or label in self.states:
                continue
            self.states[label] = {
                "emp": emp, "label": label, "intervals": [], "week": {}, "day": {},
                "postes": {}, "last_poste": None, "total": 0.0,
            }

    # -- paramètres ----------------------------------------------------
    def p(self, key):
        return number(self.settings.get(key, HR_DEFAULT_SETTINGS.get(key)), number(HR_DEFAULT_SETTINGS.get(key), 0.0))

    def flag(self, key):
        return str(self.settings.get(key, HR_DEFAULT_SETTINGS.get(key))) in ("1", "True", "true", "oui")

    def poste_labels(self):
        return [x.strip() for x in str(self.settings.get("postes", "")).split(",") if x.strip()]

    # -- découpage en vacations ------------------------------------------
    def split_mission(self, start, end):
        cap_day = max(1.0, min(self.p("vacation_max"), self.p("max_jour")))
        cap_night = max(1.0, self.p("max_nuit"))
        total_min = int((end - start).total_seconds() // 60)
        if total_min <= 0:
            return []
        night_ratio = night_minutes(start, end) / float(total_min)
        cap = cap_day
        if night_ratio >= 0.5:
            cap = min(cap, cap_night)
        n = max(1, int(math.ceil(total_min / (cap * 60.0) - 1e-9)))
        bounds = [0]
        for k in range(1, n):
            raw = total_min * k / float(n)
            bounds.append(int(round(raw / 15.0) * 15))
        bounds.append(total_min)
        chunks = []
        for a, b in zip(bounds[:-1], bounds[1:]):
            if b <= a:
                continue
            s, e = start + timedelta(minutes=a), start + timedelta(minutes=b)
            # Une vacation contenant du travail de nuit est limitée à max_nuit.
            if night_minutes(s, e) >= 180 and (e - s).total_seconds() / 3600.0 > cap_night + 1e-9:
                parts = int(math.ceil((e - s).total_seconds() / 3600.0 / cap_night - 1e-9))
                length = int((e - s).total_seconds() // 60)
                cuts = [int(round(length * j / float(parts) / 15.0) * 15) for j in range(parts + 1)]
                cuts[-1] = length
                for c0, c1 in zip(cuts[:-1], cuts[1:]):
                    if c1 > c0:
                        chunks.append((s + timedelta(minutes=c0), s + timedelta(minutes=c1)))
            else:
                chunks.append((s, e))
        return chunks

    # -- pauses ------------------------------------------------------------
    def pause_plan(self, start, end):
        length = (end - start).total_seconds() / 60.0
        each = int(self.p("pause_min"))
        if length <= self.p("pause_seuil") * 60 or each <= 0:
            return [], 0
        count = 2 if length > 9 * 60 else 1
        starts = []
        for k in range(1, count + 1):
            middle = start + timedelta(minutes=length * k / (count + 1.0) - each / 2.0)
            minute = int(round(middle.minute / 5.0) * 5)
            middle = middle.replace(minute=0) + timedelta(minutes=minute)
            starts.append(middle)
        return starts, each * count

    def effective_hours(self, start, end):
        _, pause_total = self.pause_plan(start, end)
        hours = (end - start).total_seconds() / 3600.0 + dst_shift_minutes(start, end) / 60.0
        if self.flag("deduire_pauses"):
            hours -= pause_total / 60.0
        return max(hours, 0.0)

    def target_week(self, emp):
        value = number(emp.get("heures_semaine"), 35.0)
        return value if value > 0 else 35.0

    # -- éligibilité -------------------------------------------------------
    def eligible(self, state, shift, allow_overtime):
        emp = state["emp"]
        if not emp.get("planning", True):
            return False
        if str(emp.get("disponibilite", "Disponible")) not in ("Disponible", "En mission"):
            return False
        s, e = shift["start"], shift["end"]
        abs_a, abs_b = parse_date(emp.get("absence_debut", "")), parse_date(emp.get("absence_fin", ""))
        if abs_a and abs_b and any(abs_a <= d <= abs_b for d in shift_days(s, e)):
            return False
        if not agent_matches_profile(emp, shift["profil"]):
            return False
        if expired_required_cert(emp, shift["profil"], s.date()):
            return False
        rest = timedelta(hours=self.p("repos_quotidien"))
        for a, b in state["intervals"]:
            if a < e and s < b:
                return False
            if b <= s and s - b < rest:
                return False
            if e <= a and a - e < rest:
                return False
        day_total = state["day"].get(s.date(), 0.0) + shift["eff"]
        if day_total > self.p("max_jour") + 1e-9:
            return False
        limit = self.p("max_semaine") if allow_overtime else self.target_week(emp)
        week = state["week"].get(iso_week_key(s.date()), 0.0)
        if week + shift["eff"] > limit + 1e-9:
            return False
        # jours consécutifs
        worked = set()
        for a, b in state["intervals"]:
            worked.update(shift_days(a, b))
        new_days = shift_days(s, e)
        worked.update(new_days)
        run_max = int(self.p("jours_consec"))
        for d in new_days:
            count = 1
            k = 1
            while d - timedelta(days=k) in worked:
                count += 1
                k += 1
            k = 1
            while d + timedelta(days=k) in worked:
                count += 1
                k += 1
            if count > run_max:
                return False
        return weekly_rest_ok(state["intervals"], s, e, self.p("repos_hebdo"))

    # -- génération ------------------------------------------------------------
    def build_shifts(self, period_start, period_end):
        groups = []
        for mission in self.missions:
            start = parse_datetime(mission.get("debut"))
            end = parse_datetime(mission.get("fin"))
            if not start or not end or end <= start:
                continue
            if period_start and end.date() < period_start:
                continue
            if period_end and start.date() > period_end:
                continue
            need = max(1, int(number(mission.get("agents"), 1)))
            for s, e in self.split_mission(start, end):
                groups.append({
                    "mission": mission.get("mission", ""), "profil": mission.get("profil", ""),
                    "start": s, "end": e, "need": need,
                    "eff": self.effective_hours(s, e),
                })
        groups.sort(key=lambda g: (g["start"], g["mission"]))
        return groups

    def generate(self, period_start=None, period_end=None):
        groups = self.build_shifts(period_start, period_end)
        labels_cfg = self.poste_labels()
        result = []
        for group in groups:
            chosen = []
            for _ in range(group["need"]):
                pick = None
                for allow_overtime in ((False, True) if self.flag("heures_sup") else (False,)):
                    candidates = [
                        st for st in self.states.values()
                        if st["label"] not in [c[0]["label"] for c in chosen if c[0]]
                        and self.eligible(st, group, allow_overtime)
                    ]
                    if candidates:
                        candidates.sort(key=lambda st: (
                            st["week"].get(iso_week_key(group["start"].date()), 0.0) / self.target_week(st["emp"]),
                            st["total"], st["label"]))
                        pick = (candidates[0], allow_overtime)
                        break
                if pick:
                    state, overtime = pick
                    state["intervals"].append((group["start"], group["end"]))
                    key = iso_week_key(group["start"].date())
                    state["week"][key] = state["week"].get(key, 0.0) + group["eff"]
                    state["day"][group["start"].date()] = state["day"].get(group["start"].date(), 0.0) + group["eff"]
                    state["total"] += group["eff"]
                    chosen.append((state, overtime))
                else:
                    chosen.append((None, False))
            # Rotation des postes : chaque agent reçoit le poste qu'il a le moins occupé.
            names = []
            for j in range(group["need"]):
                names.append(labels_cfg[j] if j < len(labels_cfg) else "Poste %d" % (j + 1))
            free = list(names)
            assigned = {}
            for idx, (state, overtime) in enumerate(chosen):
                if state is None:
                    continue
                free.sort(key=lambda nm: (state["postes"].get(nm, 0), nm == state["last_poste"], names.index(nm)))
                poste = free.pop(0)
                state["postes"][poste] = state["postes"].get(poste, 0) + 1
                state["last_poste"] = poste
                assigned[idx] = poste
            for idx, (state, overtime) in enumerate(chosen):
                poste = assigned.get(idx) or (free.pop(0) if free else names[idx % len(names)])
                starts, total_pause = self.pause_plan(group["start"], group["end"])
                pause_text = " ; ".join(
                    "%s (%d min)" % (p.strftime("%Hh%M"), total_pause // len(starts)) for p in starts
                ) if starts else "Aucune"
                result.append({
                    "mission": group["mission"], "profil": group["profil"],
                    "debut": fmt_dt(group["start"]), "fin": fmt_dt(group["end"]),
                    "poste": poste, "agent": state["label"] if state else "",
                    "pauses": pause_text, "pause_min": total_pause,
                    "heures": round(group["eff"], 2), "hs": bool(overtime),
                })
        result.sort(key=lambda sh: (parse_datetime(sh["debut"]), sh["mission"], sh["poste"]))
        return result


def parsed_shifts(shifts):
    out = []
    for idx, sh in enumerate(shifts):
        s, e = parse_datetime(sh.get("debut")), parse_datetime(sh.get("fin"))
        if s and e and e > s:
            out.append((idx, s, e, sh))
    return out


def audit_schedule(employees, shifts, settings):
    """Contrôle un planning : retourne (alertes, statistiques par agent)."""
    def p(key):
        return number(settings.get(key, HR_DEFAULT_SETTINGS.get(key)), number(HR_DEFAULT_SETTINGS.get(key), 0.0))

    alerts = []
    emp_by_label = {employee_label(e): e for e in employees}
    by_agent = {}
    unfilled = {}
    for idx, s, e, sh in parsed_shifts(shifts):
        name = sh.get("agent", "")
        if not name:
            unfilled.setdefault(sh.get("mission", ""), []).append(s)
            continue
        by_agent.setdefault(name, []).append((s, e, sh))

    for mission, starts in sorted(unfilled.items()):
        alerts.append(("Erreur", mission or "Mission",
                       "%d vacation(s) non pourvue(s), première le %s — effectif insuffisant, indisponibilités ou carte expirée."
                       % (len(starts), fmt_dt(min(starts)))))

    stats = {}
    for name, items in by_agent.items():
        items.sort(key=lambda x: x[0])
        emp = emp_by_label.get(name, {})
        target = number(emp.get("heures_semaine"), 35.0) or 35.0
        st = {"heures": 0.0, "vacations": 0, "jours": set(), "hs": 0.0, "postes": {}, "semaines": {}}
        for s, e, sh in items:
            eff = number(sh.get("heures"), 0.0)
            st["heures"] += eff
            st["vacations"] += 1
            st["jours"].update(shift_days(s, e))
            st["postes"][sh.get("poste", "")] = st["postes"].get(sh.get("poste", ""), 0) + 1
            wk = iso_week_key(s.date())
            st["semaines"][wk] = st["semaines"].get(wk, 0.0) + eff
        st["hs"] = sum(max(0.0, h - target) for h in st["semaines"].values())
        stats[name] = st

        # durée quotidienne / vacation de nuit
        per_day = {}
        for s, e, sh in items:
            per_day[s.date()] = per_day.get(s.date(), 0.0) + number(sh.get("heures"), 0.0)
            length = (e - s).total_seconds() / 3600.0
            if night_minutes(s, e) >= 180 and length > p("max_nuit") + 1e-9:
                alerts.append(("Alerte", name, "Vacation de nuit de %s le %s (> %s h : dérogation conventionnelle requise)."
                               % (fmt_h(length), fmt_date(s.date()), fmt_h(p("max_nuit")))))
        for day, hours in sorted(per_day.items()):
            if hours > p("max_jour") + 1e-9:
                alerts.append(("Erreur", name, "%s de travail effectif le %s (max %s)." % (fmt_h(hours), fmt_date(day), fmt_h(p("max_jour")))))
        # repos quotidien
        for (s1, e1, _), (s2, e2, _) in zip(items[:-1], items[1:]):
            gap = (s2 - e1).total_seconds() / 3600.0
            if gap < p("repos_quotidien") - 1e-9:
                alerts.append(("Erreur", name, "Repos quotidien de %s seulement entre le %s et le %s (min %s)."
                               % (fmt_h(max(gap, 0)), fmt_dt(e1), fmt_dt(s2), fmt_h(p("repos_quotidien")))))
        # durée hebdomadaire
        for wk, hours in sorted(st["semaines"].items()):
            label_wk = "semaine %d/%d" % (wk[1], wk[0])
            if hours > p("max_semaine") + 1e-9:
                alerts.append(("Erreur", name, "%s en %s (maximum absolu %s)." % (fmt_h(hours), label_wk, fmt_h(p("max_semaine")))))
            elif hours > target + 1e-9:
                alerts.append(("Info", name, "%s d'heures supplémentaires en %s (%s planifiées pour %s de contrat)."
                               % (fmt_h(hours - target), label_wk, fmt_h(hours), fmt_h(target))))
        # moyenne sur 12 semaines
        keys = sorted(st["semaines"])
        if keys:
            first = week_monday(keys[0])
            last = week_monday(keys[-1])
            if first and last:
                weeks = []
                cursor = first
                while cursor <= last:
                    weeks.append(st["semaines"].get(iso_week_key(cursor), 0.0))
                    cursor += timedelta(days=7)
                if len(weeks) >= 12:
                    for i in range(len(weeks) - 11):
                        avg = sum(weeks[i:i + 12]) / 12.0
                        if avg > p("moyenne_12") + 1e-9:
                            alerts.append(("Erreur", name, "Moyenne de %s/semaine sur 12 semaines (max %s)." % (fmt_h(avg), fmt_h(p("moyenne_12")))))
                            break
        # jours consécutifs
        days = sorted(st["jours"])
        run = 1
        for a, b in zip(days[:-1], days[1:]):
            run = run + 1 if (b - a).days == 1 else 1
            if run > int(p("jours_consec")):
                alerts.append(("Erreur", name, "Plus de %d jours consécutifs travaillés (jusqu'au %s)." % (int(p("jours_consec")), fmt_date(b))))
                break
        # repos hebdomadaire consécutif
        if days and (days[-1] - days[0]).days >= 6:
            ivs = [(s, e) for s, e, _ in items]
            cursor = datetime.combine(days[0], datetime.min.time())
            last_start = datetime.combine(days[-1], datetime.min.time()) - timedelta(days=6)
            while cursor <= last_start:
                w1 = cursor + timedelta(days=7)
                pos, best = cursor, timedelta(0)
                for a, b in ivs:
                    if b <= cursor or a >= w1:
                        continue
                    a2, b2 = max(a, cursor), min(b, w1)
                    if a2 > pos:
                        best = max(best, a2 - pos)
                    pos = max(pos, b2)
                best = max(best, w1 - pos)
                if best < timedelta(hours=p("repos_hebdo")):
                    alerts.append(("Erreur", name, "Repos hebdomadaire < %s consécutives sur la période débutant le %s."
                                   % (fmt_h(p("repos_hebdo")), fmt_date(cursor.date()))))
                    break
                cursor += timedelta(days=1)
        # repos mensuel (mois complets seulement)
        if days:
            month_cursor = date(days[0].year, days[0].month, 1)
            while month_cursor <= days[-1]:
                nb = calendar.monthrange(month_cursor.year, month_cursor.month)[1]
                m_first, m_last = month_cursor, month_cursor.replace(day=nb)
                if days[0] <= m_first and days[-1] >= m_last:
                    off = nb - len([d for d in days if m_first <= d <= m_last])
                    if off < p("repos_mensuel"):
                        alerts.append(("Alerte", name, "Seulement %d jour(s) de repos en %s %d (min %d)."
                                       % (off, MONTHS_FR[month_cursor.month - 1], month_cursor.year, int(p("repos_mensuel")))))
                month_cursor = add_months(month_cursor, 1)
        # cartes / certifications
        for s, e, sh in items:
            bad = expired_required_cert(emp, sh.get("profil", ""), s.date()) if emp else None
            if bad:
                alerts.append(("Erreur", name, "%s expirée au %s (mission %s)." % (bad, fmt_date(s.date()), sh.get("mission", ""))))
                break
    order = {"Erreur": 0, "Alerte": 1, "Info": 2}
    alerts.sort(key=lambda a: (order.get(a[0], 9), a[1]))
    return alerts, stats


# ======================================================================
# BLOC II — MANAGEMENT DES RESSOURCES HUMAINES : interface
# ======================================================================


class HRModule:
    """Méthodes du Bloc II (effectif, formations, équipes, matériel, emploi du temps)."""

    QUALIFICATIONS_DISPONIBLES = ["SST", "Habilitation élec.", "TFP APS", "SSIAP 1", "Carte pro"]

    # ------------------------------------------------------------------
    # État et persistance
    # ------------------------------------------------------------------

    def _init_hr_state(self):
        self.hr_settings = dict(HR_DEFAULT_SETTINGS)
        self.hr_schedule = []
        self.hr_vars = {key: tk.StringVar(value=value) for key, value in HR_DEFAULT_SETTINGS.items()}
        self.hr_view_mode = tk.StringVar(value="Semaine")
        self.hr_view_date = tk.StringVar(value=fmt_date(date.today()))
        self.hr_view_scope = tk.StringVar(value=TEAM_SCOPE)
        self.mgmt_tab = 0
        self.hr_tree = None
        self.hr_gantt = None

    def _sync_hr_settings(self):
        for key, var in self.hr_vars.items():
            self.hr_settings[key] = var.get().strip()

    def _apply_hr_settings(self):
        for key, var in self.hr_vars.items():
            var.set(str(self.hr_settings.get(key, HR_DEFAULT_SETTINGS[key])))

    def _load_hr_from(self, data):
        """Recharge les données RH depuis un dossier (JSON ou autosauvegarde)."""
        self.hr_settings = dict(HR_DEFAULT_SETTINGS)
        self.hr_settings.update(data.get("hr_settings", {}) or {})
        self.hr_schedule = list(data.get("hr_schedule", []) or [])
        self._apply_hr_settings()
        self._normalize_employees()
        start = parse_date(self.hr_settings.get("debut", ""))
        if start:
            self.hr_view_date.set(fmt_date(start))

    def _reset_hr(self):
        self.hr_settings = dict(HR_DEFAULT_SETTINGS)
        self.hr_schedule = []
        self._apply_hr_settings()

    def _normalize_employees(self):
        for emp in self.employees:
            quals = emp.get("qualifications") or [
                q.strip() for q in str(emp.get("qualification", "")).split(",") if q.strip()
            ]
            emp["qualifications"] = normalize_qualifications(quals)
            emp["qualification"] = ", ".join(emp["qualifications"])
            emp.setdefault("prenom", "")
            emp.setdefault("service", "")
            emp.setdefault("contrat", "CDI")
            emp["heures_semaine"] = number(emp.get("heures_semaine"), 35.0) or 35.0
            emp.setdefault("telephone", "")
            emp.setdefault("email", "")
            emp.setdefault("date_embauche", "")
            emp.setdefault("absence_debut", "")
            emp.setdefault("absence_fin", "")
            emp.setdefault("notes", "")
            emp.setdefault("planning", True)
            emp.setdefault("disponibilite", "Disponible")
            if not isinstance(emp.get("certifications"), list):
                emp["certifications"] = []

    def _agent_plan_stats(self):
        stats = {}
        for idx, s, e, sh in parsed_shifts(self.hr_schedule):
            name = sh.get("agent", "")
            if not name:
                continue
            count, hours = stats.get(name, (0, 0.0))
            stats[name] = (count + 1, hours + number(sh.get("heures"), 0.0))
        return stats

    def _planning_labels(self):
        labels = [employee_label(e) for e in self.employees if e.get("planning", True) and employee_label(e)]
        for _, _, _, sh in parsed_shifts(self.hr_schedule):
            if sh.get("agent") and sh["agent"] not in labels:
                labels.append(sh["agent"])
        return labels

    def _selected_indexes(self, tree):
        result = []
        for iid in tree.selection():
            try:
                result.append(int(str(iid).split("-")[0]))
            except ValueError:
                continue
        return result

    # ------------------------------------------------------------------
    # Page « Management RH » (onglets)
    # ------------------------------------------------------------------

    def build_management(self):
        self.add_section_heading(
            self.page_frame, "Management des ressources humaines",
            "Effectif complet, formations et cartes, équipes, matériel et besoins par mission.",
        )
        self._normalize_employees()
        nb = ttk.Notebook(self.page_frame)
        nb.pack(fill="both", expand=True)
        self.management_nb = nb
        self.management_trees = {}
        self._build_workforce_tab(nb)
        self._build_certs_tab(nb)
        self._build_management_teams(nb)
        self._build_management_equipment(nb)
        self._build_management_needs(nb)
        self._refresh_management()
        try:
            nb.select(min(self.mgmt_tab, nb.index("end") - 1))
        except tk.TclError:
            pass
        nb.bind("<<NotebookTabChanged>>", self._on_mgmt_tab_changed)

    def _on_mgmt_tab_changed(self, event=None):
        try:
            self.mgmt_tab = self.management_nb.index(self.management_nb.select())
            self._highlight_nav()
        except (tk.TclError, AttributeError):
            pass

    def open_integrated_bloc2(self):
        """Ouvre l'outil BLOC II original directement dans la zone centrale.
        L'interface générale de Gergovie reste inchangée.
        """
        self._sauvegarder_etat_integrated_bloc2()
        self.current_page = "management"
        for child in self.page_frame.winfo_children():
            child.destroy()
        self.page_title.config(text="Bloc II — Effectif, formations et matériel".upper())
        self._update_section_chip("management")
        self._ensure_bloc_open("management")
        self._highlight_nav()
        self.integrated_bloc2 = Bloc2OutilIntegre(self.page_frame)
        self.integrated_bloc2.pack(fill="both", expand=True)

    def open_management(self, tab=0):
        self.mgmt_tab = tab
        self.show_page("management")

    def _sauvegarder_etat_integrated_bloc2(self):
        """Conserve les données RH/planning avant de reconstruire les pages."""
        bloc = getattr(self, "integrated_bloc2", None)
        if bloc is None:
            return
        try:
            if not bloc.winfo_exists():
                return
            self._bloc2_saved_state = bloc.preparer_donnees_pour_export()
            bloc.sauvegarder_automatiquement()
        except (tk.TclError, AttributeError, OSError, TypeError, ValueError):
            pass

    def _tree_tab(self, notebook, title, columns, widths=None, height=15):
        tab = tk.Frame(notebook, bg=self.colors["surface"])
        notebook.add(tab, text=title)
        top = tk.Frame(tab, bg=self.colors["surface"])
        top.pack(fill="x", padx=12, pady=12)
        holder = tk.Frame(tab, bg=self.colors["surface"])
        holder.pack(fill="both", expand=True, padx=12, pady=(0, 12))
        holder.columnconfigure(0, weight=1)
        holder.rowconfigure(0, weight=1)
        tree = ttk.Treeview(holder, columns=columns, show="headings", height=height, selectmode="extended")
        ys = ttk.Scrollbar(holder, orient="vertical", command=tree.yview)
        xs = ttk.Scrollbar(holder, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=ys.set, xscrollcommand=xs.set)
        tree.grid(row=0, column=0, sticky="nsew")
        ys.grid(row=0, column=1, sticky="ns")
        xs.grid(row=1, column=0, sticky="ew")
        for i, col in enumerate(columns):
            tree.heading(col, text=col)
            width = (widths[i] if widths and i < len(widths) else 130)
            tree.column(col, width=width, anchor="center", stretch=True)
        tree.tag_configure("bad", foreground=self.colors["danger"])
        tree.tag_configure("warn", foreground=self.colors["warning"])
        tree.tag_configure("muted", foreground=self.colors["muted"])
        tree.tag_configure("stripe_even", background="#100D18")
        tree.tag_configure("stripe_odd", background="#15101D")
        self.management_trees[title] = tree
        return tab, top, tree

    # ---- Effectif complet ------------------------------------------------

    def _build_workforce_tab(self, nb):
        cols = ("Nom", "Prénom", "Service", "Profil", "Contrat", "H/sem", "Habilitations",
                "Cartes / certifications", "Disponibilité", "Inclus au planning", "Positionnement")
        tab, top, tree = self._tree_tab(
            nb, "Effectif complet", cols, (110, 100, 140, 120, 80, 60, 200, 260, 100, 110, 190))
        ttk.Button(top, text="➕ Ajouter un agent", command=self._add_employee_dialog).pack(side="left")
        ttk.Button(top, text="✎ Modifier", command=lambda: self._edit_employee_dialog(tree)).pack(side="left", padx=8)
        ttk.Button(top, text="🗑 Supprimer", style="Danger.TButton", command=self._delete_employees).pack(side="left")
        ttk.Button(top, text="📄 PDF effectif", command=self.export_workforce_pdf).pack(side="right")
        ttk.Button(top, text="⬇ CSV effectif", command=self.export_workforce_csv).pack(side="right", padx=8)
        tree.bind("<Double-1>", lambda event: self._edit_employee_dialog(tree))

    def _workforce_rows(self):
        stats = self._agent_plan_stats()
        rows = []
        for i, emp in enumerate(self.employees):
            label = employee_label(emp)
            certs = []
            worst = 0
            for cert in emp.get("certifications", []):
                st = cert_status(cert)
                worst = max(worst, st[3])
                certs.append("%s (%s)" % (cert.get("nom", ""), st[2]))
            included = bool(emp.get("planning", True))
            if not included:
                position = "Exclu du planning"
            elif label in stats:
                position = "Positionné — %d vac. / %s" % (stats[label][0], fmt_h(stats[label][1]))
            else:
                position = "Non positionné"
            tag = "bad" if worst == 2 else ("warn" if worst == 1 else ("muted" if not included else ""))
            rows.append((i, [
                emp.get("nom", ""), emp.get("prenom", ""), emp.get("service", ""), emp.get("profil", ""),
                emp.get("contrat", ""), ("%g" % number(emp.get("heures_semaine"), 35.0)),
                ", ".join(emp.get("qualifications", [])), " ; ".join(certs),
                emp.get("disponibilite", ""), "Oui" if included else "Non", position,
            ], tag))
        return rows

    def _add_employee_dialog(self):
        self._employee_dialog()

    def _edit_employee_dialog(self, tree=None):
        tree = tree or self.management_trees.get("Effectif complet")
        indexes = self._selected_indexes(tree) if tree else []
        if not indexes:
            messagebox.showinfo("Sélection", "Sélectionnez d'abord un agent dans la liste.")
            return
        if 0 <= indexes[0] < len(self.employees):
            self._employee_dialog(existing=self.employees[indexes[0]], existing_index=indexes[0])

    def _delete_employees(self):
        tree = self.management_trees.get("Effectif complet")
        indexes = sorted(self._selected_indexes(tree), reverse=True) if tree else []
        if not indexes:
            return
        if not messagebox.askyesno("Supprimer", "Supprimer %d agent(s) sélectionné(s) ?" % len(indexes)):
            return
        for idx in indexes:
            if 0 <= idx < len(self.employees):
                label = employee_label(self.employees[idx])
                self.employees.pop(idx)
                for sh in self.hr_schedule:
                    if sh.get("agent") == label:
                        sh["agent"] = ""
        self.mark_dirty()
        self._refresh_management()

    def _employee_dialog(self, existing=None, existing_index=None):
        data = existing or {}
        win = tk.Toplevel(self)
        win.title("Modifier l'agent" if existing else "Nouvel agent")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        win.configure(bg=self.colors["surface"])
        bg, fg = self.colors["surface"], self.colors["text"]
        profils = [a.get("nom", "") for a in self.agents] or ["APS Jour"]

        def text_var(key, default=""):
            return tk.StringVar(value=str(data.get(key, default)))

        v_nom, v_prenom = text_var("nom"), text_var("prenom")
        v_service = text_var("service", SERVICES_DEFAULT[0])
        v_profil = text_var("profil", profils[0])
        v_contrat = text_var("contrat", "CDI")
        v_heures = text_var("heures_semaine", 35)
        v_dispo = text_var("disponibilite", "Disponible")
        v_cout = text_var("cout_horaire", 15)
        v_tel, v_mail = text_var("telephone"), text_var("email")
        v_embauche = text_var("date_embauche")
        v_abs_a, v_abs_b = text_var("absence_debut"), text_var("absence_fin")
        v_planning = tk.BooleanVar(value=bool(data.get("planning", True)))

        fields = [
            ("Nom *", v_nom, None), ("Prénom", v_prenom, None),
            ("Service", v_service, SERVICES_DEFAULT), ("Profil tarifaire", v_profil, profils),
            ("Contrat", v_contrat, CONTRATS_DEFAULT), ("Heures / semaine", v_heures, None),
            ("Disponibilité", v_dispo, DISPONIBILITES), ("Coût horaire (€)", v_cout, None),
            ("Téléphone", v_tel, None), ("E-mail", v_mail, None),
            ("Date d'embauche (JJ/MM/AAAA)", v_embauche, None), ("", None, None),
            ("Absence du (JJ/MM/AAAA)", v_abs_a, None), ("Absence au (JJ/MM/AAAA)", v_abs_b, None),
        ]
        for i, (label, var, values) in enumerate(fields):
            if var is None:
                continue
            r, c = i // 2, (i % 2) * 2
            tk.Label(win, text=label, bg=bg, fg=fg).grid(row=r, column=c, sticky="w", padx=(14, 6), pady=6)
            if values is None:
                ttk.Entry(win, textvariable=var, width=24).grid(row=r, column=c + 1, sticky="w", padx=(0, 10), pady=6)
            else:
                state = "readonly" if label in ("Profil tarifaire", "Disponibilité") else "normal"
                ttk.Combobox(win, textvariable=var, values=values, width=22, state=state).grid(
                    row=r, column=c + 1, sticky="w", padx=(0, 10), pady=6)
        row = len(fields) // 2 + 1
        ttk.Checkbutton(win, text="Inclure cet agent dans le planning", variable=v_planning).grid(
            row=row, column=0, columnspan=4, sticky="w", padx=14, pady=(8, 2))
        row += 1
        tk.Label(win, text="Habilitations / diplômes", bg=bg, fg=fg, font=("Consolas", 9, "bold")).grid(
            row=row, column=0, columnspan=4, sticky="w", padx=14, pady=(8, 2))
        row += 1
        existing_quals = set(normalize_qualifications(data.get("qualifications") or []))
        qual_frame = tk.Frame(win, bg=bg)
        qual_frame.grid(row=row, column=0, columnspan=4, sticky="w", padx=14)
        qual_vars = {}
        for i, qual in enumerate(self.QUALIFICATIONS_DISPONIBLES):
            var = tk.BooleanVar(value=qual in existing_quals)
            qual_vars[qual] = var
            ttk.Checkbutton(qual_frame, text=qual, variable=var).grid(row=i // 3, column=i % 3, sticky="w", padx=(0, 18), pady=2)
        row += 1
        tk.Label(win, text="Autres habilitations", bg=bg, fg=fg).grid(row=row, column=0, sticky="w", padx=14, pady=6)
        autre_var = tk.StringVar(value=", ".join(q for q in existing_quals if q not in self.QUALIFICATIONS_DISPONIBLES))
        ttk.Entry(win, textvariable=autre_var, width=54).grid(row=row, column=1, columnspan=3, sticky="w", pady=6)
        row += 1
        tk.Label(win, text="Notes", bg=bg, fg=fg).grid(row=row, column=0, sticky="w", padx=14, pady=6)
        notes_var = tk.StringVar(value=str(data.get("notes", "")))
        ttk.Entry(win, textvariable=notes_var, width=54).grid(row=row, column=1, columnspan=3, sticky="w", pady=6)
        row += 1
        tk.Label(win, text="Les formations, validités et recyclages se saisissent dans l'onglet « Formations & cartes ».",
                 bg=bg, fg=self.colors["muted"], font=("Consolas", 8)).grid(row=row, column=0, columnspan=4, sticky="w", padx=14)
        row += 1

        def ok():
            nom = v_nom.get().strip()
            if not nom:
                messagebox.showwarning("Nom manquant", "Le nom de l'agent est obligatoire.", parent=win)
                return
            for value, what in ((v_embauche.get(), "d'embauche"), (v_abs_a.get(), "d'absence (début)"), (v_abs_b.get(), "d'absence (fin)")):
                if value.strip() and not parse_date(value):
                    messagebox.showwarning("Date invalide", "La date %s doit être au format JJ/MM/AAAA." % what, parent=win)
                    return
            quals = [q for q, v in qual_vars.items() if v.get()]
            quals += [q.strip() for q in autre_var.get().split(",") if q.strip()]
            quals = normalize_qualifications(quals)
            old_label = employee_label(data) if existing else ""
            record = dict(data)
            record.update(
                nom=nom, prenom=v_prenom.get().strip(), service=v_service.get().strip(),
                profil=v_profil.get(), contrat=v_contrat.get().strip(),
                heures_semaine=number(v_heures.get(), 35.0) or 35.0,
                disponibilite=v_dispo.get(), cout_horaire=self._safe_float(v_cout.get()),
                telephone=v_tel.get().strip(), email=v_mail.get().strip(),
                date_embauche=v_embauche.get().strip(), absence_debut=v_abs_a.get().strip(),
                absence_fin=v_abs_b.get().strip(), planning=bool(v_planning.get()),
                qualifications=quals, qualification=", ".join(quals), notes=notes_var.get().strip(),
            )
            record.setdefault("certifications", [])
            new_label = employee_label(record)
            if existing_index is not None:
                self.employees[existing_index] = record
                if old_label and old_label != new_label:
                    for sh in self.hr_schedule:
                        if sh.get("agent") == old_label:
                            sh["agent"] = new_label
            else:
                self.employees.append(record)
            win.destroy()
            self.mark_dirty()
            self._refresh_management()
            if hasattr(self, "pg_qualification_var"):
                try:
                    self._refresh_pg_qualification_choices()
                except tk.TclError:
                    pass

        ttk.Button(win, text="Enregistrer", style="Primary.TButton", command=ok).grid(row=row, column=0, columnspan=4, pady=14)

    # ---- Formations & cartes -------------------------------------------------

    def _build_certs_tab(self, nb):
        cols = ("Agent", "Certification", "Formation (h)", "Obtention", "Validité (mois)", "Fin de validité",
                "Recyclage (h)", "Recyclage tous les (mois)", "Prochain recyclage", "Statut")
        tab, top, tree = self._tree_tab(nb, "Formations & cartes", cols, (150, 150, 90, 90, 90, 100, 90, 120, 110, 140))
        ttk.Button(top, text="➕ Ajouter", command=lambda: self._cert_dialog()).pack(side="left")
        ttk.Button(top, text="✎ Modifier", command=self._edit_cert).pack(side="left", padx=8)
        ttk.Button(top, text="🗑 Supprimer", style="Danger.TButton", command=self._delete_cert).pack(side="left")
        tk.Label(top, text="Valeurs préremplies indicatives : à vérifier auprès de votre organisme de formation.",
                 bg=self.colors["surface"], fg=self.colors["muted"], font=("Consolas", 8)).pack(side="right")
        tree.bind("<Double-1>", lambda event: self._edit_cert())

    def _cert_rows(self):
        rows = []
        for i, emp in enumerate(self.employees):
            for j, cert in enumerate(emp.get("certifications", [])):
                end_v, next_r, status, level = cert_status(cert)
                rows.append(("%d-%d" % (i, j), [
                    employee_label(emp), cert.get("nom", ""), ("%g" % number(cert.get("formation_h"), 0)),
                    cert.get("obtention", ""),
                    ("%d" % number(cert.get("validite_mois"), 0)) if number(cert.get("validite_mois"), 0) else "Illimitée",
                    fmt_date(end_v) if end_v else "—", ("%g" % number(cert.get("recyclage_h"), 0)),
                    ("%d" % number(cert.get("recyclage_mois"), 0)) if number(cert.get("recyclage_mois"), 0) else "—",
                    fmt_date(next_r) if next_r else "—", status,
                ], "bad" if level == 2 else ("warn" if level == 1 else "")))
        return rows

    def _selected_cert(self):
        tree = self.management_trees.get("Formations & cartes")
        sel = tree.selection() if tree else ()
        if not sel:
            messagebox.showinfo("Sélection", "Sélectionnez d'abord une ligne.")
            return None
        try:
            i, j = [int(x) for x in str(sel[0]).split("-")]
        except ValueError:
            return None
        return i, j

    def _edit_cert(self):
        pos = self._selected_cert()
        if pos:
            self._cert_dialog(pos[0], pos[1])

    def _delete_cert(self):
        pos = self._selected_cert()
        if not pos:
            return
        i, j = pos
        if messagebox.askyesno("Supprimer", "Supprimer cette formation / carte ?"):
            try:
                self.employees[i]["certifications"].pop(j)
            except (IndexError, KeyError):
                return
            self.mark_dirty()
            self._refresh_management()

    def _cert_dialog(self, emp_index=None, cert_index=None):
        if not self.employees:
            messagebox.showinfo("Aucun agent", "Ajoutez d'abord un agent dans l'onglet « Effectif complet ».")
            return
        cert = {}
        if emp_index is not None and cert_index is not None:
            cert = dict(self.employees[emp_index]["certifications"][cert_index])
        win = tk.Toplevel(self)
        win.title("Formation / carte / certification")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        win.configure(bg=self.colors["surface"])
        bg, fg = self.colors["surface"], self.colors["text"]
        labels = [employee_label(e) for e in self.employees]
        v_agent = tk.StringVar(value=labels[emp_index] if emp_index is not None else labels[0])
        v_nom = tk.StringVar(value=cert.get("nom", "TFP APS"))
        v_form = tk.StringVar(value=str(cert.get("formation_h", 0)))
        v_obt = tk.StringVar(value=cert.get("obtention", ""))
        v_val = tk.StringVar(value=str(cert.get("validite_mois", 0)))
        v_rech = tk.StringVar(value=str(cert.get("recyclage_h", 0)))
        v_per = tk.StringVar(value=str(cert.get("recyclage_mois", 0)))
        v_last = tk.StringVar(value=cert.get("dernier_recyclage", ""))
        v_num = tk.StringVar(value=cert.get("numero", ""))

        def apply_preset(event=None):
            preset = CERT_PRESETS.get(v_nom.get())
            if preset and emp_index is None:
                v_form.set(str(preset["formation_h"]))
                v_val.set(str(preset["validite_mois"]))
                v_rech.set(str(preset["recyclage_h"]))
                v_per.set(str(preset["recyclage_mois"]))

        rows = [
            ("Agent", v_agent, labels, "readonly"),
            ("Certification / carte", v_nom, list(CERT_PRESETS.keys()), "normal"),
            ("Durée de formation (h)", v_form, None, None),
            ("Date d'obtention (JJ/MM/AAAA)", v_obt, None, None),
            ("Durée de validité (mois, 0 = illimitée)", v_val, None, None),
            ("Durée du recyclage (h)", v_rech, None, None),
            ("Recyclage tous les (mois, 0 = aucun)", v_per, None, None),
            ("Dernier recyclage (JJ/MM/AAAA)", v_last, None, None),
            ("N° de carte / certificat", v_num, None, None),
        ]
        for i, (label, var, values, state) in enumerate(rows):
            tk.Label(win, text=label, bg=bg, fg=fg).grid(row=i, column=0, sticky="w", padx=14, pady=6)
            if values is None:
                ttk.Entry(win, textvariable=var, width=30).grid(row=i, column=1, padx=14, pady=6)
            else:
                box = ttk.Combobox(win, textvariable=var, values=values, width=28, state=state)
                box.grid(row=i, column=1, padx=14, pady=6)
                if label.startswith("Certification"):
                    box.bind("<<ComboboxSelected>>", apply_preset)

        def ok():
            if not v_nom.get().strip():
                messagebox.showwarning("Champ manquant", "Indiquez la certification.", parent=win)
                return
            for value, what in ((v_obt.get(), "d'obtention"), (v_last.get(), "du dernier recyclage")):
                if value.strip() and not parse_date(value):
                    messagebox.showwarning("Date invalide", "La date %s doit être au format JJ/MM/AAAA." % what, parent=win)
                    return
            record = dict(
                nom=v_nom.get().strip(), formation_h=number(v_form.get(), 0), obtention=v_obt.get().strip(),
                validite_mois=int(number(v_val.get(), 0)), recyclage_h=number(v_rech.get(), 0),
                recyclage_mois=int(number(v_per.get(), 0)), dernier_recyclage=v_last.get().strip(),
                numero=v_num.get().strip(),
            )
            target = labels.index(v_agent.get())
            if emp_index is not None and cert_index is not None:
                if target == emp_index:
                    self.employees[emp_index]["certifications"][cert_index] = record
                else:
                    self.employees[emp_index]["certifications"].pop(cert_index)
                    self.employees[target]["certifications"].append(record)
            else:
                self.employees[target]["certifications"].append(record)
            win.destroy()
            self.mark_dirty()
            self._refresh_management()

        ttk.Button(win, text="Enregistrer", style="Primary.TButton", command=ok).grid(
            row=len(rows), column=0, columnspan=2, pady=14)

    # ---- Équipes, matériel, besoins ------------------------------------------

    def _simple_add_dialog(self, title, fields, callback):
        win = tk.Toplevel(self)
        win.title(title)
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        win.configure(bg=self.colors["surface"])
        vars_ = []
        for i, (label, default) in enumerate(fields):
            tk.Label(win, text=label, bg=self.colors["surface"], fg=self.colors["text"]).grid(
                row=i, column=0, sticky="w", padx=12, pady=7)
            var = tk.StringVar(value=str(default))
            ttk.Entry(win, textvariable=var, width=34).grid(row=i, column=1, padx=12, pady=7)
            vars_.append(var)

        def ok():
            callback([v.get().strip() for v in vars_])
            win.destroy()
            self.mark_dirty()

        ttk.Button(win, text="Enregistrer", style="Primary.TButton", command=ok).grid(
            row=len(fields), column=0, columnspan=2, pady=12)

    def _build_management_teams(self, nb):
        tab, top, tree = self._tree_tab(nb, "Équipes", ("Nom", "Chef d'équipe", "Membres", "Statut"), (180, 180, 320, 120))
        ttk.Button(top, text="➕ Ajouter", command=self._add_team_dialog).pack(side="left")
        ttk.Button(top, text="🗑 Supprimer", style="Danger.TButton", command=lambda: self._delete_selected(tree, self.teams, self._refresh_management)).pack(side="left", padx=8)

    def _build_management_equipment(self, nb):
        tab, top, tree = self._tree_tab(
            nb, "Matériel", ("Désignation", "Catégorie", "Quantité", "Coût unitaire", "Total", "État"))
        ttk.Button(top, text="➕ Ajouter", command=self._add_equipment_dialog).pack(side="left")
        ttk.Button(top, text="🗑 Supprimer", style="Danger.TButton", command=lambda: self._delete_selected(tree, self.equipment, self._refresh_management)).pack(side="left", padx=8)

    def _build_management_needs(self, nb):
        tab, top, tree = self._tree_tab(
            nb, "Besoins RH", ("Mission", "Profil", "Besoin", "Disponible", "Manquant", "Statut"))
        ttk.Button(top, text="➕ Ajouter", command=self._add_need_dialog).pack(side="left")
        ttk.Button(top, text="🗑 Supprimer", style="Danger.TButton", command=lambda: self._delete_selected(tree, self.hr_needs, self._refresh_management)).pack(side="left", padx=8)

    def _add_team_dialog(self):
        self._simple_add_dialog("Nouvelle équipe", [("Nom", "Équipe 1"), ("Chef d'équipe", ""), ("Membres", ""), ("Statut", "Disponible")], self._save_team)

    def _save_team(self, v):
        self.teams.append(dict(nom=v[0], chef=v[1], membres=v[2], statut=v[3]))
        self._refresh_management()

    def _add_equipment_dialog(self):
        self._simple_add_dialog("Matériel", [("Désignation", ""), ("Catégorie", "Matériel"), ("Quantité", "1"), ("Coût unitaire", "0"), ("État", "Disponible")], self._save_equipment)

    def _save_equipment(self, v):
        qty = self._safe_float(v[2])
        unit = self._safe_float(v[3])
        self.equipment.append(dict(designation=v[0], categorie=v[1], quantite=qty, cout_unitaire=unit, total=qty * unit, etat=v[4]))
        self._refresh_management()

    def _add_need_dialog(self):
        self._simple_add_dialog("Besoin RH", [("Mission", ""), ("Profil", "APS Jour"), ("Besoin", "1"), ("Disponible", "0")], self._save_need)

    def _save_need(self, v):
        self.hr_needs.append(dict(mission=v[0], profil=v[1], besoin=int(self._safe_float(v[2])), disponible=int(self._safe_float(v[3]))))
        self._refresh_management()

    def _delete_selected(self, tree, data, refresh):
        sel = tree.selection()
        if not sel:
            return
        indexes = [tree.index(i) for i in sel]
        for idx in sorted(indexes, reverse=True):
            if 0 <= idx < len(data):
                data.pop(idx)
        refresh()
        self.mark_dirty()

    def _fill_tree(self, title, rows):
        tree = self.management_trees.get(title) if hasattr(self, "management_trees") else None
        if tree is None:
            return
        try:
            tree.delete(*tree.get_children())
        except tk.TclError:
            return
        for index, (iid, values, tag) in enumerate(rows):
            stripe = "stripe_even" if index % 2 == 0 else "stripe_odd"
            tags = tuple(item for item in (tag, stripe) if item)
            tree.insert("", "end", iid=iid, values=values, tags=tags)

    def _refresh_management(self):
        if not hasattr(self, "management_trees"):
            return
        self._fill_tree("Effectif complet", [(str(i), v, t) for i, v, t in self._workforce_rows()])
        self._fill_tree("Formations & cartes", self._cert_rows())
        self._fill_tree("Équipes", [(str(i), (x.get("nom", ""), x.get("chef", ""), x.get("membres", ""), x.get("statut", "")), "")
                                    for i, x in enumerate(self.teams)])
        self._fill_tree("Matériel", [(str(i), (
            x.get("designation", ""), x.get("categorie", ""), self._safe_float(x.get("quantite")),
            "%.2f €" % self._safe_float(x.get("cout_unitaire")), "%.2f €" % self._safe_float(x.get("total")), x.get("etat", "")), "")
            for i, x in enumerate(self.equipment)])
        needs = []
        for i, x in enumerate(self.hr_needs):
            need = int(self._safe_float(x.get("besoin")))
            avail = int(self._safe_float(x.get("disponible")))
            miss = max(0, need - avail)
            needs.append((str(i), (x.get("mission", ""), x.get("profil", ""), need, avail, miss, "À compléter" if miss else "OK"), "warn" if miss else ""))
        self._fill_tree("Besoins RH", needs)

    # ------------------------------------------------------------------
    # Exports de l'effectif
    # ------------------------------------------------------------------

    def export_workforce_csv(self):
        path = filedialog.asksaveasfilename(
            title="Exporter l'effectif", defaultextension=".csv",
            filetypes=[("Fichier CSV", "*.csv"), ("Tous les fichiers", "*.*")], initialfile="Effectif_Gergovie.csv")
        if not path:
            return
        try:
            with open(path, "w", newline="", encoding="utf-8-sig") as file:
                writer = csv.writer(file, delimiter=";")
                writer.writerow(["Nom", "Prénom", "Service", "Profil", "Contrat", "H/sem", "Habilitations",
                                 "Cartes / certifications", "Disponibilité", "Inclus au planning", "Positionnement",
                                 "Téléphone", "E-mail", "Date d'embauche", "Coût horaire"])
                for i, values, _ in self._workforce_rows():
                    emp = self.employees[i]
                    writer.writerow(values + [emp.get("telephone", ""), emp.get("email", ""),
                                              emp.get("date_embauche", ""), emp.get("cout_horaire", "")])
            messagebox.showinfo("Export terminé", "Effectif exporté :\n" + path)
        except OSError as error:
            messagebox.showerror("Erreur", str(error))

    def export_workforce_pdf(self):
        path = filedialog.asksaveasfilename(
            title="Exporter l'effectif en PDF", defaultextension=".pdf",
            filetypes=[("Fichier PDF", "*.pdf"), ("Tous les fichiers", "*.*")], initialfile="Effectif_Gergovie.pdf")
        if not path:
            return
        cols = [("Nom", 70), ("Prénom", 60), ("Service", 90), ("Profil", 75), ("Contrat", 45), ("H/s", 28),
                ("Habilitations", 110), ("Cartes / certifications", 170), ("Dispo", 60), ("Plan.", 30), ("Positionnement", 105)]
        rows = [{"values": v, "tag": t} for _, v, t in self._workforce_rows()]
        sections = [{
            "title": "Effectif de l'entreprise", "subtitle": ["Gergovie Sécurité — édité le " + fmt_date(date.today())],
            "columns": cols, "rows": rows, "notes": [],
        }]
        try:
            self._write_tables_pdf(path, sections)
            messagebox.showinfo("PDF créé", "Effectif exporté :\n" + path)
        except OSError as error:
            messagebox.showerror("Erreur PDF", str(error))

