        self.hr_alert_tree.tag_configure("Alerte", foreground=self.colors["warning"])
        self.hr_alert_tree.tag_configure("Info", foreground=self.colors["muted"])
        self.hr_alert_tree.pack(fill="x", padx=14, pady=(0, 12))

