    # ---- actions --------------------------------------------------------------

    def _reset_legal_values(self):
        for key, _ in HR_LEGAL_HINTS:
            self.hr_vars[key].set(HR_DEFAULT_SETTINGS[key])

    def _period_from_missions(self):
        starts, ends = [], []
        for row in self.rows:
            s, e = parse_datetime(row.get("debut")), parse_datetime(row.get("fin"))
            if s and e and e > s:
                starts.append(s)
                ends.append(e)
        if not starts:
            messagebox.showinfo("Aucune mission", "Ajoutez d'abord des missions dans le Bloc I (Planning des missions).")
            return
        self.hr_vars["debut"].set(fmt_date(min(starts).date()))
        self.hr_vars["fin"].set(fmt_date((max(ends) - timedelta(minutes=1)).date()))

    def _collect_flags(self):
        self.hr_vars["deduire_pauses"].set("1" if self.hr_ded_var.get() else "0")
        self.hr_vars["heures_sup"].set("1" if self.hr_hs_var.get() else "0")
        self._sync_hr_settings()

    def generate_schedule(self, silent=False):
        self._collect_flags()
        if not self.rows:
            messagebox.showinfo("Aucun événement", "Aucune mission n'est saisie : ajoutez-en dans le Bloc I (Planning des missions).")
            return
        if not [e for e in self.employees if e.get("planning", True)]:
            messagebox.showwarning("Aucun agent", "Aucun agent n'est inclus au planning. Ajoutez des agents dans la partie RH.")
            return
        d0, d1 = parse_date(self.hr_settings.get("debut", "")), parse_date(self.hr_settings.get("fin", ""))
        if not d0 or not d1:
            self._period_from_missions()
            self._sync_hr_settings()
            d0, d1 = parse_date(self.hr_settings.get("debut", "")), parse_date(self.hr_settings.get("fin", ""))
        if not d0 or not d1 or d1 < d0:
            messagebox.showwarning("Période invalide", "Renseignez une période valide (JJ/MM/AAAA).")
            return
        if self.hr_schedule and not silent and not messagebox.askyesno(
                "Remplacer le planning", "Le planning existant (y compris vos affectations manuelles) sera remplacé. Continuer ?"):
            return
        scheduler = HRScheduler(self.employees, self.hr_settings, self.rows)
        self.hr_schedule = scheduler.generate(d0, d1)
        self.hr_view_date.set(fmt_date(d0))
        self.mark_dirty()
        self.show_page("schedule")
        missing = len([s for s in self.hr_schedule if not s.get("agent")])
        overtime = len([s for s in self.hr_schedule if s.get("hs")])
        messagebox.showinfo(
            "Planning généré",
            "%d vacation(s) créée(s).\n%d non pourvue(s).\n%d vacation(s) en heures supplémentaires.\n\n"
            "Consultez les contrôles en bas de page." % (len(self.hr_schedule), missing, overtime))

    def clear_schedule(self):
        if self.hr_schedule and messagebox.askyesno("Vider", "Supprimer le planning généré ?"):
            self.hr_schedule = []
            self.mark_dirty()
            self.show_page("schedule")

    def _shift_view(self, direction):
        ref = parse_date(self.hr_view_date.get()) or date.today()
        mode = self.hr_view_mode.get()
        if mode == "Jour":
            ref += timedelta(days=direction)
        elif mode == "Semaine":
            ref += timedelta(days=7 * direction)
        else:
            ref = add_months(ref.replace(day=1), direction)
        self.hr_view_date.set(fmt_date(ref))
        self._refresh_schedule_view()

    def _view_today(self):
        self.hr_view_date.set(fmt_date(date.today()))
        self._refresh_schedule_view()

    def _on_schedule_double_click(self, event=None):
        iid = self.hr_tree.identify_row(event.y) if event is not None else ""
        if iid and str(iid).startswith("s"):
            try:
                self._reassign_shift(int(str(iid)[1:]))
            except ValueError:
                pass
    def _duplicate_selected_shifts(self):
        tree = getattr(self, "hr_tree", None)
        if tree is None:
            return
        selected = []
        for iid in tree.selection():
            if str(iid).startswith("s"):
                try:
                    idx = int(str(iid)[1:])
                except ValueError:
                    continue
                if 0 <= idx < len(self.hr_schedule):
                    selected.append(idx)
        selected = sorted(set(selected))
        if not selected:
            messagebox.showinfo("Dupliquer des vacations", "Sélectionnez une ou plusieurs vacations dans la vue Jour de l'équipe ou dans le planning d'un agent.", parent=self)
            return

        labels = self._planning_labels()
        if not labels:
            messagebox.showwarning("Aucun agent", "Ajoutez ou incluez des agents dans le planning avant de dupliquer des vacations.", parent=self)
            return
        win = tk.Toplevel(self)
        win.title("Dupliquer les vacations sélectionnées")
        win.transient(self)
        win.grab_set()
        win.configure(bg=self.colors["surface"])
        tk.Label(win, text="Choisissez les agents destinataires", bg=self.colors["surface"], fg=self.colors["text"], font=("Consolas", 10, "bold")).pack(anchor="w", padx=16, pady=(14, 4))
        tk.Label(win, text="Maintenez le bouton gauche et faites glisser sur les noms. Ctrl-clic permet une sélection séparée.", bg=self.colors["surface"], fg=self.colors["muted"], wraplength=440, justify="left").pack(anchor="w", padx=16, pady=(0, 8))
        frame = tk.Frame(win, bg=self.colors["surface"])
        frame.pack(fill="both", expand=True, padx=16, pady=4)
        agents = tk.Listbox(frame, selectmode=tk.EXTENDED, exportselection=False, height=min(max(len(labels), 5), 14), width=42, activestyle="dotbox")
        scrollbar = ttk.Scrollbar(frame, orient="vertical", command=agents.yview)
        agents.configure(yscrollcommand=scrollbar.set)
        agents.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        for label in labels:
            agents.insert(tk.END, label)

        def confirm():
            target_indexes = agents.curselection()
            if not target_indexes:
                messagebox.showinfo("Destinataires manquants", "Sélectionnez au moins un agent.", parent=win)
                return
            targets = [labels[i] for i in target_indexes]
            existing = {
                (sh.get("agent", ""), sh.get("debut", ""), sh.get("fin", ""), sh.get("mission", ""), sh.get("poste", ""))
                for sh in self.hr_schedule
            }
            added = 0
            for source_idx in selected:
                source = self.hr_schedule[source_idx]
                for target in targets:
                    key = (target, source.get("debut", ""), source.get("fin", ""), source.get("mission", ""), source.get("poste", ""))
                    if key in existing:
                        continue
                    duplicate = dict(source)
                    duplicate["agent"] = target
                    duplicate["hs"] = bool(source.get("hs", False))
                    self.hr_schedule.append(duplicate)
                    existing.add(key)
                    added += 1
            win.destroy()
            if added:
                self.hr_schedule.sort(key=lambda sh: (parse_datetime(sh.get("debut")) or datetime.min, sh.get("mission", ""), sh.get("poste", "")))
                self.mark_dirty()
                self._refresh_schedule_view()
            messagebox.showinfo("Duplication terminée", "%d vacation(s) dupliquée(s) vers %d agent(s). Les doublons déjà présents ont été ignorés." % (added, len(targets)), parent=self)

        buttons = tk.Frame(win, bg=self.colors["surface"])
        buttons.pack(fill="x", padx=16, pady=(8, 14))
        ttk.Button(buttons, text="Annuler", command=win.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(buttons, text="Dupliquer", style="Primary.TButton", command=confirm).pack(side="right")
    def _reassign_shift(self, idx):
        if not (0 <= idx < len(self.hr_schedule)):
            return
        shift = self.hr_schedule[idx]
        win = tk.Toplevel(self)
        win.title("Modifier l'affectation")
        win.transient(self)
        win.grab_set()
        win.resizable(False, False)
        win.configure(bg=self.colors["surface"])
        tk.Label(win, text="%s — %s → %s\n%s" % (shift.get("mission", ""), shift.get("debut", ""), shift.get("fin", "")[-5:], shift.get("poste", "")),
                 bg=self.colors["surface"], fg=self.colors["text"], justify="left").pack(padx=16, pady=(14, 6), anchor="w")
        choices = ["(Non pourvu)"] + self._planning_labels()
        var = tk.StringVar(value=shift.get("agent") or "(Non pourvu)")
        ttk.Combobox(win, textvariable=var, values=choices, state="readonly", width=32).pack(padx=16, pady=6)
        pause_frame = tk.Frame(win, bg=self.colors["surface"])
        pause_frame.pack(fill="x", padx=16, pady=6)
        tk.Label(pause_frame, text="Pause repas (début, HH:MM)", bg=self.colors["surface"], fg=self.colors["text"]).grid(row=0, column=0, sticky="w", pady=3)
        pause_start = tk.StringVar(value=shift.get("pause_debut", ""))
        ttk.Entry(pause_frame, textvariable=pause_start, width=10).grid(row=0, column=1, padx=8)
        tk.Label(pause_frame, text="Durée (min)", bg=self.colors["surface"], fg=self.colors["text"]).grid(row=1, column=0, sticky="w", pady=3)
        pause_duration = tk.StringVar(value=str(shift.get("pause_duree", "")))
        ttk.Entry(pause_frame, textvariable=pause_duration, width=10).grid(row=1, column=1, padx=8)
        tk.Label(win, text="Laissez le début vide pour conserver les pauses déjà prévues.", bg=self.colors["surface"], fg=self.colors["muted"]).pack(padx=16, anchor="w")

        def ok():
            custom_start = pause_start.get().strip()
            custom_duration = pause_duration.get().strip()
            if custom_start:
                try:
                    hh, mm = [int(part) for part in custom_start.split(":", 1)]
                    duration = int(custom_duration)
                    if not (0 <= hh <= 23 and 0 <= mm <= 59 and duration > 0):
                        raise ValueError
                    start_dt, end_dt = parse_datetime(shift.get("debut")), parse_datetime(shift.get("fin"))
                    break_start = start_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
                    if break_start < start_dt:
                        break_start += timedelta(days=1)
                    if break_start + timedelta(minutes=duration) > end_dt:
                        raise ValueError
                except (ValueError, TypeError, AttributeError):
                    messagebox.showwarning("Pause repas invalide", "Saisissez une heure HH:MM et une durée positive, entièrement comprise dans la vacation.", parent=win)
                    return
                old_pause = number(shift.get("pause_min"), 0)
                shift["pause_debut"] = break_start.strftime("%H:%M")
                shift["pause_duree"] = duration
                shift["pause_min"] = duration
                shift["pauses"] = "%s (%d min)" % (break_start.strftime("%Hh%M"), duration)
                if self.hr_settings.get("deduire_pauses", "1") == "1":
                    shift["heures"] = round(max(0, number(shift.get("heures"), 0) + (old_pause - duration) / 60.0), 2)
            shift["agent"] = "" if var.get() == "(Non pourvu)" else var.get()
            shift["hs"] = False
            win.destroy()
            self.mark_dirty()
            self._refresh_schedule_view()

        ttk.Button(win, text="Enregistrer", style="Primary.TButton", command=ok).pack(pady=(6, 14))

    # ---- construction des tableaux ------------------------------------------------

    def _range_for(self, mode, ref):
        if mode == "Jour":
            return ref, ref
        if mode == "Semaine":
            monday = monday_of(ref)
            return monday, monday + timedelta(days=6)
        first = ref.replace(day=1)
        return first, first.replace(day=calendar.monthrange(ref.year, ref.month)[1])

    @staticmethod
    def _short_time(moment):
        return moment.strftime("%Hh") if moment.minute == 0 else moment.strftime("%Hh%M")

    @staticmethod
    def _short_poste(label):
        return "P" + label[6:] if label.startswith("Poste ") else label[:8]

    @staticmethod
    def _period_code(start):
        h = start.hour
        if 4 <= h < 12:
            return "M"
        if 12 <= h < 18:
            return "A"
        if 18 <= h < 22:
            return "S"
        return "N"

    def _schedule_table(self, mode, scope, d0, d1):
        holidays = holidays_between(d0, d1)
        items = [(i, s, e, sh) for i, s, e, sh in parsed_shifts(self.hr_schedule) if d0 <= s.date() <= d1]
        items.sort(key=lambda x: (x[1], x[3].get("mission", ""), x[3].get("poste", "")))
        days = [d0 + timedelta(days=k) for k in range((d1 - d0).days + 1)]
        labels = self._planning_labels()
        emp_by_label = {employee_label(e): e for e in self.employees}
        table = {"columns": [], "rows": [], "note": ""}

        if scope == TEAM_SCOPE and mode == "Jour":
            table["columns"] = [("Début", 70), ("Fin", 70), ("Agent", 180), ("Mission", 220), ("Poste", 90), ("H effectives", 90), ("Pauses", 200)]
            busy = set()
            for i, s, e, sh in items:
                agent = sh.get("agent", "")
                busy.add(agent)
                table["rows"].append({"iid": "s%d" % i, "tag": "" if agent else "unfilled" if not sh.get("hs") else "hs", "values": [
                    fmt_hm(s), fmt_hm(e), agent or "⚠ NON POURVU", sh.get("mission", ""), sh.get("poste", ""),
                    fmt_h(number(sh.get("heures"), 0)), sh.get("pauses", "")]})
            for label in labels:
                if label not in busy:
                    emp = emp_by_label.get(label, {})
                    reason = "Repos"
                    a, b = parse_date(emp.get("absence_debut", "")), parse_date(emp.get("absence_fin", ""))
                    if a and b and a <= d0 <= b:
                        reason = "Absence"
                    elif emp and emp.get("disponibilite") in ("Indisponible", "Congés"):
                        reason = emp.get("disponibilite")
                    table["rows"].append({"iid": None, "tag": "repos", "values": ["", "", label, reason, "", "", ""]})
            table["note"] = "Double-clic sur une vacation pour modifier l'agent affecté."

        elif scope == TEAM_SCOPE and mode == "Semaine":
            cols = [("Agent", 170)] + [("%s %02d/%02d" % (DAYS_FR[d.weekday()], d.day, d.month), 105) for d in days] + [("Total h", 70), ("Contrat", 65)]
            table["columns"] = cols
            for label in labels:
                cells, total = [], 0.0
                for d in days:
                    parts = ["%s-%s %s" % (self._short_time(s), self._short_time(e), self._short_poste(sh.get("poste", "")))
                             for i, s, e, sh in items if sh.get("agent") == label and s.date() == d]
                    total += sum(number(sh.get("heures"), 0) for i, s, e, sh in items if sh.get("agent") == label and s.date() == d)
                    cells.append(" / ".join(parts) if parts else "—")
                target = number(emp_by_label.get(label, {}).get("heures_semaine"), 35.0)
                tag = "hs" if total > target + 1e-9 else ("repos" if total == 0 else "")
                table["rows"].append({"iid": None, "tag": tag, "values": [label] + cells + [fmt_h(total), fmt_h(target)]})
            unfilled = []
            for d in days:
                n = len([1 for i, s, e, sh in items if not sh.get("agent") and s.date() == d])
                unfilled.append("%d vac." % n if n else "—")
            if any(u != "—" for u in unfilled):
                table["rows"].append({"iid": None, "tag": "unfilled", "values": ["⚠ NON POURVU"] + unfilled + ["", ""]})
            table["note"] = "P = poste occupé. « — » = repos. Orange : heures supérieures au contrat. Utilisez la vue Jour pour modifier une affectation."

        elif scope == TEAM_SCOPE:  # Mois
            cols = [("Agent", 170)] + [("%s%d" % (DAYS_FR[d.weekday()][:2], d.day), 38) for d in days] + [("H eff.", 65), ("Repos", 55)]
            table["columns"] = cols
            for label in labels:
                cells, total, worked = [], 0.0, 0
                for d in days:
                    mine = [(s, sh) for i, s, e, sh in items if sh.get("agent") == label and s.date() == d]
                    total += sum(number(sh.get("heures"), 0) for s, sh in mine)
                    if mine:
                        worked += 1
                    cells.append("".join(self._period_code(s) for s, sh in mine) if mine else "")
                table["rows"].append({"iid": None, "tag": "repos" if not worked else "", "values": [label] + cells + [fmt_h(total), str(len(days) - worked)]})
            unfilled = []
            for d in days:
                n = len([1 for i, s, e, sh in items if not sh.get("agent") and s.date() == d])
                unfilled.append(str(n) if n else "")
            if any(unfilled):
                table["rows"].append({"iid": None, "tag": "unfilled", "values": ["⚠ NON POURVU"] + unfilled + ["", ""]})
            table["note"] = "M = matin (4h-12h) · A = après-midi (12h-18h) · S = soir (18h-22h) · N = nuit (22h-4h) · case vide = repos."

        else:  # agent seul, quel que soit le mode
            table["columns"] = [("Jour", 90), ("Date", 90), ("Vacation", 130), ("Mission", 220), ("Poste", 90), ("Pauses", 180), ("H effectives", 90)]
            total = 0.0
            emp = emp_by_label.get(scope, {})
            a_abs, b_abs = parse_date(emp.get("absence_debut", "")), parse_date(emp.get("absence_fin", ""))
            for d in days:
                mine = [(i, s, e, sh) for i, s, e, sh in items if sh.get("agent") == scope and s.date() == d]
                ferie = " (férié)" if d in holidays else ""
                if not mine:
                    reason = "Absence" if (a_abs and b_abs and a_abs <= d <= b_abs) else "Repos"
                    table["rows"].append({"iid": None, "tag": "repos", "values": [DAYS_FR_LONG[d.weekday()] + ferie, fmt_date(d), reason, "", "", "", ""]})
                for i, s, e, sh in mine:
                    hours = number(sh.get("heures"), 0)
                    total += hours
                    table["rows"].append({"iid": "s%d" % i, "tag": "hs" if sh.get("hs") else ("holiday" if ferie else ""), "values": [
                        DAYS_FR_LONG[d.weekday()] + ferie, fmt_date(d), "%s → %s" % (fmt_hm(s), fmt_hm(e)), sh.get("mission", ""),
                        sh.get("poste", ""), sh.get("pauses", ""), fmt_h(hours)]})
            table["rows"].append({"iid": None, "tag": "total", "values": ["TOTAL", "", "", "", "", "", fmt_h(total)]})
            table["note"] = "Contrat : %s par semaine. Double-clic sur une vacation pour modifier l'affectation." % fmt_h(number(emp.get("heures_semaine"), 35.0))
        return table

    def _view_title(self, mode, scope, d0, d1):
        if mode == "Jour":
            span = "%s %s" % (DAYS_FR_LONG[d0.weekday()], fmt_date(d0))
        elif mode == "Semaine":
            span = "Semaine %d — du %s au %s" % (d0.isocalendar()[1], fmt_date(d0), fmt_date(d1))
        else:
            span = "%s %d" % (MONTHS_FR[d0.month - 1], d0.year)
        return "%s — %s" % (scope, span)

    def _refresh_schedule_view(self):
        tree = getattr(self, "hr_tree", None)
        if tree is None:
            return
        try:
            if not tree.winfo_exists():
                return
        except tk.TclError:
            return
        ref = parse_date(self.hr_view_date.get())
        if not ref:
            ref = date.today()
            self.hr_view_date.set(fmt_date(ref))
        mode, scope = self.hr_view_mode.get(), self.hr_view_scope.get()
        if scope != TEAM_SCOPE and scope not in self._planning_labels():
            scope = TEAM_SCOPE
            self.hr_view_scope.set(scope)
        try:
            self.hr_scope_combo.configure(values=[TEAM_SCOPE] + self._planning_labels())
        except (AttributeError, tk.TclError):
            pass
        d0, d1 = self._range_for(mode, ref)
        table = self._schedule_table(mode, scope, d0, d1)
        self.hr_view_title.config(text=self._view_title(mode, scope, d0, d1))
        names = [c[0] for c in table["columns"]]
        tree.configure(columns=names)
        for name, width in table["columns"]:
            tree.heading(name, text=name)
            tree.column(name, width=width, minwidth=30, anchor="w" if name in ("Agent", "Mission", "Pauses") else "center", stretch=False)
        tree.delete(*tree.get_children())
        for n, row in enumerate(table["rows"]):
            iid = row["iid"] or "r%d" % n
            tree.insert("", "end", iid=iid, values=row["values"], tags=(row["tag"],) if row["tag"] else ())
        if not self.hr_schedule:
            self.hr_note.config(text="Aucun planning généré : renseignez la période puis cliquez sur « Générer le planning ».")
        else:
            self.hr_note.config(text=table["note"])
        # Frise horaire pour la vue « Jour » de l'équipe
        if mode == "Jour" and scope == TEAM_SCOPE and self.hr_schedule:
            self._draw_day_gantt(d0)
        else:
            self.hr_gantt.pack_forget()
        self._refresh_schedule_summary()

    def _draw_day_gantt(self, day):
        canvas = self.hr_gantt
        canvas.pack(fill="x", padx=14, pady=(0, 10))
        canvas.delete("all")
        items = [(i, s, e, sh) for i, s, e, sh in parsed_shifts(self.hr_schedule) if s.date() == day or (s.date() < day <= (e - timedelta(minutes=1)).date())]
        rows = []
        for i, s, e, sh in items:
            name = sh.get("agent") or "⚠ Non pourvu"
            if name not in rows:
                rows.append(name)
        row_h, left, top = 22, 170, 24
        width = max(canvas.winfo_width(), 900)
        canvas.configure(height=top + row_h * max(len(rows), 1) + 8)
        plot_w = width - left - 20
        origin = datetime.combine(day, datetime.min.time())
        for hour in range(0, 25, 2):
            x = left + plot_w * hour / 24.0
            canvas.create_line(x, top - 4, x, top + row_h * max(len(rows), 1), fill=self.colors["border"])
            canvas.create_text(x, 10, text="%02dh" % hour, fill=self.colors["muted"], font=("Consolas", 8))
        palette = [self.colors["primary"], self.colors["success"], self.colors["warning"], "#D946EF", "#1BAA56", "#7CFFB2"]
        missions = sorted({sh.get("mission", "") for _, _, _, sh in items})
        for r, name in enumerate(rows):
            y = top + r * row_h
            canvas.create_text(left - 8, y + row_h / 2, text=name[:26], anchor="e", fill=self.colors["text"], font=("Consolas", 8))
            for i, s, e, sh in items:
                if (sh.get("agent") or "⚠ Non pourvu") != name:
                    continue
                a = max((s - origin).total_seconds() / 3600.0, 0.0)
                b = min((e - origin).total_seconds() / 3600.0, 24.0)
                color = self.colors["danger"] if not sh.get("agent") else palette[missions.index(sh.get("mission", "")) % len(palette)]
                x1, x2 = left + plot_w * a / 24.0, left + plot_w * b / 24.0
                canvas.create_rectangle(x1, y + 3, x2, y + row_h - 3, fill=color, outline="")
                if x2 - x1 > 46:
                    canvas.create_text((x1 + x2) / 2, y + row_h / 2, text=self._short_poste(sh.get("poste", "")), fill="white", font=("Consolas", 8, "bold"))

    def _all_alerts(self):
        self._sync_hr_settings()
        alerts, stats = audit_schedule(self.employees, self.hr_schedule, self.hr_settings)
        for emp in self.employees:
            if not emp.get("planning", True):
                continue
            for cert in emp.get("certifications", []):
                end_v, next_r, status, level = cert_status(cert)
                if level == 2:
                    alerts.append(("Erreur", employee_label(emp), "%s : %s (fin de validité %s, recyclage %s)." % (
                        cert.get("nom", ""), status.lower(), fmt_date(end_v) if end_v else "—", fmt_date(next_r) if next_r else "—")))
                elif level == 1:
                    alerts.append(("Alerte", employee_label(emp), "%s : %s (échéance %s)." % (
                        cert.get("nom", ""), status.lower(), fmt_date(min([d for d in (end_v, next_r) if d] or [date.today()])))))
        order = {"Erreur": 0, "Alerte": 1, "Info": 2}
        alerts.sort(key=lambda a: (order.get(a[0], 9), a[1]))
        return alerts, stats

    def _summary_rows(self, stats):
        emp_by_label = {employee_label(e): e for e in self.employees}
        all_days = [s.date() for _, s, _, _ in parsed_shifts(self.hr_schedule)]
        span = (max(all_days) - min(all_days)).days + 1 if all_days else 0
        rows = []
        for label in self._planning_labels():
            emp = emp_by_label.get(label, {})
            st = stats.get(label)
            if st:
                posts = ", ".join("%s×%d" % (self._short_poste(k), v) for k, v in sorted(st["postes"].items()))
                rows.append([label, emp.get("service", ""), "%g" % number(emp.get("heures_semaine"), 35.0), fmt_h(st["heures"]),
                             st["vacations"], len(st["jours"]), max(span - len(st["jours"]), 0), fmt_h(st["hs"]), posts])
            else:
                rows.append([label, emp.get("service", ""), "%g" % number(emp.get("heures_semaine"), 35.0), "0 h", 0, 0, span, "0 h", "Non positionné"])
        return rows

    def _refresh_schedule_summary(self):
        alerts, stats = self._all_alerts()
        try:
            self.hr_summary_tree.delete(*self.hr_summary_tree.get_children())
            for n, row in enumerate(self._summary_rows(stats)):
                self.hr_summary_tree.insert("", "end", iid="a%d" % n, values=row)
            self.hr_alert_tree.delete(*self.hr_alert_tree.get_children())
            if not alerts:
                self.hr_alert_tree.insert("", "end", values=("OK", "—", "Aucun dépassement détecté."))
            for n, (level, who, text) in enumerate(alerts):
                self.hr_alert_tree.insert("", "end", iid="c%d" % n, values=(level, who, text), tags=(level,))
        except (AttributeError, tk.TclError):
            pass

    # ---- Rotations & horaires proposés ----------------------------------------------

    def propose_rotations(self):
        self._collect_flags()
        d0, d1 = parse_date(self.hr_settings.get("debut", "")), parse_date(self.hr_settings.get("fin", ""))
        if not self.rows:
            messagebox.showinfo("Aucun événement", "Aucune mission n'est saisie dans le Bloc I.")
            return
        if not d0 or not d1:
            self._period_from_missions()
            self._sync_hr_settings()
            d0, d1 = parse_date(self.hr_settings.get("debut", "")), parse_date(self.hr_settings.get("fin", ""))
        if not d0 or not d1:
            return
        weeks = max(((d1 - d0).days + 1) / 7.0, 1.0)
        options = [("A", 8.0), ("B", min(number(self.hr_settings.get("max_jour"), 10.0), 12.0))]
        planning_emps = [e for e in self.employees if e.get("planning", True) and e.get("disponibilite") in ("Disponible", "En mission")]
        lines = []
        for key, hours in options:
            local = dict(self.hr_settings)
            local["vacation_max"] = str(hours)
            sched = HRScheduler(self.employees, local, self.rows)
            groups = sched.build_shifts(d0, d1)
            lines.append("OPTION %s — vacations de %s maximum" % (key, fmt_h(hours)))
            lines.append("-" * 78)
            per_profile = {}
            for g in groups:
                per_profile[g["profil"]] = per_profile.get(g["profil"], 0.0) + g["eff"] * g["need"]
            for profil, man_hours in sorted(per_profile.items()):
                weekly = man_hours / weeks
                pool = [e for e in planning_emps if agent_matches_profile(e, profil)]
                avg = (sum(number(e.get("heures_semaine"), 35.0) for e in pool) / len(pool)) if pool else 35.0
                need = int(math.ceil(weekly / avg - 1e-9)) if avg else 0
                status = "OK" if len(pool) >= need else "MANQUE %d agent(s)" % (need - len(pool))
                lines.append("• %s : %s d'heures effectives / semaine → %d agent(s) à %s (disponibles : %d) — %s"
                             % (profil or "Profil non précisé", fmt_h(weekly), need, fmt_h(avg), len(pool), status))
            shown = set()
            for row in self.rows:
                s, e = parse_datetime(row.get("debut")), parse_datetime(row.get("fin"))
                if not s or not e or row.get("mission") in shown:
                    continue
                shown.add(row.get("mission"))
                cut_end = min(e, s + timedelta(hours=24))
                chunks = sched.split_mission(s, cut_end)
                horaires = "  |  ".join("%s-%s" % (fmt_hm(a), fmt_hm(b)) for a, b in chunks)
                lines.append("  ↳ %s : %d vacation(s) par cycle de 24 h → %s" % (row.get("mission", ""), len(chunks), horaires))
            lines.append("")
        lines += [
            "ROTATIONS RECOMMANDÉES",
            "-" * 78,
            "• Rotation des postes : à chaque vacation, l'agent reçoit le poste qu'il a le moins occupé (aucune fixation sur un même poste).",
            "• Rotation des horaires : alterner dans le sens Matin → Après-midi → Nuit afin de conserver 11 h de repos entre deux vacations.",
            "• Cycle conseillé : 5 jours travaillés / 2 jours de repos, avec au moins 35 h de repos consécutives par semaine glissante.",
            "• Pauses : 20 min minimum dès 6 h de travail continu (2 pauses au-delà de 9 h), placées en milieu de vacation.",
            "• Les heures effectives par agent sont plafonnées à leur contrat ; les heures supplémentaires ne sont utilisées qu'en dernier recours.",
        ]
        win = tk.Toplevel(self)
        win.title("Rotations et horaires proposés")
        win.transient(self)
        win.geometry("900x560")
        win.configure(bg=self.colors["surface"])
        text = tk.Text(win, wrap="word", bg=self.colors["surface"], fg=self.colors["text"], font=("Consolas", 10), relief="flat")
        text.pack(fill="both", expand=True, padx=14, pady=(14, 6))
        text.insert("1.0", "\n".join(lines))
        text.config(state="disabled")
        buttons = tk.Frame(win, bg=self.colors["surface"])
        buttons.pack(fill="x", padx=14, pady=(0, 14))

        def apply(hours):
            self.hr_vars["vacation_max"].set(("%g" % hours))
            win.destroy()
            self.generate_schedule()

        ttk.Button(buttons, text="Fermer", command=win.destroy).pack(side="right")
        ttk.Button(buttons, text="Appliquer l'option B et générer", command=lambda: apply(options[1][1])).pack(side="right", padx=8)
        ttk.Button(buttons, text="Appliquer l'option A et générer", style="Primary.TButton", command=lambda: apply(options[0][1])).pack(side="right")

    # ------------------------------------------------------------------
    # Export PDF de l'emploi du temps (bibliothèque standard uniquement)
    # ------------------------------------------------------------------

    def export_schedule_pdf(self, full=False):
        if not self.hr_schedule:
            messagebox.showinfo("Aucun planning", "Générez d'abord un planning.")
            return
        path = filedialog.asksaveasfilename(
            title="Enregistrer l'emploi du temps en PDF", defaultextension=".pdf",
            filetypes=[("Fichier PDF", "*.pdf"), ("Tous les fichiers", "*.*")],
            initialfile="Emploi_du_temps_Gergovie.pdf")
        if not path:
            return
        self._sync_hr_settings()
        head = ["Gergovie Sécurité — Emploi du temps", "Dossier : %s — %s" % (
            self.project.get("client") or "sans client", self.project.get("event") or "sans événement")]
        sections = []
        try:
            if not full:
                mode, scope = self.hr_view_mode.get(), self.hr_view_scope.get()
                ref = parse_date(self.hr_view_date.get()) or date.today()
                d0, d1 = self._range_for(mode, ref)
                sections.append(self._pdf_section(self._schedule_table(mode, scope, d0, d1), self._view_title(mode, scope, d0, d1), head))
            else:
                shifts = parsed_shifts(self.hr_schedule)
                first = min(s.date() for _, s, _, _ in shifts)
                last = max(s.date() for _, s, _, _ in shifts)
                monday = monday_of(first)
                while monday <= last:
                    sunday = monday + timedelta(days=6)
                    sections.append(self._pdf_section(
                        self._schedule_table("Semaine", TEAM_SCOPE, monday, sunday),
                        self._view_title("Semaine", TEAM_SCOPE, monday, sunday), head))
                    monday += timedelta(days=7)
                for label in self._planning_labels():
                    sections.append(self._pdf_section(
                        self._schedule_table("Mois", label, first, last),
                        "Emploi du temps individuel — %s (du %s au %s)" % (label, fmt_date(first), fmt_date(last)), head))
            alerts, stats = self._all_alerts()
            sum_cols = [("Agent", 130), ("Service", 110), ("Contrat h/sem", 70), ("Heures planifiées", 85), ("Vacations", 60),
                        ("Jours travaillés", 75), ("Jours de repos", 70), ("Heures sup.", 65), ("Postes occupés", 150)]
            sections.append({"title": "Synthèse des heures par agent", "subtitle": head, "columns": sum_cols,
                             "rows": [{"values": r, "tag": ""} for r in self._summary_rows(stats)], "notes": []})
            sections.append({"title": "Contrôles réglementaires", "subtitle": head,
                             "columns": [("Niveau", 60), ("Agent / mission", 170), ("Contrôle", 540)],
                             "rows": [{"values": [a, b, c], "tag": "unfilled" if a == "Erreur" else ("hs" if a == "Alerte" else "")} for a, b, c in alerts]
                             or [{"values": ["OK", "—", "Aucun dépassement détecté."], "tag": ""}],
                             "notes": ["Références : Code du travail L3121-16, L3121-18, L3121-20, L3121-22, L3122-6, L3131-1, L3132-2."]})
            self._write_tables_pdf(path, sections)
            messagebox.showinfo("PDF créé", "L'emploi du temps a été exporté :\n" + path)
        except (OSError, ValueError) as error:
            messagebox.showerror("Erreur PDF", str(error))

    @staticmethod
    def _pdf_section(table, title, head):
        return {"title": title, "subtitle": head, "columns": table["columns"],
                "rows": [{"values": r["values"], "tag": r["tag"]} for r in table["rows"]],
                "notes": [table["note"]] if table.get("note") else []}

    def _write_tables_pdf(self, path, sections):
        """PDF paysage A4 avec tableaux paginés, sans bibliothèque externe."""
        page_w, page_h, margin = 842, 595, 24
        usable = page_w - 2 * margin
        pages = []

        def clean(text):
            text = str(text).replace("⚠", "!").replace("→", "->").replace("↳", ">").replace("•", "-").replace("—", "-").replace("–", "-")
            text = text.replace("’", "'").replace("×", "x").replace("≤", "<=").replace("≥", ">=").replace("\u202f", " ").replace("\u00a0", " ")
            text = text.encode("cp1252", "replace").decode("cp1252")
            return text.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")

        def put(cmds, x, y, text, size=8, bold=False, color=(0, 0, 0)):
            cmds.append("%.2f %.2f %.2f rg BT /%s %d Tf %.2f %.2f Td (%s) Tj ET" % (
                color[0], color[1], color[2], "F2" if bold else "F1", size, x, y, clean(text)))

        def fit(text, width, size):
            limit = max(1, int((width - 5) / (size * 0.52)))
            text = str(text)
            return text if len(text) <= limit else text[:max(limit - 1, 1)] + "."

        colors = {"unfilled": (0.8, 0.1, 0.1), "hs": (0.8, 0.3, 0.0), "repos": (0.5, 0.5, 0.5), "bad": (0.8, 0.1, 0.1),
                  "warn": (0.8, 0.3, 0.0), "holiday": (0.1, 0.3, 0.8), "muted": (0.5, 0.5, 0.5), "total": (0.1, 0.5, 0.3)}
        palette = {"plum": (0.21, 0.13, 0.24), "plum2": (0.10, 0.08, 0.15),
                   "green": (0.22, 1.0, 0.53), "line": (0.72, 0.66, 0.77),
                   "row_a": (0.97, 0.96, 0.98), "row_b": (0.92, 0.89, 0.94)}
        cmds = []
        y = page_h - margin

        def nouvelle_page(suite=False):
            nonlocal cmds, y
            if cmds:
                pages.append(cmds)
            cmds = []
            y = page_h - margin
            titre = sections[0]["title"] if sections else "Rapport Gergovie Sécurité"
            cmds.append("%.3f %.3f %.3f rg %.2f %.2f %.2f 21 re f" % (palette["plum2"] + (margin, y - 21, usable)))
            put(cmds, margin + 8, y - 15, titre + (" (suite)" if suite else ""), 12, True, palette["green"])
            y -= 25
            if not suite and sections:
                for line in sections[0].get("subtitle", []):
                    put(cmds, margin + 2, y - 7, line, 8, False, (0.30, 0.27, 0.33))
                    y -= 10
            y -= 3

        def ajouter_bandeau_section(section, cols, widths, size):
            nonlocal y
            section_color = section.get("color_rgb", palette["plum"])
            badge = str(section.get("icon", "•"))[:2]
            if section.get("shield", False):
                sx, sy = margin + 4, y - 1
                cmds.append("%.3f %.3f %.3f rg %.2f %.2f m %.2f %.2f l %.2f %.2f l %.2f %.2f l %.2f %.2f l %.2f %.2f l %.2f %.2f l h f" % (
                    section_color + (sx, sy, sx + 10, sy, sx + 10, sy - 4,
                                     sx + 8.5, sy - 8, sx + 5, sy - 12,
                                     sx + 1.5, sy - 8, sx, sy - 4)
                ))
            else:
                cmds.append("%.3f %.3f %.3f rg %.2f %.2f 12 12 re f" % (section_color + (margin + 3, y - 12)))
                put(cmds, margin + 5, y - 9, badge, 6, True, (1, 1, 1))
            put(cmds, margin + 19, y - 9, section.get("heading", section.get("title", "")), 9, True, palette["plum"])
            y -= 13
            rh = 13
            cmds.append("%.3f %.3f %.3f rg %.2f %.2f %.2f %.2f re f" % (palette["plum"] + (margin, y - rh, usable, rh)))
            x = margin
            for (name, _), width in zip(cols, widths):
                put(cmds, x + 3, y - rh + 3.5, fit(name, width, size), size, True, palette["green"])
                x += width
            y -= rh

        if sections:
            nouvelle_page()
        for section in sections:
            cols = section["columns"]
            total_w = float(sum(c[1] for c in cols)) or 1.0
            widths = [c[1] / total_w * usable for c in cols]
            size = 8 if len(cols) <= 12 else 6
            rows = section["rows"] or [{"values": [""] * len(cols), "tag": ""}]
            rh = 13
            # Chaque poste commence sur la page courante si son bandeau et son
            # en-tête tiennent. Les vacations remplissent ensuite l'espace restant.
            if y - 26 - rh < margin + 22:
                nouvelle_page(suite=True)
            ajouter_bandeau_section(section, cols, widths, size)
            index = 0
            while index < len(rows):
                if y - rh < margin + 22:
                    nouvelle_page(suite=True)
                    ajouter_bandeau_section(dict(section, heading=section.get("heading", section.get("title", "")) + " (suite)"), cols, widths, size)
                row = rows[index]
                row_color = palette["row_a"] if index % 2 == 0 else palette["row_b"]
                cmds.append("%.3f %.3f %.3f rg %.2f %.2f %.2f %.2f re f" % (row_color + (margin, y - rh, usable, rh)))
                color = colors.get(row.get("tag", ""), (0.12, 0.10, 0.14))
                x = margin
                for value, width in zip(row["values"], widths):
                    put(cmds, x + 3, y - rh + 3.5, fit(value, width, size), size, row.get("tag") == "total", color)
                    x += width
                cmds.append("%.3f %.3f %.3f RG 0.35 w %.2f %.2f m %.2f %.2f l S" % (palette["line"] + (margin, y - rh, margin + usable, y - rh)))
                y -= rh
                index += 1
            y -= 4  # fine séparation entre les postes
            for note in section.get("notes", []):
                if y < margin + 20:
                    nouvelle_page(suite=True)
                put(cmds, margin + 2, y - 7, note, 7, False, (0.35, 0.35, 0.35))
                y -= 9
        if cmds:
            pages.append(cmds)
        total = len(pages)
        for n, cmds in enumerate(pages, start=1):
            put(cmds, margin, 16, "Gergovie Sécurité — %s" % FOOTER, 7, False, (0.45, 0.45, 0.45))
            put(cmds, page_w - margin - 60, 16, "Page %d / %d" % (n, total), 7, False, (0.45, 0.45, 0.45))
        if not pages:
            pages.append([])

        objects = []

        def add(data):
            objects.append(data)
            return len(objects)

        catalog_id = add(b"")
        pages_id = add(b"")
        f1 = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
        f2 = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>")
        page_ids = []
        for cmds in pages:
            stream = "\n".join(cmds).encode("cp1252", "replace")
            sid = add(b"<< /Length " + str(len(stream)).encode("ascii") + b" >>\nstream\n" + stream + b"\nendstream")
            page_ids.append(add(
                ("<< /Type /Page /Parent %d 0 R /MediaBox [0 0 %d %d] /Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> /Contents %d 0 R >>"
                 % (pages_id, page_w, page_h, f1, f2, sid)).encode("ascii")))
        objects[pages_id - 1] = ("<< /Type /Pages /Kids [%s] /Count %d >>" % (" ".join("%d 0 R" % p for p in page_ids), len(page_ids))).encode("ascii")
        objects[catalog_id - 1] = ("<< /Type /Catalog /Pages %d 0 R >>" % pages_id).encode("ascii")
        pdf = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
        offsets = []
        for number_, obj in enumerate(objects, start=1):
            offsets.append(len(pdf))
            pdf.extend(("%d 0 obj\n" % number_).encode("ascii"))
            pdf.extend(obj)
            pdf.extend(b"\nendobj\n")
        xref = len(pdf)
        pdf.extend(("xref\n0 %d\n" % (len(objects) + 1)).encode("ascii"))
        pdf.extend(b"0000000000 65535 f \n")
        for offset in offsets:
            pdf.extend(("%010d 00000 n \n" % offset).encode("ascii"))
        pdf.extend(("trailer\n<< /Size %d /Root %d 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objects) + 1, catalog_id, xref)).encode("ascii"))
        with open(path, "wb") as file:
            file.write(pdf)




