        self.evenements = []
        self.next_vacation_id = 1

        # États d'édition
        self.agent_en_cours_edition = None
        self.vacation_en_cours_edition = None
        self.indisponibilites = []
        self.next_indisponibilite_id = 1
        self.agents_selectionnes_planning = []
        self.mode_vue_planning = "Semaine"
        self.date_reference_planning = datetime_module.date.today()
        self.historique_actions = []
        self.index_historique_actions = -1
        self._etat_historique_en_cours = False

