    def ajouter_defilement_treeview(self, parent, tree, horizontal=False):
        conteneur = ttk.Frame(parent)
        tree.pack_forget()
        tree.pack(in_=conteneur, side="left", fill="both", expand=True)
        conteneur.pack(fill="both", expand=True)
        return conteneur

    def activer_defilement_souris(self, widget):
        def scroll(event):
            try:
                widget.yview_scroll(int(-1 * (event.delta / 120)), "units")
            except Exception:
                pass
        widget.bind("<MouseWheel>", scroll, add="+")
        widget.bind("<Button-4>", lambda e: widget.yview_scroll(-3, "units"), add="+")
        widget.bind("<Button-5>", lambda e: widget.yview_scroll(3, "units"), add="+")

    @staticmethod
    def _icone_profil_agent(agent):
        return "👤"

    def _selectionner_carte_profil(self, agent_id):
        iid = str(agent_id)
        if not self.tree_rh.exists(iid):
            return
        self.tree_rh.selection_set(iid)
        self.tree_rh.focus(iid)
        self.tree_rh.see(iid)
        for identifiant, bouton in self.profile_card_buttons.items():
            couleur = "#D946EF" if str(identifiant) == iid else "#39FF88"
            bouton.configure(highlightbackground=couleur, highlightcolor=couleur)
        self.charger_agent_pour_edition()

    def _rafraichir_cartes_profils(self):
        if not hasattr(self, "profile_strip") or not self.profile_strip.winfo_exists():
            return
        for widget in self.profile_strip.winfo_children():
            widget.destroy()
        self.profile_card_buttons = {}
        if not self.agents:
            tk.Label(self.profile_strip, text="Ajoutez un agent pour créer son profil.",
                     bg="#100D18", fg="#A9DDB7", font=("Segoe UI", 9)).pack(anchor="w", padx=12, pady=16)
        selected = self.tree_rh.selection()[0] if self.tree_rh.selection() else None
        for agent in self.agents:
            identifiant = agent.get("id", 0)
            avatar = tk.Frame(
                self.profile_strip, width=154, height=124,
                bg="#191323", highlightthickness=2,
                highlightbackground="#D946EF" if str(identifiant) == selected else "#35223C",
                cursor="hand2",
            )
            avatar.pack_propagate(False)
            avatar.pack(side="left", padx=6, pady=6)
            icon = tk.Label(avatar, text="👤", bg="#191323", fg="#39FF88", font=("Segoe UI Emoji", 25))
            icon.pack(pady=(5, 0))
            name = tk.Label(avatar, text=str(agent.get("nom", "Agent")), bg="#191323", fg="#E8FFF0",
                            font=("Segoe UI", 10, "bold"), anchor="center")
            name.pack(fill="x", padx=5)
            subtitle = "{} · {}".format(agent.get("service", "Service non précisé"), agent.get("tfp_aps", "Profil agent"))
            details = tk.Label(avatar, text=subtitle, bg="#191323", fg="#A9DDB7",
                               font=("Segoe UI", 8), wraplength=138, justify="center")
            details.pack(fill="x", padx=5, pady=(1, 4))
            self.profile_card_buttons[identifiant] = avatar
            for widget in (avatar, icon, name, details):
                widget.bind("<Button-1>", lambda event, agent_id=identifiant: self._selectionner_carte_profil(agent_id), add="+")
                widget.bind("<Enter>", lambda event, card=avatar: self._survol_carte_profil(card, True), add="+")
                widget.bind("<Leave>", lambda event, card=avatar, agent_id=identifiant: self._survol_carte_profil(card, False, agent_id), add="+")
        self.profile_strip.update_idletasks()
        self.profile_canvas.configure(scrollregion=self.profile_canvas.bbox("all"))

    def _survol_carte_profil(self, card, active, agent_id=None):
        background = "#281532" if active else "#191323"
        selected = bool(self.tree_rh.selection() and str(agent_id) == self.tree_rh.selection()[0])
        border = "#D946EF" if active or selected else "#35223C"
        card.configure(bg=background, highlightbackground=border)
        for child in card.winfo_children():
            child.configure(bg=background)

