    def construire_onglet_rh(self):
        paned = ttk.PanedWindow(self.tab_rh, orient="horizontal")
        paned.pack(fill="both", expand=True)
        def adapt_paned_orientation(event):
            desired = "vertical" if event.width < 1050 else "horizontal"
            if str(paned.cget("orient")) != desired:
                paned.configure(orient=desired)
        paned.bind("<Configure>", adapt_paned_orientation, add="+")

        frame_form = ttk.LabelFrame(paned, text=" Saisie & Modification Agent (TFP APS) ", padding=12)
        paned.add(frame_form, weight=1)

        self.lbl_mode_rh = ttk.Label(frame_form, text="🟢 Mode : Nouvel Agent", style="Mode.TLabel")
        self.lbl_mode_rh.grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 10))

        fields = [
            ("Nom :", "nom", 1, 0),
            ("Prénom :", "prenom", 1, 1),
            ("Service / Affectation :", "service", 2, 0),
            ("N° Carte Professionnelle :", "carte_pro", 2, 1),
            ("Validité Carte Pro (AAAA-MM-JJ) :", "validite_carte", 3, 0),
            ("Habilitation (Saisie libre ou choix) :", "tfp_aps", 3, 1),
            ("Autres habilitations :", "hab_supp", 4, 0),
            ("Durée formation initiale (heures) :", "duree_forma", 4, 1),
            ("Dernier Recyclage / MAC (AAAA-MM-JJ) :", "date_mac", 5, 0),
        ]

        self.inputs_rh = {}
        for label_text, key, row, col in fields:
            f_box = ttk.Frame(frame_form)
            f_box.grid(row=row, column=col, sticky="ew", padx=6, pady=6)
            frame_form.columnconfigure(col, weight=1)

            ttk.Label(f_box, text=label_text, style="Form.TLabel").pack(anchor="w")
            if key == "tfp_aps":
                cb = ttk.Combobox(f_box, values=["TFP APS", "SSIAP 1", "SSIAP 2", "SSIAP 3", "SST", "Cynophile", "Rondeur / Intervenant"])
                cb.set("TFP APS")
                cb.pack(fill="x", pady=(4, 0))
                self.inputs_rh[key] = cb
            else:
                entry = ttk.Entry(f_box)
                entry.pack(fill="x", pady=(4, 0))
                self.inputs_rh[key] = entry

        btn_box = ttk.Frame(frame_form)
        btn_box.grid(row=6, column=0, columnspan=2, sticky="ew", pady=14, padx=6)

        self.btn_save_rh = ttk.Button(btn_box, text="➕ Enregistrer l'Agent", style="Accent.TButton", command=self.enregistrer_agent)
        self.btn_save_rh.pack(fill="x", pady=3)

        self.btn_cancel_rh = ttk.Button(btn_box, text="❌ Annuler / Réinitialiser", command=self.reinitialiser_formulaire_rh)
        self.btn_cancel_rh.pack(fill="x", pady=3)

        frame_table = ttk.LabelFrame(paned, text=" Registre des Effectifs & Gestion ", padding=12)
        paned.add(frame_table, weight=2)

        self.lbl_alerte_rh = ttk.Label(frame_table, text="✅ Validation des cartes en cours...", style="AlertBanner.TLabel", anchor="center")
        self.lbl_alerte_rh.pack(fill="x", pady=(0, 8))

        toolbar_rh = ttk.Frame(frame_table)
        toolbar_rh.pack(fill="x", pady=(0, 10))

        ttk.Button(toolbar_rh, text="✏️ Modifier l'agent", command=self.charger_agent_pour_edition).pack(side="left", padx=2)
        ttk.Button(toolbar_rh, text="⧉ Dupliquer ses vacations", command=self.dupliquer_vacations_depuis_agent).pack(side="left", padx=4)
        ttk.Button(toolbar_rh, text="🗑️ Supprimer l'agent", style="Danger.TButton", command=self.supprimer_agent_selectionne).pack(side="left", padx=4)
        ttk.Button(toolbar_rh, text="📄 Exporter Registre RH", command=self.exporter_rh_pdf).pack(side="right", padx=2)
        ttk.Label(frame_table, text="Profils des agents — sélectionnez une carte pour modifier un agent", style="SubHeader.TLabel").pack(anchor="w", pady=(0, 4))
        self.profile_canvas = tk.Canvas(frame_table, height=144, bg="#100D18", highlightthickness=0)
        self.profile_canvas.pack(fill="x", pady=(0, 2))
        self.profile_scroll = ttk.Scrollbar(frame_table, orient="horizontal", command=self.profile_canvas.xview)
        self.profile_scroll.pack(fill="x", pady=(0, 6))
        self.profile_canvas.configure(xscrollcommand=self.profile_scroll.set)
        self.profile_strip = tk.Frame(self.profile_canvas, bg="#100D18")
        self.profile_canvas_window = self.profile_canvas.create_window((0, 0), window=self.profile_strip, anchor="nw")
        self.profile_strip.bind("<Configure>", lambda event: self.profile_canvas.configure(scrollregion=self.profile_canvas.bbox("all")))

        columns = ("id", "nom", "service", "tfp_aps", "carte_pro", "validite", "mac", "positionne")
        self.tree_rh = ttk.Treeview(frame_table, columns=columns, show="headings")

        self.tree_rh.heading("id", text="ID")
        self.tree_rh.heading("nom", text="Agent")
        self.tree_rh.heading("service", text="Service")
        self.tree_rh.heading("tfp_aps", text="Habilitation")
        self.tree_rh.heading("carte_pro", text="Carte Pro")
        self.tree_rh.heading("validite", text="Validité Carte Pro")
        self.tree_rh.heading("mac", text="Recyclage MAC")
        self.tree_rh.heading("positionne", text="Sur Planning ?")

        self.tree_rh.column("id", width=40, anchor="center")
        self.tree_rh.column("nom", width=130)
        self.tree_rh.column("service", width=110)
        self.tree_rh.column("tfp_aps", width=110, anchor="center")
        self.tree_rh.column("carte_pro", width=120)
        self.tree_rh.column("validite", width=145, anchor="center")
        self.tree_rh.column("mac", width=95, anchor="center")
        self.tree_rh.column("positionne", width=95, anchor="center")

        self.tree_rh.tag_configure("expired", foreground="#f38ba8")
        self.tree_rh.tag_configure("warning", foreground="#f9e2af")
        self.tree_rh.tag_configure("valid", foreground="#A9DDB7")
        self.tree_rh.tag_configure("stripe_even", background="#100D18")
        self.tree_rh.tag_configure("stripe_odd", background="#15101D")

        self.tree_rh.pack(side="left", fill="both", expand=True)
        self.activer_defilement_souris(self.tree_rh)

        self.tree_rh.bind("<Double-1>", lambda event: self.charger_agent_pour_edition())
        self._rafraichir_cartes_profils()
        ttk.Label(frame_table, text="💡 Double-cliquez sur un agent pour le modifier rapidement.", style="SubHeader.TLabel").pack(anchor="w", pady=(6, 0))

    def reinitialiser_formulaire_rh(self):
        self.agent_en_cours_edition = None
        self.lbl_mode_rh.configure(text="🟢 Mode : Nouvel Agent", foreground="#A3FF5F")
        self.btn_save_rh.configure(text="➕ Enregistrer l'Agent")
        for widget in self.inputs_rh.values():
            if isinstance(widget, ttk.Entry):
                widget.delete(0, tk.END)
            elif isinstance(widget, ttk.Combobox):
                widget.set("TFP APS")

    def charger_agent_pour_edition(self):
        selection = self.tree_rh.selection()
        if not selection:
            messagebox.showwarning("Sélection requise", "Veuillez sélectionner un agent dans le tableau.")
            return

        agent_id = int(selection[0])
        agent = next((a for a in self.agents if a["id"] == agent_id), None)
        if not agent:
            return

        self.agent_en_cours_edition = agent_id
        self.lbl_mode_rh.configure(text=f"✏️ Mode Édition : Agent #{agent_id} ({agent['nom']})", foreground="#39FF88")
        self.btn_save_rh.configure(text="💾 Mettre à jour l'Agent")

        parts = agent["nom"].split(" ", 1)
        nom = parts[0] if parts else ""
        prenom = parts[1] if len(parts) > 1 else ""

        self.inputs_rh["nom"].delete(0, tk.END)
        self.inputs_rh["nom"].insert(0, nom)

        self.inputs_rh["prenom"].delete(0, tk.END)
        self.inputs_rh["prenom"].insert(0, prenom)

        self.inputs_rh["service"].delete(0, tk.END)
        self.inputs_rh["service"].insert(0, agent["service"])

        self.inputs_rh["carte_pro"].delete(0, tk.END)
        self.inputs_rh["carte_pro"].insert(0, agent["carte_pro"])

        self.inputs_rh["validite_carte"].delete(0, tk.END)
        self.inputs_rh["validite_carte"].insert(0, agent["validite"])

        self.inputs_rh["tfp_aps"].delete(0, tk.END)
        self.inputs_rh["tfp_aps"].insert(0, agent["tfp_aps"])

        self.inputs_rh["hab_supp"].delete(0, tk.END)
        self.inputs_rh["hab_supp"].insert(0, agent.get("hab_supp", ""))

        self.inputs_rh["duree_forma"].delete(0, tk.END)
        self.inputs_rh["duree_forma"].insert(0, agent.get("duree_forma", ""))

        self.inputs_rh["date_mac"].delete(0, tk.END)
        self.inputs_rh["date_mac"].insert(0, agent["date_mac"])

    def enregistrer_agent(self):
        nom = self.inputs_rh["nom"].get().strip()
        prenom = self.inputs_rh["prenom"].get().strip()
        validite = self.inputs_rh["validite_carte"].get().strip()

        if not nom or not prenom:
            messagebox.showwarning("Champs requis", "Le nom et le prénom sont obligatoires.")
            return

        nom_complet = f"{nom.upper()} {prenom.capitalize()}"
        habilitation = self.inputs_rh["tfp_aps"].get().strip() or "TFP APS"

        if validite:
            try:
                datetime_module.datetime.strptime(validite, "%Y-%m-%d")
            except ValueError:
                messagebox.showerror("Format Date Incorrect", "La date de validité doit être au format AAAA-MM-JJ (ex: 2026-12-31).")
                return

        if self.agent_en_cours_edition is None:
            agent_id = len(self.agents) + 1 if not self.agents else max(a["id"] for a in self.agents) + 1
            agent_data = {
                "id": agent_id,
                "nom": nom_complet,
                "service": self.inputs_rh["service"].get() or "Général",
                "carte_pro": self.inputs_rh["carte_pro"].get() or "N/A",
                "validite": validite or "Non renseigné",
                "tfp_aps": habilitation,
                "hab_supp": self.inputs_rh["hab_supp"].get() or "Aucune",
                "duree_forma": self.inputs_rh["duree_forma"].get() or "175h (Standard)",
                "date_mac": self.inputs_rh["date_mac"].get() or "À jour",
                "positionne": "Non"
            }
            self.agents.append(agent_data)
            messagebox.showinfo("Succès", f"Agent {nom_complet} enregistré avec habilitation '{habilitation}'.")
        else:
            agent = next((a for a in self.agents if a["id"] == self.agent_en_cours_edition), None)
            if agent:
                agent["nom"] = nom_complet
                agent["service"] = self.inputs_rh["service"].get() or "Général"
                agent["carte_pro"] = self.inputs_rh["carte_pro"].get() or "N/A"
                agent["validite"] = validite or "Non renseigné"
                agent["tfp_aps"] = habilitation
                agent["hab_supp"] = self.inputs_rh["hab_supp"].get() or "Aucune"
                agent["duree_forma"] = self.inputs_rh["duree_forma"].get() or "175h (Standard)"
                agent["date_mac"] = self.inputs_rh["date_mac"].get() or "À jour"

                for ev in self.evenements:
                    if ev["agent_id"] == agent["id"]:
                        ev["agent_nom"] = nom_complet

                messagebox.showinfo("Modifications enregistrées", f"Agent {nom_complet} mis à jour.")

        self.reinitialiser_formulaire_rh()
        self.rafraichir_table_rh()
        self.rafraichir_combos_planning()
        self.rafraichir_liste_agents_planning()
        self.rafraichir_planning()
        self.sauvegarder_automatiquement()

    def supprimer_agent_selectionne(self):
        selection = self.tree_rh.selection()
        if not selection:
            messagebox.showwarning("Sélection requise", "Veuillez sélectionner un agent à supprimer.")
            return

        agent_id = int(selection[0])
        agent = next((a for a in self.agents if a["id"] == agent_id), None)
        if not agent:
            return

        confirm = messagebox.askyesno(
            "Confirmation de suppression",
            f"Êtes-vous sûr de vouloir supprimer l'agent {agent['nom']} ?\n\n"
            "⚠️ Attention : Ses vacations planifiées seront également supprimées du planning."
        )

        if confirm:
            self.agents = [a for a in self.agents if a["id"] != agent_id]
            self.evenements = [ev for ev in self.evenements if ev["agent_id"] != agent_id]
            self.indisponibilites = [x for x in self.indisponibilites if x.get("agent_id") != agent_id]

            if self.agent_en_cours_edition == agent_id:
                self.reinitialiser_formulaire_rh()

            self.rafraichir_table_rh()
            self.rafraichir_combos_planning()
            self.rafraichir_liste_agents_planning()
            self.rafraichir_planning()
            self.sauvegarder_automatiquement()
            messagebox.showinfo("Suppression effectuée", f"L'agent {agent['nom']} a été supprimé.")

    def dupliquer_vacations_depuis_agent(self):
        """Part de l'agent RH sélectionné, puis copie ses vacations vers des agents choisis."""
        selection = self.tree_rh.selection()
        if not selection:
            messagebox.showwarning("Agent requis", "Cliquez d'abord sur l'agent qui possède la vacation à copier.")
            return
        try:
            agent_id = int(selection[0])
        except (TypeError, ValueError):
            messagebox.showwarning("Agent introuvable", "Sélectionnez un agent valide dans le registre RH.")
            return
        agent = next((a for a in self.agents if a.get("id") == agent_id), None)
        if not agent:
            return
        vacations = [ev for ev in self.evenements if ev.get("agent_id") == agent_id]
        if not vacations:
            messagebox.showinfo("Aucune vacation", f"{agent.get('nom', 'Cet agent')} n'a aucune vacation à dupliquer.")
            return

        fenetre = tk.Toplevel(self)
        fenetre.title("Dupliquer les vacations de l'agent")
        fenetre.transient(self)
        fenetre.grab_set()
        fenetre.configure(bg="#100D18")
        vacations_triees = sorted(vacations, key=lambda x: (str(x.get("date", "")), str(x.get("heure_debut", ""))))
        autres_agents = [a for a in self.agents if a.get("id") != agent_id]
        hauteur_vacations = min(150, max(48, min(len(vacations_triees), 6) * 25))
        hauteur_agents = min(150, max(48, min(len(autres_agents), 6) * 25))
        fenetre.geometry(f"520x{220 + hauteur_vacations + hauteur_agents}")
        fenetre.minsize(520, 220 + hauteur_vacations + hauteur_agents)
        fenetre.resizable(False, False)
        self._centrer_fenetre(fenetre)
        ttk.Label(
            fenetre,
            text=f"Agent source : {agent.get('nom', '')}\nChoisissez une ou plusieurs vacations, puis les agents destinataires.",
            justify="left", padding=12
        ).pack(anchor="w")

        cadre_vacations = ttk.LabelFrame(fenetre, text="Vacations à copier · Ctrl ou Maj pour plusieurs", padding=6, height=hauteur_vacations)
        cadre_vacations.pack(fill="both", expand=True, padx=12, pady=(4, 8))
        cadre_vacations.pack_propagate(False)
        liste_vacations = tk.Listbox(
            cadre_vacations, selectmode=tk.EXTENDED,
            height=max(2, min(len(vacations_triees), 6)), exportselection=False,
            bg="#15101D", fg="#E8FFF0", selectbackground="#D946EF",
            selectforeground="#FFFFFF", relief="flat", highlightthickness=0
        )
        scroll_vacations = ttk.Scrollbar(cadre_vacations, orient="vertical", command=liste_vacations.yview)
        liste_vacations.configure(yscrollcommand=scroll_vacations.set)
        liste_vacations.pack(side="left", fill="both", expand=True)
        scroll_vacations.pack(side="right", fill="y")
        for ev in vacations_triees:
            d = ev.get("date")
            date_txt = d.strftime("%d/%m/%Y") if isinstance(d, (datetime_module.date, datetime_module.datetime)) else str(d)
            liste_vacations.insert(tk.END, f"{date_txt} · {ev.get('poste', '')} · {ev.get('heure_debut', '')}-{ev.get('heure_fin', '')}")

        cadre_agents = ttk.LabelFrame(fenetre, text="Agents destinataires", padding=6, height=hauteur_agents)
        cadre_agents.pack(fill="both", expand=True, padx=12, pady=(0, 8))
        cadre_agents.pack_propagate(False)
        canvas_agents = tk.Canvas(cadre_agents, highlightthickness=0, bg="#100D18")
        scroll_agents = ttk.Scrollbar(cadre_agents, orient="vertical", command=canvas_agents.yview)
        contenu_agents = ttk.Frame(canvas_agents)
        contenu_agents.bind("<Configure>", lambda _event: canvas_agents.configure(scrollregion=canvas_agents.bbox("all")))
        canvas_agents.create_window((0, 0), window=contenu_agents, anchor="nw")
        canvas_agents.configure(yscrollcommand=scroll_agents.set)
        canvas_agents.pack(side="left", fill="both", expand=True)
        scroll_agents.pack(side="right", fill="y")
        variables = []
        for cible in autres_agents:
            var = tk.BooleanVar(value=False)
            variables.append((cible, var))
            ttk.Checkbutton(contenu_agents, text=f"{cible.get('nom', '')} (#{cible.get('id')})", variable=var).pack(anchor="w", pady=2)

        def confirmer():
            indices = liste_vacations.curselection()
            cibles = [cible for cible, var in variables if var.get()]
            if not indices:
                messagebox.showwarning("Vacation requise", "Sélectionnez au moins une vacation de l'agent source.", parent=fenetre)
                return
            if not cibles:
                messagebox.showwarning("Destinataire requis", "Cochez au moins un agent destinataire.", parent=fenetre)
                return
            sources = [vacations_triees[i] for i in indices]
            champs = ("poste", "date", "heure_debut", "heure_fin", "pause_minutes")
            copies = []
            doublons = 0
            self._enregistrer_historique()
            for source in sources:
                for cible in cibles:
                    if any(
                        ev.get("agent_id") == cible.get("id")
                        and all(ev.get(champ) == source.get(champ) for champ in champs)
                        for ev in self.evenements
                    ):
                        doublons += 1
                        continue
                    copie = dict(source)
                    copie["id"] = self.next_vacation_id
                    copie["agent_id"] = cible["id"]
                    copie["agent_nom"] = cible.get("nom", "")
                    self.next_vacation_id += 1
                    self.evenements.append(copie)
                    copies.append(copie)
            if copies:
                self._enregistrer_historique()
                self.recalculer_statuts_positionnement()
                self.rafraichir_table_rh()
                self.sauvegarder_automatiquement()
            fenetre.destroy()
            if copies:
                self._afficher_toutes_les_vacations(copies[0].get("date"))
                self.rafraichir_planning()
            messagebox.showinfo(
                "Duplication terminée",
                f"{len(copies)} vacation(s) copiée(s) vers les agents choisis."
                + (f"\n{doublons} créneau(x) déjà présent(s) ignoré(s)." if doublons else "")
            )

        bas = ttk.Frame(fenetre, padding=(12, 2, 12, 10))
        bas.pack(fill="x")
        ttk.Button(bas, text="Annuler", command=fenetre.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(bas, text="⧉ Dupliquer", style="Primary.TButton", command=confirmer).pack(side="right")

    def generer_agents_exemples(self):
        noms = ["DUPONT", "MARTIN", "BERNARD", "THOMAS", "PETIT", "ROBERT", "RICHARD", "DURAND", "DUBOIS", "MOREAU"]
        prenoms = ["Jean", "Pierre", "Michel", "Sophie", "Lucie", "Antoine", "Sarah", "Alexandre", "Amine", "Yassine"]
        services = ["PC Sécurité", "Filtrage / Accès", "Rondes", "Événementiel", "Secteur Nord"]
        tfp_options = ["TFP APS", "SSIAP 1", "SSIAP 2", "SSIAP 3", "Opérateur Video", "SST / Autre"]
        hab_options = ["SST, HOBO", "SST", "EPI, SST", "Aucune", "Palpation"]

        aujourdhui = datetime_module.date.today()

        for _ in range(5):
            agent_id = len(self.agents) + 1 if not self.agents else max(a["id"] for a in self.agents) + 1
            nom = random.choice(noms)
            prenom = random.choice(prenoms)

            type_date = random.choice(["ok", "expiree", "bientot"])
            if type_date == "expiree":
                date_val = aujourdhui - datetime_module.timedelta(days=random.randint(1, 100))
            elif type_date == "bientot":
                date_val = aujourdhui + datetime_module.timedelta(days=random.randint(1, 25))
            else:
                date_val = aujourdhui + datetime_module.timedelta(days=random.randint(60, 500))

            agent_data = {
                "id": agent_id,
                "nom": f"{nom} {prenom}",
                "service": random.choice(services),
                "carte_pro": f"CARTE-2026-{random.randint(1000, 9999)}",
                "validite": date_val.strftime("%Y-%m-%d"),
                "tfp_aps": random.choice(tfp_options),
                "hab_supp": random.choice(hab_options),
                "duree_forma": f"{random.choice([175, 210, 140])}h",
                "date_mac": f"2026-{random.randint(1,12):02d}-{random.randint(1,28):02d}",
                "positionne": "Non"
            }
            self.agents.append(agent_data)

        self.rafraichir_table_rh()
        self.rafraichir_combos_planning()
        self.rafraichir_liste_agents_planning()
        self.rafraichir_planning()
        self.sauvegarder_automatiquement()
        messagebox.showinfo("Génération Exemple", "5 agents fictifs ont été ajoutés.")

    def rafraichir_table_rh(self):
        for item in self.tree_rh.get_children():
            self.tree_rh.delete(item)

        aujourdhui = datetime_module.date.today()
        cartes_expirees = 0
        cartes_alerte = 0

        for row_index, a in enumerate(self.agents):
            validite_str = a.get("validite", "")
            statut_validite = validite_str
            tag = "valid"

            try:
                date_val = datetime_module.datetime.strptime(validite_str, "%Y-%m-%d").date()
                jours_restants = (date_val - aujourdhui).days

                if jours_restants < 0:
                    statut_validite = f"🚨 {validite_str} (Expirée)"
                    tag = "expired"
                    cartes_expirees += 1
                elif jours_restants <= 30:
                    statut_validite = f"⚠️ {validite_str} ({jours_restants}j)"
                    tag = "warning"
                    cartes_alerte += 1
                else:
                    statut_validite = f"✅ {validite_str}"
            except ValueError:
                statut_validite = f"❓ {validite_str}"

            self.tree_rh.insert("", "end", iid=str(a["id"]), values=(
                a["id"], f"{self._icone_profil_agent(a)} {a['nom']}", a["service"], a["tfp_aps"],
                a["carte_pro"], statut_validite, a["date_mac"], a["positionne"]
            ), tags=(tag, "stripe_even" if row_index % 2 == 0 else "stripe_odd"))

        self._rafraichir_cartes_profils()
        if cartes_expirees > 0 or cartes_alerte > 0:
            msg = f"🚨 ALERTE : {cartes_expirees} carte(s) expirée(s) | ⚠️ {cartes_alerte} carte(s) expirent dans <30 jours"
            couleur = "#f38ba8" if cartes_expirees > 0 else "#f9e2af"
            self.lbl_alerte_rh.configure(text=msg, foreground=couleur)
        else:
            self.lbl_alerte_rh.configure(text="✅ Toutes les cartes professionnelles sont à jour", foreground="#A3FF5F")

