        self.entry_date_vacation = ttk.Entry(frame_creer)
        self.entry_date_vacation.insert(0, datetime_module.date.today().strftime("%Y-%m-%d"))
        self.entry_date_vacation.pack(fill="x", pady=(2, 4))

        ttk.Label(frame_creer, text="Date Fin de Rotation (Optionnelle) :", style="Form.TLabel").pack(anchor="w")
        self.entry_date_fin_rotation = ttk.Entry(frame_creer)
        self.entry_date_fin_rotation.pack(fill="x", pady=(2, 8))

        ttk.Label(frame_creer, text="Heure de début (HH:MM) :", style="Form.TLabel").pack(anchor="w")
        self.entry_heure_debut = ttk.Entry(frame_creer)
        self.entry_heure_debut.insert(0, "08:00")
        self.entry_heure_debut.pack(fill="x", pady=(2, 8))

        ttk.Label(frame_creer, text="Heure de fin (HH:MM) :", style="Form.TLabel").pack(anchor="w")
        self.entry_heure_fin = ttk.Entry(frame_creer)
        self.entry_heure_fin.insert(0, "16:00")
        self.entry_heure_fin.pack(fill="x", pady=(2, 8))

        ttk.Label(frame_creer, text="Pause (minutes) :", style="Form.TLabel").pack(anchor="w")
        self.entry_pause = ttk.Entry(frame_creer)
        self.entry_pause.insert(0, "20")
        self.entry_pause.pack(fill="x", pady=(2, 8))

        ttk.Label(frame_creer, text="Heures travaillées (arrondies à l'unité) :", style="Form.TLabel").pack(anchor="w")
        self.entry_heures = ttk.Entry(frame_creer)
        self.entry_heures.insert(0, "8")
        self.entry_heures.configure(state="readonly")
        self.entry_heures.pack(fill="x", pady=(2, 8))

        def maj_duree(*args):
            try:
                debut = datetime_module.datetime.strptime(self.entry_heure_debut.get().strip(), "%H:%M")
                fin = datetime_module.datetime.strptime(self.entry_heure_fin.get().strip(), "%H:%M")
                minutes = (fin.hour * 60 + fin.minute) - (debut.hour * 60 + debut.minute)
                if minutes < 0:
                    minutes += 24 * 60
                pause = max(0, int(self.entry_pause.get().strip() or "0"))
                heures = round(max(0, minutes - pause) / 60)
                self.entry_heures.configure(state="normal")
                self.entry_heures.delete(0, tk.END)
                self.entry_heures.insert(0, f"{int(heures)}")
                self.entry_heures.configure(state="readonly")
            except Exception:
                pass

        self.entry_heure_debut.bind("<KeyRelease>", maj_duree)
        self.entry_heure_fin.bind("<KeyRelease>", maj_duree)
        self.entry_pause.bind("<KeyRelease>", maj_duree)

