    def exporter_planning_pdf(self, format_force=None):
        evenements = self._evenements_filtres()
        if not evenements:
            messagebox.showwarning("Export impossible", "Aucune vacation ne correspond à la période affichée.")
            return
        extension_defaut = format_force if format_force in ("pdf", "html") else "pdf"
        if format_force == "pdf":
            types_export = [("Fichier PDF", "*.pdf")]
        elif format_force == "html":
            types_export = [("Fichier HTML", "*.html")]
        else:
            types_export = [("Fichier PDF", "*.pdf"), ("Fichier CSV", "*.csv"), ("Fichier HTML", "*.html")]
        fichier = filedialog.asksaveasfilename(
            initialdir=self.docs_dir,
            initialfile=f"Export_Planning_BLOC2_{datetime_module.date.today()}.{extension_defaut}",
            title="Exporter le planning par poste",
            defaultextension="." + extension_defaut,
            filetypes=types_export
        )
        if not fichier:
            return

        mode_actuel = self.filtre_mode.get()
        val_actuelle = self.entry_filtre_val.get().strip()
        groupes = {}
        for ev in evenements:
            groupes.setdefault(str(ev.get("poste") or "Autre"), []).append(ev)
        postes = sorted(groupes, key=str.casefold)
        for poste in postes:
            groupes[poste].sort(key=lambda ev: (str(ev.get("date", "")), str(ev.get("heure_debut", "")), str(ev.get("agent_nom", ""))))

        def date_affichee(value):
            if isinstance(value, (datetime_module.date, datetime_module.datetime)):
                return value.strftime("%d/%m/%Y")
            try:
                return datetime_module.datetime.strptime(str(value), "%Y-%m-%d").strftime("%d/%m/%Y")
            except ValueError:
                return str(value)

        def icone_poste(poste):
            p = poste.casefold()
            if "accueil" in p:
                return "👋", "#D946EF"
            if "ronde" in p:
                return "🛡️", "#5EEAD4"
            if "filtrage" in p or "contrôle" in p or "controle" in p:
                return "🚪", "#39FF88"
            if "inspection" in p or "palpation" in p:
                return "🔎", "#F472B6"
            if "pc" in p:
                return "🖥️", "#A3FF5F"
            return "◆", "#FCEE0A"

        extension = os.path.splitext(fichier)[1].lower()
        if extension == ".csv":
            with open(fichier, "w", newline="", encoding="utf-8-sig") as sortie:
                writer = csv.writer(sortie, delimiter=";")
                writer.writerow(["PLANNING BLOC II", f"Vue {mode_actuel}", val_actuelle])
                for poste in postes:
                    icon, _color = icone_poste(poste)
                    writer.writerow([])
                    writer.writerow([icon, "POSTE", poste, "", "", "", "", f"{len(groupes[poste])} vacation(s)"])
                    writer.writerow(["ID", "Agent", "Poste", "Date", "Début", "Fin", "Heures", "Pause", "Conformité"])
                    for ev in groupes[poste]:
                        writer.writerow([
                            ev.get("id", ""), ev.get("agent_nom", ""), poste, date_affichee(ev.get("date", "")),
                            ev.get("heure_debut", ""), ev.get("heure_fin", ""), ev.get("heures", ""),
                            ev.get("pause", ""), ev.get("conformite", "")
                        ])
