# ============================================================
# MODERNISATION VISUELLE (ajout) — composants graphiques
# Ces composants ne contiennent aucune logique métier.
# ============================================================

def blend_hex(color_a, color_b, ratio):
    """Mélange deux couleurs #RRGGBB (ratio = part de color_a)."""
    try:
        a = [int(color_a[i:i + 2], 16) for i in (1, 3, 5)]
        b = [int(color_b[i:i + 2], 16) for i in (1, 3, 5)]
        return "#%02X%02X%02X" % tuple(int(x * ratio + y * (1 - ratio)) for x, y in zip(a, b))
    except (ValueError, IndexError, TypeError):
        return color_a


# ======================================================================
# GERGOVIE FX — moteur d'animation et de 3D logicielle
# Tkinter pur : aucune dépendance externe (compatible Python 3.7 / EduPython).
#   • FxEngine  : une seule boucle d'animation pour toute l'application
#                 (tweens, easing, qualité adaptative, bouton ON/OFF).
#   • FxMesh    : maillage 3D, éclairage de Lambert, perspective, tri des faces.
#   • FxHero    : bandeau 3D de l'accueil (bouclier holographique, anneaux,
#                 particules, grille de sol, HUD).
#   • FxLogin   : écran de connexion (faux login) avec blason 3D.
#   • FxChart3D : histogrammes et anneau en vraie 3D (rotation à la souris).
# ======================================================================
import random as _fx_random


def fx_clamp(value, low=0.0, high=1.0):
    return low if value < low else (high if value > high else value)


# ---------------------------------------------------------------- easing
def _ease_out_cubic(t):
    t = 1.0 - t
    return 1.0 - t * t * t


def _ease_in_cubic(t):
    return t * t * t


def _ease_in_out_cubic(t):
    return 4.0 * t * t * t if t < 0.5 else 1.0 - pow(-2.0 * t + 2.0, 3) / 2.0


def _ease_out_back(t):
    c1 = 1.70158
    c3 = c1 + 1.0
    return 1.0 + c3 * pow(t - 1.0, 3) + c1 * pow(t - 1.0, 2)


def _ease_out_expo(t):
    return 1.0 if t >= 1.0 else 1.0 - pow(2.0, -10.0 * t)


def _ease_out_elastic(t):
    if t <= 0.0:
        return 0.0
    if t >= 1.0:
        return 1.0
    return pow(2.0, -10.0 * t) * math.sin((t * 10.0 - 0.75) * (2.0 * math.pi / 3.0)) + 1.0


FX_EASE = {
    "linear": lambda t: t,
    "out_cubic": _ease_out_cubic,
    "in_cubic": _ease_in_cubic,
    "in_out": _ease_in_out_cubic,
    "out_back": _ease_out_back,
    "out_expo": _ease_out_expo,
    "out_elastic": _ease_out_elastic,
}


# ---------------------------------------------------------------- couleurs
_FX_RGB_CACHE = {}


def fx_rgb(color):
    """(r, g, b) d'une couleur #RRGGBB, ou None si le format n'est pas géré."""
    found = _FX_RGB_CACHE.get(color, 0)
    if found != 0:
        return found
    rgb = None
    try:
        if isinstance(color, str):
            if color.startswith("#") and len(color) == 7:
                rgb = (int(color[1:3], 16), int(color[3:5], 16), int(color[5:7], 16))
            elif color.lower() == "white":
                rgb = (255, 255, 255)
            elif color.lower() == "black":
                rgb = (0, 0, 0)
    except ValueError:
        rgb = None
    _FX_RGB_CACHE[color] = rgb
    return rgb


def fx_mix(color_a, color_b, t):
    """Interpolation de color_a vers color_b (t = part de color_b)."""
    a, b = fx_rgb(color_a), fx_rgb(color_b)
    if a is None or b is None:
        return color_b if t >= 0.5 else color_a
    t = fx_clamp(t)
    return "#%02X%02X%02X" % (
        int(a[0] + (b[0] - a[0]) * t + 0.5),
        int(a[1] + (b[1] - a[1]) * t + 0.5),
        int(a[2] + (b[2] - a[2]) * t + 0.5),
    )


# ---------------------------------------------------------------- nombres FR
_FX_NUMBER = re.compile(r"-?\d{1,3}(?:[   ]\d{3})+(?:,\d+)?|-?\d+(?:,\d+)?")


def fx_parse_number(text):
    """Repère le premier nombre au format français dans un texte.
    Retourne (début, fin, valeur, décimales) ou None."""
    match = _FX_NUMBER.search(text or "")
    if not match:
        return None
    raw = match.group(0)
    try:
        value = float(raw.replace(" ", "").replace(" ", "").replace(" ", "").replace(",", "."))
    except ValueError:
        return None
    decimals = len(raw.split(",")[1]) if "," in raw else 0
    return match.start(), match.end(), value, decimals


def fx_format_number(value, decimals):
    return ("{:,.%df}" % decimals).format(value).replace(",", "X").replace(".", ",").replace("X", " ")


# ---------------------------------------------------------------- boucle
class FxTask(object):
    __slots__ = ("fn", "owner", "dead", "every", "acc")

    def __init__(self, fn, owner=None, fps=0):
        self.fn = fn
        self.owner = owner
        self.dead = False
        self.every = (1.0 / fps) if fps else 0.0
        self.acc = 0.0

    def cancel(self):
        self.dead = True


class FxEngine(object):
    """Boucle d'animation unique : une seule tâche `after`, arrêtée quand rien ne bouge.

    * ``tween`` / ``add`` : animations ponctuelles ou continues ;
    * ``quality`` : 2 = complet, 1 = réduit, 0 = minimal (adapté en direct selon la fluidité) ;
    * ``enabled`` : interrupteur général (les tweens se terminent alors instantanément).
    """

    TICK_MS = 16
    SCRAMBLE = "01<>/|[]{}#$%&*+=?!"

    def __init__(self, root, clock=None):
        self.root = root
        self.clock = clock or time.perf_counter
        self.enabled = True
        self.quality = 2
        self.toplevel_fade = True
        self.reported = set()
        self._tasks = []
        self._job = None
        self._last = None
        self._ticking = False
        self._load = 8.0
        self._slow = 0
        self._fast = 0
        self._stagger = 0
        self.hold_until = 0.0
        self._ttk_ok = True
        self._ttk_task = None
        self._ttk_final = {}

    # ------------------------------------------------------------ boucle
    def add(self, fn, owner=None, fps=0):
        """Ajoute une tâche fn(dt, now). Elle s'arrête quand elle renvoie False."""
        task = FxTask(fn, owner, fps)
        self._tasks.append(task)
        self._wake()
        return task

    def _wake(self):
        if self._job is None and not self._ticking and self._tasks:
            self._last = self.clock()
            try:
                self._job = self.root.after(self.TICK_MS, self._tick)
            except tk.TclError:
                self._job = None

    def _report(self, error):
        key = repr(error)
        if key not in self.reported and len(self.reported) < 8:
            self.reported.add(key)
            try:
                import traceback
                traceback.print_exc()
            except Exception:
                pass

    def _tick(self):
        self._job = None
        self._ticking = True
        started = self.clock()
        dt = started - self._last if self._last is not None else 0.016
        self._last = started
        dt = min(max(dt, 0.0), 0.1)
        batch, self._tasks = self._tasks, []
        alive = []
        for task in batch:
            if task.dead:
                continue
            owner = task.owner
            if owner is not None:
                try:
                    if not owner.winfo_exists():
                        continue
                except tk.TclError:
                    continue
            step = dt
            if task.every:
                task.acc += dt
                if task.acc < task.every:
                    alive.append(task)
                    continue
                step, task.acc = task.acc, 0.0
            try:
                keep = task.fn(step, started)
            except tk.TclError:
                keep = False
            except Exception as error:
                self._report(error)
                keep = False
            if keep is not False and not task.dead:
                alive.append(task)
        self._tasks = alive + self._tasks
        self._ticking = False
        spent = (self.clock() - started) * 1000.0
        self._adapt(spent)
        if self._tasks:
            delay = max(4, int(self.TICK_MS - spent))
            try:
                self._job = self.root.after(delay, self._tick)
            except tk.TclError:
                self._job = None

    def _adapt(self, spent):
        """Qualité adaptative : on allège les scènes 3D si l'image prend trop de temps."""
        self._load = self._load * 0.92 + spent * 0.08
        if self._load > 20.0:
            self._slow += 1
            self._fast = 0
            if self._slow > 25 and self.quality > 0:
                self.quality -= 1
                self._slow = 0
                self._load = 12.0
        elif self._load < 6.0:
            self._fast += 1
            self._slow = 0
            if self._fast > 400 and self.quality < 2:
                self.quality += 1
                self._fast = 0
        else:
            self._slow = max(0, self._slow - 1)
            self._fast = 0

    # ------------------------------------------------------------ tweens
    def tween(self, duration, update, ease="out_cubic", delay=0.0, on_done=None, owner=None):
        """Anime update(p) avec p de 0 à 1 (après easing) pendant `duration` secondes."""
        ease_fn = FX_EASE.get(ease, _ease_out_cubic) if isinstance(ease, str) else ease
        if not self.enabled or duration <= 0:
            update(1.0)
            if on_done:
                on_done()
            dummy = FxTask(None)
            dummy.dead = True
            return dummy
        state = {"t": -float(delay)}
        update(ease_fn(0.0))         # état initial immédiat (texte à zéro, page décalée, fondu…)

        def step(dt, now):
            if self.holding():
                return True
            state["t"] += dt
            if state["t"] < 0:
                return True
            progress = state["t"] / duration
            if progress >= 1.0:
                update(ease_fn(1.0))
                if on_done:
                    on_done()
                return False
            update(ease_fn(progress))
            return True

        return self.add(step, owner)

    def holding(self):
        """Vrai pendant la séquence de démarrage : les animations d'interface attendent."""
        return self.clock() < self.hold_until

    def stagger(self):
        """Rang d'apparition (0, 1, 2…) pour décaler les entrées d'une page."""
        value = self._stagger
        self._stagger += 1
        return value

    def reset_stagger(self):
        self._stagger = 0

    # ------------------------------------------------------------ widgets
    @staticmethod
    def _cancel_attr(widget, name):
        old = getattr(widget, name, None)
        if old is not None:
            old.cancel()
            setattr(widget, name, None)

    def tween_option(self, widget, option, start, end, duration=0.16, ease="out_cubic"):
        """Fait glisser une option couleur d'un widget (bg, fg…) de start à end."""
        name = "_fx_tw_" + option
        self._cancel_attr(widget, name)

        def update(p):
            widget.configure(**{option: fx_mix(start, end, p)})

        setattr(widget, name, self.tween(duration, update, ease, owner=widget))

    def decode_text(self, widget, text, duration=0.5, ease="linear"):
        """Effet « décryptage » : des symboles se stabilisent de gauche à droite."""
        self._cancel_attr(widget, "_fx_decode")
        if not self.enabled:
            widget.configure(text=text)
            return
        rng = _fx_random
        glyphs = self.SCRAMBLE
        total = len(text)

        def update(p):
            reveal = int(total * p)
            out = []
            for index, char in enumerate(text):
                if index < reveal or char in " \n·—–-:":
                    out.append(char)
                else:
                    out.append(rng.choice(glyphs))
            widget.configure(text="".join(out))

        widget._fx_decode = self.tween(
            duration, update, ease, owner=widget, on_done=lambda: widget.configure(text=text)
        )

    def count_up(self, widget, text, duration=0.9, delay=0.0):
        """Fait compter le premier nombre d'un texte (ex. « 1 234,50 € ») de 0 à sa valeur."""
        self._cancel_attr(widget, "_fx_count")
        parsed = fx_parse_number(text)
        if parsed is None or not self.enabled:
            widget.configure(text=text)
            return
        start, end, value, decimals = parsed
        head, tail = text[:start], text[end:]

        def update(p):
            widget.configure(text=head + fx_format_number(value * p, decimals) + tail)

        widget.configure(text=head + fx_format_number(0.0, decimals) + tail)
        widget._fx_count = self.tween(
            duration, update, "out_expo", delay=delay, owner=widget,
            on_done=lambda: widget.configure(text=text),
        )

    # ------------------------------------------------------------ ttk
    def install_ttk_hover(self, root):
        """Survol fluide des boutons ttk : la couleur « active » du style est animée
        pendant que le bouton survolé est seul dans cet état."""
        try:
            root.bind_class("TButton", "<Enter>", self._ttk_enter, add="+")
            root.bind_class("TButton", "<Leave>", self._ttk_leave, add="+")
        except tk.TclError:
            self._ttk_ok = False

    def _ttk_restore(self):
        for (name, option), pairs in list(self._ttk_final.items()):
            try:
                ttk.Style().map(name, **{option: pairs})
            except tk.TclError:
                pass
        self._ttk_final = {}

    def _ttk_enter(self, event):
        if not (self.enabled and self._ttk_ok):
            return
        try:
            widget = event.widget
            if str(widget.cget("state")) == "disabled":
                return
            name = str(widget.cget("style")) or "TButton"
            style = ttk.Style(widget)
            plan = []
            for option in ("background", "lightcolor", "darkcolor"):
                pairs = style.map(name, query_opt=option)
                if not pairs:
                    continue
                pairs = [(str(state), value) for state, value in pairs]
                if any(" " in state for state, _ in pairs):
                    continue
                target = [value for state, value in pairs if state == "active"]
                base = style.lookup(name, option)
                if target and fx_rgb(target[0]) and fx_rgb(base):
                    plan.append((option, pairs, base, target[0]))
            if not plan:
                return
            if self._ttk_task is not None:
                self._ttk_task.cancel()
            self._ttk_restore()
            for option, pairs, base, target in plan:
                self._ttk_final[(name, option)] = pairs

            def update(p):
                for option, pairs, base, target in plan:
                    shade = fx_mix(base, target, p)
                    style.map(name, **{option: [
                        (state, shade if state == "active" else value) for state, value in pairs
                    ]})

            self._ttk_task = self.tween(0.16, update, "out_cubic", owner=widget)
        except Exception:
            self._ttk_ok = False

    def _ttk_leave(self, event):
        if not self._ttk_final:
            return
        try:
            if self._ttk_task is not None:
                self._ttk_task.cancel()
            self._ttk_restore()
        except Exception:
            self._ttk_ok = False


_FX_ORIG_TOPLEVEL = tk.Toplevel


class _FxToplevel(_FX_ORIG_TOPLEVEL):
    """Toplevel standard dont l'apparition se fait en fondu (les infobulles restent instantanées)."""

    def __init__(self, *args, **kwargs):
        _FX_ORIG_TOPLEVEL.__init__(self, *args, **kwargs)
        engine = _FX_STATE.get("engine")
        if engine is not None and engine.enabled and engine.toplevel_fade:
            try:
                self.attributes("-alpha", 0.0)
                self.after(1, self._fx_fade_in)
                self.after(900, self._fx_reveal)     # filet de sécurité : jamais de fenêtre invisible
            except tk.TclError:
                pass

    def _fx_reveal(self):
        try:
            if self.winfo_exists():
                self.attributes("-alpha", 1.0)
        except tk.TclError:
            pass

    def _fx_fade_in(self):
        engine = _FX_STATE.get("engine")
        try:
            if not self.winfo_exists():
                return
            if self.overrideredirect() or engine is None or not engine.enabled:
                self.attributes("-alpha", 1.0)
                return
            engine.tween(
                0.20, lambda p: self.attributes("-alpha", p), "out_cubic", owner=self,
                on_done=lambda: self.attributes("-alpha", 1.0),
            )
        except tk.TclError:
            pass


_FX_STATE = {"engine": None}
tk.Toplevel = _FxToplevel



# ---------------------------------------------------------------- 3D : base
def fx_rot_yxz(points, yaw, pitch, roll=0.0):
    """Rotation lacet (Y) puis tangage (X) puis roulis (Z). z positif = loin de la caméra."""
    sy, cy = math.sin(yaw), math.cos(yaw)
    sp, cp = math.sin(pitch), math.cos(pitch)
    sr, cr = math.sin(roll), math.cos(roll)
    out = []
    for x, y, z in points:
        x, z = x * cy + z * sy, -x * sy + z * cy
        y, z = y * cp - z * sp, y * sp + z * cp
        if roll:
            x, y = x * cr - y * sr, x * sr + y * cr
        out.append((x, y, z))
    return out


def fx_newell(points):
    """Normale (non normalisée) d'un polygone plan, méthode de Newell."""
    nx = ny = nz = 0.0
    count = len(points)
    for i in range(count):
        x1, y1, z1 = points[i]
        x2, y2, z2 = points[(i + 1) % count]
        nx += (y1 - y2) * (z1 + z2)
        ny += (z1 - z2) * (x1 + x2)
        nz += (x1 - x2) * (y1 + y2)
    return nx, ny, nz


class FxView(object):
    """Caméra en perspective : l'unité 3D vaut `unit` pixels à z = 0."""

    def __init__(self, cx, cy, unit, dist=5.5):
        self.cx, self.cy, self.unit, self.dist = cx, cy, unit, dist

    def project(self, x, y, z):
        depth = self.dist + z
        if depth < 0.3:
            depth = 0.3
        k = self.unit * self.dist / depth
        return self.cx + x * k, self.cy + y * k, k


class FxMesh(object):
    """Maillage composé de pièces convexes (le masquage des faces arrière suffit alors
    à obtenir un rendu correct) ; éclairage de Lambert et reflet de bord « holographique »."""

    LIGHT = (-0.45, -0.60, -0.66)

    def __init__(self):
        length = math.sqrt(sum(c * c for c in self.LIGHT))
        self.light = tuple(c / length for c in self.LIGHT)
        self.verts = []
        self.vpart = []
        self.faces = []
        self.parts = []

    def add_part(self, verts, faces, role, push=(0.0, 0.0, 0.0), bias=0.0):
        pid = len(self.parts)
        n = float(len(verts))
        center = (sum(v[0] for v in verts) / n, sum(v[1] for v in verts) / n, sum(v[2] for v in verts) / n)
        self.parts.append({"center": center, "push": push})
        base = len(self.verts)
        for vertex in verts:
            self.verts.append(vertex)
            self.vpart.append(pid)
        for idx in faces:
            pts = [verts[i] for i in idx]
            nx, ny, nz = fx_newell(pts)
            length = math.sqrt(nx * nx + ny * ny + nz * nz)
            if length < 1e-9:
                continue
            nx, ny, nz = nx / length, ny / length, nz / length
            fcx = sum(p[0] for p in pts) / len(pts)
            fcy = sum(p[1] for p in pts) / len(pts)
            fcz = sum(p[2] for p in pts) / len(pts)
            # Normale sortante : orientée à l'opposé du centre de la pièce.
            if nx * (fcx - center[0]) + ny * (fcy - center[1]) + nz * (fcz - center[2]) < 0:
                nx, ny, nz = -nx, -ny, -nz
            self.faces.append((tuple(base + i for i in idx), (nx, ny, nz), role, bias))

    def render(self, canvas, view, yaw, pitch, palette, roll=0.0, scale=1.0,
               explode=0.0, tag="g3", width=1, bright=1.0, offset=(0.0, 0.0, 0.0)):
        """Dessine le maillage sur le canvas. Retourne le nombre de faces tracées."""
        verts = []
        ox, oy, oz = offset
        for i, (x, y, z) in enumerate(self.verts):
            if explode:
                px, py, pz = self.parts[self.vpart[i]]["push"]
                x, y, z = x + px * explode, y + py * explode, z + pz * explode
            verts.append((x * scale + ox, y * scale + oy, z * scale + oz))
        rotated = fx_rot_yxz(verts, yaw, pitch, roll)
        normals = fx_rot_yxz([f[1] for f in self.faces], yaw, pitch, roll)
        lx, ly, lz = self.light
        dist = view.dist
        queue = []
        for face, normal in zip(self.faces, normals):
            idx, _, role, bias = face
            pts = [rotated[i] for i in idx]
            count = float(len(pts))
            cx = sum(p[0] for p in pts) / count
            cy = sum(p[1] for p in pts) / count
            cz = sum(p[2] for p in pts) / count
            nx, ny, nz = normal
            to_cam = -nx * cx - ny * cy - nz * (dist + cz)
            if to_cam <= 1e-6:
                continue
            sight = math.sqrt(cx * cx + cy * cy + (dist + cz) * (dist + cz))
            facing = to_cam / sight if sight > 1e-6 else 1.0
            lam = nx * lx + ny * ly + nz * lz
            lam = 0.0 if lam < 0.0 else (1.0 if lam > 1.0 else lam)
            dark, light, edge = palette[role]
            fill = fx_mix(dark, light, (0.10 + 0.90 * lam) * bright)
            line = fx_mix(fill, edge, 0.45 + 0.55 * (1.0 - facing))
            coords = []
            for px, py, pz in pts:
                sx, sy, _ = view.project(px, py, pz)
                coords.append(sx)
                coords.append(sy)
            queue.append((cz - bias, coords, fill, line))
        queue.sort(key=lambda item: -item[0])
        for _, coords, fill, line in queue:
            canvas.create_polygon(coords, fill=fill, outline=line, width=width, tags=tag)
        return len(queue)


# ---------------------------------------------------------------- 3D : formes
FX_SHIELD_OUTLINE = [
    (-0.78, -0.96), (0.78, -0.96), (0.88, -0.80), (0.88, 0.04), (0.80, 0.38), (0.62, 0.68),
    (0.36, 0.93), (0.0, 1.14), (-0.36, 0.93), (-0.62, 0.68), (-0.80, 0.38), (-0.88, 0.04), (-0.88, -0.80),
]


def fx_prism(outline, z0, z1, bevel=0.0, inset=0.92):
    """Prisme convexe : face avant en z0 (côté caméra), face arrière en z1, biseau optionnel."""
    if bevel > 0:
        layers = [(inset, z0), (1.0, z0 + bevel), (1.0, z1 - bevel), (inset, z1)]
    else:
        layers = [(1.0, z0), (1.0, z1)]
    count = len(outline)
    verts = []
    for scale, z in layers:
        for x, y in outline:
            verts.append((x * scale, y * scale, z))
    faces = [tuple(range(count))]
    for layer in range(len(layers) - 1):
        for i in range(count):
            j = (i + 1) % count
            faces.append((layer * count + i, layer * count + j, (layer + 1) * count + j, (layer + 1) * count + i))
    last = (len(layers) - 1) * count
    faces.append(tuple(range(last, last + count)))
    return verts, faces


def fx_stroke(p, q, thick):
    """Contour d'un trait épais (rectangle) entre deux points 2D."""
    dx, dy = q[0] - p[0], q[1] - p[1]
    length = math.sqrt(dx * dx + dy * dy) or 1.0
    dx, dy = dx / length, dy / length
    nx, ny = -dy * thick / 2.0, dx * thick / 2.0
    ex, ey = dx * thick / 2.0, dy * thick / 2.0
    a = (p[0] - ex, p[1] - ey)
    b = (q[0] + ex, q[1] + ey)
    return [(a[0] + nx, a[1] + ny), (b[0] + nx, b[1] + ny), (b[0] - nx, b[1] - ny), (a[0] - nx, a[1] - ny)]


def fx_shield_mesh():
    """Bouclier de sécurité : coque biseautée, écusson en relief et coche, sur les deux faces."""
    mesh = FxMesh()
    verts, faces = fx_prism(FX_SHIELD_OUTLINE, -0.16, 0.16, bevel=0.06, inset=0.93)
    mesh.add_part(verts, faces, "shell")
    crest = [(x * 0.70, y * 0.70 + 0.03) for x, y in FX_SHIELD_OUTLINE]
    verts, faces = fx_prism(crest, -0.25, -0.155, bevel=0.025, inset=0.94)
    mesh.add_part(verts, faces, "emblem", push=(0.0, 0.0, -1.0), bias=1.0)
    # Montagne en relief : sommet secondaire, grand sommet, calotte claire et ligne de sol.
    far_peak = [(0.04, 0.44), (0.33, -0.10), (0.60, 0.44)]
    verts, faces = fx_prism(far_peak, -0.33, -0.245)
    mesh.add_part(verts, faces, "emblem", push=(0.0, 0.0, -1.3), bias=1.4)
    big_peak = [(-0.50, 0.44), (-0.06, -0.38), (0.34, 0.44)]
    verts, faces = fx_prism(big_peak, -0.37, -0.245)
    mesh.add_part(verts, faces, "mount", push=(0.0, 0.0, -1.7), bias=2.0)
    cap = [(-0.06, -0.38), (-0.20, -0.12), (0.08, -0.12)]
    verts, faces = fx_prism(cap, -0.41, -0.37)
    mesh.add_part(verts, faces, "check", push=(0.0, 0.0, -2.1), bias=2.6)
    verts, faces = fx_prism([(-0.50, 0.46), (0.60, 0.46), (0.60, 0.53), (-0.50, 0.53)], -0.33, -0.245)
    mesh.add_part(verts, faces, "mount", push=(0.0, 0.0, -1.5), bias=1.6)
    verts, faces = fx_prism(crest, 0.155, 0.25, bevel=0.025, inset=0.94)
    mesh.add_part(verts, faces, "emblem", push=(0.0, 0.0, 1.0), bias=1.0)
    diamond = [(0.0, -0.26), (0.20, 0.0), (0.0, 0.26), (-0.20, 0.0)]
    verts, faces = fx_prism(diamond, 0.245, 0.34)
    mesh.add_part(verts, faces, "check", push=(0.0, 0.0, 1.7), bias=2.0)
    return mesh


def fx_palette(colors):
    """Palette 3D déduite du thème courant (sombre ou clair)."""
    bg, acc, acc2 = colors["surface"], colors["accent"], colors["accent2"]
    deep = colors["primary_dark"]
    return {
        # Logo uni : une seule teinte (celle de l'accent), seules les nuances d'éclairage varient.
        "shell": (fx_mix(bg, deep, 0.60), fx_mix(deep, acc, 0.70), acc),
        "emblem": (fx_mix(bg, deep, 0.35), fx_mix(deep, acc, 0.45), fx_mix(acc, bg, 0.25)),
        "mount": (fx_mix(acc, bg, 0.45), fx_mix(acc, bg, 0.05), fx_mix(acc, "#FFFFFF", 0.20)),
        "check": (fx_mix(acc, bg, 0.30), fx_mix(acc, "#FFFFFF", 0.35), fx_mix(acc, "#FFFFFF", 0.35)),
    }


def fx_ring(radius, count, rx, rz):
    """Cercle (plan XZ) incliné de façon fixe par rx / rz."""
    pts = []
    for i in range(count):
        angle = 2.0 * math.pi * i / count
        pts.append((radius * math.cos(angle), 0.0, radius * math.sin(angle)))
    return fx_rot_yxz(pts, 0.0, rx, rz)



# ---------------------------------------------------------------- bandeau 3D
class FxHero(object):
    """Bandeau d'accueil : bouclier holographique 3D, anneaux orbitaux, particules,
    grille de sol en perspective et HUD. Glisser = faire tourner, clic = onde de choc."""

    def __init__(self, app, parent, height=270):
        self.app = app
        self.engine = app.fx
        self.colors = app.colors
        self.height = height
        self.canvas = tk.Canvas(
            parent, height=height, bg=self.colors["surface"], highlightthickness=1,
            highlightbackground=self.colors["border"], bd=0, cursor="hand2",
        )
        self.mesh = fx_shield_mesh()
        self.palette = fx_palette(self.colors)
        self.t = 0.0
        self.intro = 0.0
        self.spin_t = -1.0
        self.next_spin = 5.5
        self.mx = self.my = 0.0
        self.cam_yaw = self.cam_pitch = 0.0
        self.user_yaw = self.user_pitch = 0.0
        self.vel_yaw = 0.0
        self.dragging = False
        self.moved = 0.0
        self.last_pt = None
        self.idle = 0.0
        self.pulses = []
        self.glitch = 0.0
        self.next_glitch = 4.0
        self.width = 0
        self.stats = self._read_stats()
        rng = _fx_random.Random(7)
        self.particles = [
            [rng.uniform(-6.0, 6.0), rng.uniform(-2.6, 2.6), rng.uniform(-2.0, 6.0), rng.uniform(0.05, 0.28)]
            for _ in range(90)
        ]
        self._build_ui()
        cv = self.canvas
        cv.bind("<Motion>", self._on_motion)
        cv.bind("<Leave>", self._on_leave)
        cv.bind("<ButtonPress-1>", self._on_press)
        cv.bind("<B1-Motion>", self._on_drag)
        cv.bind("<ButtonRelease-1>", self._on_release)
        self.task = self.engine.add(self._frame, owner=cv)

    # ------------------------------------------------------------ données
    def _read_stats(self):
        app = self.app
        try:
            totals = app.get_totals()
            margin = float(totals["margin"])
        except Exception:
            margin = 0.0
        try:
            agents = float(app.peak_agents())
        except Exception:
            agents = 0.0
        return [("MISSIONS", float(len(app.rows)), 0, ""), ("AGENTS MAX", agents, 0, ""), ("MARGE", margin, 2, " €")]

    # ------------------------------------------------------------ interface
    def _build_ui(self):
        c, cv = self.colors, self.canvas
        mono = "Consolas"
        self.ui_tag = cv.create_text(0, 0, anchor="w", text="", fill=c["success"], font=(mono, 9, "bold"), tags="ui")
        self.ui_title_a = cv.create_text(0, 0, anchor="w", text="GERGOVIE", fill=c["accent2"], font=(mono, 36, "bold"), tags="ui", state="hidden")
        self.ui_title_b = cv.create_text(0, 0, anchor="w", text="GERGOVIE", fill="#22D3EE", font=(mono, 36, "bold"), tags="ui", state="hidden")
        self.ui_title = cv.create_text(0, 0, anchor="w", text="GERGOVIE", fill=c["accent"], font=(mono, 36, "bold"), tags="ui")
        self.ui_title2 = cv.create_text(0, 0, anchor="w", text="S É C U R I T É", fill=c["text"], font=(mono, 17, "bold"), tags="ui")
        self.ui_sub = cv.create_text(0, 0, anchor="w", text="", fill=c["muted"], font=(mono, 9), tags="ui")
        self.ui_stat_label, self.ui_stat_value = [], []
        for label, _, _, _ in self.stats:
            self.ui_stat_label.append(cv.create_text(0, 0, anchor="w", text=label, fill=c["muted"], font=(mono, 8, "bold"), tags="ui"))
            self.ui_stat_value.append(cv.create_text(0, 0, anchor="w", text="0", fill=c["neon"], font=(mono, 15, "bold"), tags="ui"))
        self.ui_corner = [cv.create_line(0, 0, 0, 0, fill=c["accent"], width=2, tags="ui") for _ in range(4)]
        self.ui_scan = cv.create_line(0, 0, 0, 0, fill=c["accent2"], width=1, tags="ui")
        self.ui_clock = cv.create_text(0, 0, anchor="e", text="", fill=c["muted"], font=(mono, 8), tags="ui")
        self.ui_hint = cv.create_text(0, 0, anchor="e", text="GLISSER : PIVOTER   •   CLIC : ONDE DE CHOC", fill=c["muted"], font=(mono, 7), tags="ui")

    def _layout(self, width, height):
        cv = self.canvas
        self.width = width
        left = 30
        cv.coords(self.ui_tag, left, 34)
        for item in (self.ui_title_a, self.ui_title_b, self.ui_title):
            cv.coords(item, left, 82)
        cv.coords(self.ui_title2, left + 4, 124)
        cv.coords(self.ui_sub, left + 4, 152)
        col = min(150, int((width * 0.50 - left) / 3))
        for i in range(len(self.stats)):
            x = left + 4 + i * col
            cv.coords(self.ui_stat_label[i], x, height - 62)
            cv.coords(self.ui_stat_value[i], x, height - 40)
        m, s = 10, 22
        w, h = width - 1, height - 1
        cv.coords(self.ui_corner[0], m, m + s, m, m, m + s, m)
        cv.coords(self.ui_corner[1], w - m - s, m, w - m, m, w - m, m + s)
        cv.coords(self.ui_corner[2], m, h - m - s, m, h - m, m + s, h - m)
        cv.coords(self.ui_corner[3], w - m - s, h - m, w - m, h - m, w - m, h - m - s)
        cv.coords(self.ui_clock, width - 24, 26)
        cv.coords(self.ui_hint, width - 24, height - 22)

    # ------------------------------------------------------------ événements
    def _on_motion(self, event):
        width = max(1, self.canvas.winfo_width())
        self.mx = (event.x / float(width) - 0.5) * 2.0
        self.my = (event.y / float(self.height) - 0.5) * 2.0

    def _on_leave(self, event):
        self.mx = self.my = 0.0

    def _on_press(self, event):
        self.dragging = True
        self.moved = 0.0
        self.last_pt = (event.x, event.y)
        self.vel_yaw = 0.0
        self.idle = 0.0
        self.canvas.configure(cursor="fleur")

    def _on_drag(self, event):
        if not self.dragging or self.last_pt is None:
            return
        dx, dy = event.x - self.last_pt[0], event.y - self.last_pt[1]
        self.last_pt = (event.x, event.y)
        self.moved += abs(dx) + abs(dy)
        self.user_yaw += dx * 0.012
        self.user_pitch = fx_clamp(self.user_pitch + dy * 0.008, -0.9, 0.9)
        self.vel_yaw = self.vel_yaw * 0.5 + dx * 0.012 * 25.0 * 0.5

    def _on_release(self, event):
        self.dragging = False
        self.canvas.configure(cursor="hand2")
        if self.moved < 5:
            self.pulses.append(0.0)
            self.vel_yaw = 0.0

    # ------------------------------------------------------------ image
    def _frame(self, dt, now):
        cv = self.canvas
        if not cv.winfo_viewable() or self.engine.holding():
            return True
        width, height = cv.winfo_width(), cv.winfo_height()
        if width < 80 or height < 60:
            return True
        if width != self.width:
            self._layout(width, height)
        engine = self.engine
        quality = engine.quality
        self.t += dt
        self.intro = min(1.0, self.intro + dt / 1.5)
        intro = FX_EASE["out_cubic"](self.intro)
        follow = min(1.0, dt * 4.0)
        self.cam_yaw += (self.mx * 0.20 - self.cam_yaw) * follow
        self.cam_pitch += (0.12 + self.my * 0.10 - self.cam_pitch) * follow

        # Mouvement propre du bouclier : balancement, rotation complète périodique, inertie.
        if self.dragging:
            self.idle = 0.0
        else:
            self.user_yaw += self.vel_yaw * dt
            self.vel_yaw *= max(0.0, 1.0 - dt * 2.2)
            self.idle += dt
            if self.idle > 1.2:
                pull = min(1.0, dt * 1.6)
                wrapped = (self.user_yaw + math.pi) % (2.0 * math.pi) - math.pi
                self.user_yaw = wrapped * (1.0 - pull)
                self.user_pitch *= (1.0 - pull)
            self.next_spin -= dt
            if self.next_spin <= 0 and self.spin_t < 0:
                self.spin_t, self.next_spin = 0.0, 9.0
        spin = 0.0
        if self.spin_t >= 0:
            self.spin_t += dt
            if self.spin_t >= 1.6:
                self.spin_t = -1.0
            else:
                spin = 2.0 * math.pi * FX_EASE["in_out"](self.spin_t / 1.6)
        yaw = 0.50 * math.sin(self.t * 0.55) + self.user_yaw + spin
        pitch = self.cam_pitch + self.user_pitch + 0.05 * math.sin(self.t * 0.8)

        bump = 0.0
        alive_pulses = []
        for age in self.pulses:
            age += dt
            if age < 1.2:
                alive_pulses.append(age)
                bump = max(bump, 0.20 * (1.0 - FX_EASE["out_elastic"](min(1.0, age / 1.2))))
        self.pulses = alive_pulses

        unit = height * 0.36
        sx0 = width * (0.72 if width > 760 else 0.68)
        view = FxView(sx0, height * 0.47, unit, 5.5)
        cv.delete("g3")
        self._draw_glow(view, intro)
        if quality >= 1:
            self._draw_grid(view, width)
        if quality >= 1:
            self._draw_particles(view, dt, quality)
        rings = self._ring_specs(quality)
        self._draw_rings(view, rings, 0)
        self.mesh.render(
            cv, view, yaw, pitch, self.palette, scale=(0.55 + 0.45 * intro) * (1.0 + bump),
            explode=(1.0 - intro) * 1.4, width=1,
        )
        self._draw_rings(view, rings, 1)
        self._draw_pulses(view)
        self._update_ui(dt, intro, width, height)
        cv.tag_raise("ui")
        return True

    # ------------------------------------------------------------ éléments
    def _draw_glow(self, view, intro):
        cv, c = self.canvas, self.colors
        pulse = 0.5 + 0.5 * math.sin(self.t * 1.6)
        rings = 16 if self.engine.quality >= 1 else 8
        for i in range(rings, 0, -1):
            ratio = i / float(rings)
            radius = view.unit * (0.45 + 1.75 * ratio) * (0.6 + 0.4 * intro)
            tone = 0.018 + 0.20 * (1.0 - ratio) ** 1.4 + 0.02 * pulse * (1.0 - ratio)
            color = fx_mix(c["surface"], c["accent"], tone)
            cv.create_oval(view.cx - radius, view.cy - radius, view.cx + radius, view.cy + radius,
                           fill=color, outline="", tags="g3")

    def _draw_grid(self, view, width):
        cv, c = self.canvas, self.colors
        floor, near, far = 1.50, -2.0, 15.0
        pitch = self.cam_pitch * 0.6
        yaw = self.cam_yaw * 0.8
        lines = []
        for i in range(-9, 10):
            x = i * 1.25
            lines.append(((x, floor, near), (x, floor, far), 0.0))
        offset = (self.t * 0.9) % 1.3
        for k in range(1, 13):
            z = near + k * 1.3 - offset
            lines.append(((-11.0, floor, z), (11.0, floor, z), z))
        for a, b, z in lines:
            pa, pb = fx_rot_yxz([a, b], yaw, pitch)
            if pa[2] + view.dist < 0.4 or pb[2] + view.dist < 0.4:
                continue
            xa, ya, _ = view.project(*pa)
            xb, yb, _ = view.project(*pb)
            fade = 1.0 - fx_clamp((max(pa[2], pb[2]) + 2.0) / 17.0) if z == 0.0 else 1.0 - fx_clamp((z + 2.0) / 15.0)
            color = fx_mix(c["surface"], c["accent"], 0.07 + 0.30 * fade)
            cv.create_line(xa, ya, xb, yb, fill=color, tags="g3")

    def _draw_particles(self, view, dt, quality):
        cv, c = self.canvas, self.colors
        count = len(self.particles) if quality >= 2 else 36
        bg, acc, acc2 = c["surface"], c["accent"], c["accent2"]
        moved = []
        for i in range(count):
            p = self.particles[i]
            p[1] -= p[3] * dt
            if p[1] < -2.7:
                p[1] = 2.7
            moved.append((p[0], p[1], p[2]))
        rot = fx_rot_yxz(moved, self.t * 0.06 + self.cam_yaw * 1.4, self.cam_pitch * 0.8)
        for i, (x, y, z) in enumerate(rot):
            if z + view.dist < 0.8:
                continue
            sx, sy, k = view.project(x, y, z)
            near = fx_clamp(1.0 - (z + 3.0) / 10.0)
            color = fx_mix(bg, acc2 if i % 5 == 0 else acc, 0.18 + 0.72 * near)
            size = 1 + int(k / 70.0)
            cv.create_rectangle(sx, sy, sx + size, sy + size, fill=color, outline="", tags="g3")

    def _ring_specs(self, quality):
        steps = 56 if quality >= 2 else 36
        return [
            # rayon, inclinaison X, inclinaison Z, vitesse, couleur (clé), épaisseur
            (1.85, 1.22, 0.32, 0.50, "accent", 2, steps),
            (2.30, 1.05, -0.55, -0.34, "accent", 1, steps),
            (1.45, 0.52, 0.80, 0.78, "accent", 1, steps),
        ]

    def _draw_rings(self, view, rings, part):
        """part 0 = tronçons et satellites derrière le bouclier ; part 1 = devant."""
        cv, c = self.canvas, self.colors
        quality = self.engine.quality
        for index, (radius, rx, rz, speed, key, width, steps) in enumerate(rings):
            tint = c[key]
            front = fx_mix(c["surface"], tint, 0.95)
            back = fx_mix(c["surface"], tint, 0.28)
            base = fx_ring(radius, steps, rx, rz)
            turn, tilt = self.t * speed + self.cam_yaw, self.cam_pitch * 0.7
            pts = []
            for x, y, z in fx_rot_yxz(base, turn, tilt):
                sx, sy, _ = view.project(x, y, z)
                pts.append((sx, sy, z))
            pts.append(pts[0])
            if part == 0:
                self._draw_half(pts, back, True)
            else:
                self._draw_half(pts, front, False, width)
                if quality >= 2:
                    # graduations du cadran
                    for i in range(0, steps, 4):
                        a = base[i]
                        b = (a[0] * 1.07, a[1] * 1.07, a[2] * 1.07)
                        ra, rb = fx_rot_yxz([a, b], turn, tilt)
                        if ra[2] < 0:
                            xa, ya, _ = view.project(*ra)
                            xb, yb, _ = view.project(*rb)
                            cv.create_line(xa, ya, xb, yb, fill=front, tags="g3")
            # satellite : tête brillante + traînée, rangé devant ou derrière selon sa profondeur
            for trail in range(5):
                angle = (self.t * (1.1 + 0.4 * index) + index * 2.1) - trail * 0.11
                point = fx_rot_yxz([(radius * math.cos(angle), 0.0, radius * math.sin(angle))], 0.0, rx, rz)
                final = fx_rot_yxz(point, turn, tilt)[0]
                if (final[2] > 0) != (part == 0):
                    continue
                sx, sy, k = view.project(*final)
                size = (4.5 - trail * 0.7) * (k / view.unit)
                tone = fx_mix(c["surface"], "#FFFFFF" if trail == 0 else tint, 1.0 - trail * 0.18)
                cv.create_oval(sx - size, sy - size, sx + size, sy + size, fill=tone, outline="", tags="g3")

    def _draw_half(self, pts, color, back_only, width=1):
        cv = self.canvas
        if back_only:
            group = []
            for sx, sy, depth in pts:
                if depth >= 0:
                    group.extend((sx, sy))
                else:
                    if len(group) >= 4:
                        cv.create_line(group, fill=color, tags="g3")
                    group = []
            if len(group) >= 4:
                cv.create_line(group, fill=color, tags="g3")
        else:
            group = []
            for sx, sy, depth in pts:
                if depth < 0:
                    group.extend((sx, sy))
                else:
                    if len(group) >= 4:
                        cv.create_line(group, fill=color, width=width, tags="g3")
                    group = []
            if len(group) >= 4:
                cv.create_line(group, fill=color, width=width, tags="g3")

    def _draw_pulses(self, view):
        cv, c = self.canvas, self.colors
        for age in self.pulses:
            p = age / 1.2
            radius = view.unit * (0.9 + 2.6 * FX_EASE["out_expo"](p))
            color = fx_mix(c["accent2"], c["surface"], p)
            cv.create_oval(view.cx - radius, view.cy - radius * 0.38, view.cx + radius, view.cy + radius * 0.38,
                           outline=color, width=2, tags="g3")
            cv.create_oval(view.cx - radius * 0.8, view.cy - radius * 0.8, view.cx + radius * 0.8, view.cy + radius * 0.8,
                           outline=fx_mix(c["accent"], c["surface"], min(1.0, p * 1.2)), width=1, tags="g3")

    def _update_ui(self, dt, intro, width, height):
        cv = self.canvas
        t = self.t
        blink = "_" if int(t * 2.2) % 2 == 0 else " "
        cv.itemconfigure(self.ui_tag, text="> SYSTÈME EN LIGNE" + blink)
        sub = "CHIFFRAGE  ·  RESSOURCES HUMAINES  ·  RELATION CLIENT"
        shown = int(max(0.0, t - 0.5) * 38)
        cv.itemconfigure(self.ui_sub, text=sub[:shown])
        for i, (label, value, decimals, suffix) in enumerate(self.stats):
            cv.itemconfigure(self.ui_stat_value[i], text=fx_format_number(value * intro, decimals) + suffix)
        # glitch périodique du titre
        self.next_glitch -= dt
        if self.next_glitch <= 0 and self.glitch <= 0:
            self.glitch, self.next_glitch = 0.14, _fx_random.uniform(5.0, 9.0)
        if self.glitch > 0:
            self.glitch -= dt
            jitter = _fx_random.choice((-3, -2, 2, 3))
            cv.itemconfigure(self.ui_title_a, state="normal")
            cv.itemconfigure(self.ui_title_b, state="normal")
            cv.coords(self.ui_title_a, 30 - jitter, 82)
            cv.coords(self.ui_title_b, 30 + jitter, 82)
        else:
            cv.itemconfigure(self.ui_title_a, state="hidden")
            cv.itemconfigure(self.ui_title_b, state="hidden")
        # ligne de balayage
        sweep = (t * 0.35) % 1.0
        y = 14 + sweep * (height - 28)
        cv.coords(self.ui_scan, 14, y, width - 14, y)
        cv.itemconfigure(self.ui_scan, fill=fx_mix(self.colors["surface"], self.colors["accent2"], 0.30))
        cv.itemconfigure(self.ui_clock, text=time.strftime("%d/%m/%Y   %H:%M:%S"))



# ---------------------------------------------------------------- menu de connexion
FX_LOGIN_COLORS = {
    "background": "#090711", "surface": "#100D18", "surface_2": "#191323", "border": "#35223C",
    "text": "#E8FFF0", "muted": "#91B7A0", "accent": "#39FF88", "accent2": "#D946EF",
    "neon": "#39FF88", "primary_dark": "#16803B", "success": "#39FF88", "danger": "#FF4D6D",
}


class FxLogin(object):
    """Écran d'accueil : blason 3D, faux formulaire de connexion (identifiant + mot de passe),
    séquence d'authentification animée, puis le rideau se lève sur l'application.
    Démonstration : tout couple identifiant / mot de passe non vide est accepté, rien n'est enregistré."""

    LOG = [
        "> VÉRIFICATION DES IDENTIFIANTS",
        "> OUVERTURE DE LA SESSION SÉCURISÉE",
        "> CHARGEMENT DES MODULES BLOC I · II · III",
        "> ACCÈS AUTORISÉ",
    ]
    AUTH_TIME = 1.9

    def __init__(self, app, on_done):
        self.app = app
        self.engine = app.fx
        self.on_done = on_done
        c = self.colors = FX_LOGIN_COLORS
        self.cv = tk.Canvas(app, bg=c["background"], highlightthickness=0, bd=0)
        self.cv.place(x=0, y=0, relwidth=1.0, relheight=1.0)
        self.cv.lift()
        self.edge = tk.Canvas(app, height=3, bg=c["accent"], highlightthickness=0, bd=0)
        self.mesh = fx_shield_mesh()
        self.palette = fx_palette(c)
        self.state = "form"
        self.t = self.auth_t = self.close_t = self.shake = self.hv = self.hv_eye = 0.0
        self.notice, self.notice_color = "", c["muted"]
        self.show_pwd = False
        self.hover = None
        self.user = ""
        self.finished = False
        self.rects = {}
        self.user_var = tk.StringVar()
        self.pwd_var = tk.StringVar()
        opts = dict(
            font=("Consolas", 12), bg=c["surface_2"], fg=c["text"], insertbackground=c["accent"],
            relief="flat", bd=0, highlightthickness=1, highlightbackground=c["border"],
            highlightcolor=c["accent"], disabledbackground=c["surface_2"], disabledforeground=c["muted"],
        )
        self.user_entry = tk.Entry(self.cv, textvariable=self.user_var, **opts)
        self.pwd_entry = tk.Entry(self.cv, textvariable=self.pwd_var, show="•", **opts)
        self.w_user = self.cv.create_window(0, 0, window=self.user_entry, anchor="nw", width=350, height=32)
        self.w_pwd = self.cv.create_window(0, 0, window=self.pwd_entry, anchor="nw", width=306, height=32)
        for entry in (self.user_entry, self.pwd_entry):
            entry.bind("<Return>", self._submit)
            entry.bind("<Key>", self._typing, add="+")
        self.user_entry.bind("<Down>", lambda e: self.pwd_entry.focus_set())
        self.pwd_entry.bind("<Up>", lambda e: self.user_entry.focus_set())
        self.cv.bind("<Button-1>", self._click)
        self.cv.bind("<Motion>", self._motion)
        self.task = self.engine.add(self._frame, owner=self.cv)
        self.cv.after(250, self._focus)

    # ------------------------------------------------------------ actions
    def raise_up(self):
        try:
            self.cv.lift()
            if self.state == "closing":
                self.edge.lift()
        except tk.TclError:
            pass

    def _focus(self):
        try:
            if self.state == "form":
                self.user_entry.focus_force()
        except tk.TclError:
            pass

    def _typing(self, event=None):
        if self.notice_color == self.colors["danger"]:
            self.notice = ""
        for entry in (self.user_entry, self.pwd_entry):
            try:
                entry.configure(highlightbackground=self.colors["border"])
            except tk.TclError:
                pass

    def _submit(self, event=None):
        if self.state != "form":
            return
        name, password = self.user_var.get().strip(), self.pwd_var.get()
        c = self.colors
        if not name or not password:
            self.notice, self.notice_color = "Identifiant et mot de passe requis.", c["danger"]
            self.shake = 0.5
            target = self.user_entry if not name else self.pwd_entry
            target.configure(highlightbackground=c["danger"])
            target.focus_set()
            return
        self.user = name
        self.state = "auth"
        self.auth_t = 0.0
        self.notice = ""
        for entry in (self.user_entry, self.pwd_entry):
            entry.configure(state="disabled")
        self.cv.configure(cursor="watch")

    def _click(self, event):
        if self.state != "form":
            return
        for name, (x1, y1, x2, y2) in self.rects.items():
            if x1 <= event.x <= x2 and y1 <= event.y <= y2:
                if name == "btn":
                    self._submit()
                elif name == "eye":
                    self.show_pwd = not self.show_pwd
                    self.pwd_entry.configure(show="" if self.show_pwd else "•")
                elif name == "forgot":
                    self.notice = "Démonstration : aucun mot de passe réel n'est demandé."
                    self.notice_color = self.colors["accent2"]
                return

    def _motion(self, event):
        hit = None
        if self.state == "form":
            for name, (x1, y1, x2, y2) in self.rects.items():
                if x1 <= event.x <= x2 and y1 <= event.y <= y2:
                    hit = name
        self.hover = hit
        try:
            self.cv.configure(cursor="hand2" if hit else "")
        except tk.TclError:
            pass

    def _finish(self):
        if self.finished:
            return
        self.finished = True
        for widget in (self.edge, self.cv):
            try:
                widget.destroy()
            except tk.TclError:
                pass

    def _notify_done(self):
        if getattr(self, "_notified", False):
            return
        self._notified = True
        try:
            self.on_done(self.user or "Invité")
        except Exception:
            import traceback
            traceback.print_exc()

    # ------------------------------------------------------------ image
    def _frame(self, dt, now):
        try:
            return self._draw(dt)
        except tk.TclError:
            return False
        except Exception:
            # Filet de sécurité : jamais bloquer l'utilisateur à cause d'un problème d'affichage.
            import traceback
            traceback.print_exc()
            self._notify_done()
            self._finish()
            return False

    def _draw(self, dt):
        cv, c = self.cv, self.colors
        width, height = cv.winfo_width(), cv.winfo_height()
        if width < 120 or height < 120:
            return True
        self.t += dt
        t = self.t
        if self.state == "auth":
            self.auth_t += dt
            if self.auth_t >= self.AUTH_TIME:
                self.state = "closing"
                self.close_t = 0.0
                self._notify_done()
        slide = 0.0
        if self.state == "closing":
            self.close_t += dt
            slide = FX_EASE["in_out"](min(1.0, self.close_t / 0.8))
            if slide >= 1.0:
                self._finish()
                return False
            offset = int(-slide * height)
            cv.place_configure(y=offset)
            self.edge.place(x=0, y=offset + height - 2, relwidth=1.0)
            self.edge.lift()
        self.shake = max(0.0, self.shake - dt)
        shake_x = math.sin(self.shake * 48.0) * 12.0 * (self.shake / 0.5) if self.shake > 0 else 0.0
        self.hv += ((1.0 if self.hover == "btn" else 0.0) - self.hv) * min(1.0, dt * 12.0)
        self.hv_eye += ((1.0 if self.hover == "eye" else 0.0) - self.hv_eye) * min(1.0, dt * 12.0)

        cv.delete("dyn")
        card_w, card_h = 440, 282
        card_x = (width - card_w) / 2.0 + shake_x
        card_y = min(height * 0.50, height - card_h - 66)
        card_y = max(card_y, 250)
        build = FX_EASE["out_cubic"](fx_clamp(t / 1.4))
        boost = FX_EASE["in_out"](fx_clamp(self.auth_t / self.AUTH_TIME)) if self.state != "form" else 0.0

        # fond : grille et halo
        step = 46
        grid = fx_mix(c["background"], c["accent"], 0.045)
        for gx in range(0, int(width), step):
            cv.create_line(gx, 0, gx, height, fill=grid, tags="dyn")
        for gy in range(0, int(height), step):
            cv.create_line(0, gy, width, gy, fill=grid, tags="dyn")
        unit = max(30.0, (card_y - 120.0) / 2.7)
        view = FxView(width / 2.0, max(unit * 1.4, (card_y - 96.0) / 2.0 + 8), unit, 5.5)
        pulse = 0.5 + 0.5 * math.sin(t * 2.2)
        for i in range(14, 0, -1):
            ratio = i / 14.0
            radius = unit * (0.6 + 2.2 * ratio)
            tone = 0.014 + (0.16 + 0.10 * boost) * (1.0 - ratio) ** 1.5 + 0.02 * pulse * (1.0 - ratio)
            cv.create_oval(view.cx - radius, view.cy - radius, view.cx + radius, view.cy + radius,
                           fill=fx_mix(c["background"], c["accent"], tone),
                           outline="", tags="dyn")
        # blason 3D
        yaw = (1.0 - build) * 5.0 + 0.55 * math.sin(t * 0.8) + boost * 12.566
        scale = (0.5 + 0.5 * build) * (1.0 + 0.06 * math.sin(boost * 3.1416))
        self.mesh.render(cv, view, yaw, 0.14 + 0.04 * math.sin(t * 1.1), self.palette,
                         scale=scale, explode=(1.0 - build) * 2.0, tag="dyn")
        ring = unit * 1.7
        sweep = (t * (160.0 + 400.0 * boost)) % 360.0
        cv.create_arc(view.cx - ring, view.cy - ring, view.cx + ring, view.cy + ring, start=sweep,
                      extent=64, style="arc", outline=c["accent"], width=2, tags="dyn")
        cv.create_arc(view.cx - ring, view.cy - ring, view.cx + ring, view.cy + ring, start=sweep + 180,
                      extent=36, style="arc", outline=c["accent"], width=2, tags="dyn")
        # titre
        title = "GERGOVIE SÉCURITÉ"
        shown = int(fx_clamp((t - 0.2) / 0.9) * len(title))
        glyphs = "".join(ch if (i < shown or ch == " ") else _fx_random.choice(FxEngine.SCRAMBLE)
                         for i, ch in enumerate(title))
        ty = card_y - 52
        cv.create_text(width / 2.0, ty, text=glyphs, fill=c["accent"], font=("Consolas", 24, "bold"), tags="dyn")
        cv.create_text(width / 2.0, ty + 26, text="CHIFFRAGE  ·  RESSOURCES HUMAINES  ·  RELATION CLIENT",
                       fill=c["muted"], font=("Consolas", 9), tags="dyn")

        # carte de connexion
        x0, y0 = card_x, card_y
        cut = 16

        def cut_poly(a, b, w, h, pad=0):
            return [a + pad, b + pad, a + w - cut - pad, b + pad, a + w - pad, b + cut + pad,
                    a + w - pad, b + h - pad, a + cut + pad, b + h - pad, a + pad, b + h - cut - pad]

        cv.create_polygon(cut_poly(x0, y0, card_w, card_h), fill=c["surface"],
                          outline=fx_mix(c["surface"], c["accent"], 0.35), width=4, tags="dyn")
        cv.create_polygon(cut_poly(x0, y0, card_w, card_h, 2), fill=c["surface"], outline=c["accent"], width=1, tags="dyn")
        cv.create_text(x0 + 30, y0 + 24, anchor="w", text="CONNEXION SÉCURISÉE", fill=c["text"],
                       font=("Consolas", 11, "bold"), tags="dyn")
        led = fx_mix(c["surface"], c["success"], 0.35 + 0.65 * pulse)
        cv.create_oval(x0 + card_w - 40, y0 + 18, x0 + card_w - 30, y0 + 28, fill=led, outline="", tags="dyn")
        cv.create_text(x0 + 30, y0 + 58, anchor="w", text="IDENTIFIANT", fill=c["muted"], font=("Consolas", 8, "bold"), tags="dyn")
        cv.create_text(x0 + 30, y0 + 120, anchor="w", text="MOT DE PASSE", fill=c["muted"], font=("Consolas", 8, "bold"), tags="dyn")
        cv.coords(self.w_user, x0 + 30, y0 + 68)
        cv.coords(self.w_pwd, x0 + 30, y0 + 130)
        # bouton « voir »
        ex1, ey1 = x0 + 30 + 314, y0 + 130
        self.rects = {"eye": (ex1, ey1, ex1 + 36, ey1 + 32)}
        cv.create_rectangle(ex1, ey1, ex1 + 36, ey1 + 32, outline=fx_mix(c["border"], c["accent"], self.hv_eye),
                            fill=c["surface_2"], tags="dyn")
        cv.create_text(ex1 + 18, ey1 + 16, text="◉" if self.show_pwd else "○", fill=c["accent"],
                       font=("Consolas", 12, "bold"), tags="dyn")
        by = y0 + 232
        if self.state == "form":
            msg = self.notice
            if msg:
                cv.create_text(x0 + card_w / 2.0, y0 + 182, text=msg, fill=self.notice_color, font=("Consolas", 9), tags="dyn")
            if not msg:
                cv.create_text(x0 + 30, y0 + 190, anchor="w", text="Mot de passe oublié ?", fill=c["muted"],
                               font=("Consolas", 8, "underline"), tags="dyn")
            self.rects["forgot"] = (x0 + 30, y0 + 182, x0 + 190, y0 + 198)
            bx1, bx2 = x0 + 30, x0 + card_w - 30
            self.rects["btn"] = (bx1, by - 14, bx2, by + 22)
            fill = fx_mix(fx_mix(c["surface_2"], c["accent"], 0.22), c["accent"], 0.45 * self.hv)
            cv.create_polygon(cut_poly(bx1, by - 14, bx2 - bx1, 36), fill=fill, outline=c["accent"], width=1, tags="dyn")
            cv.create_text((bx1 + bx2) / 2.0, by + 4, text="SE CONNECTER  →",
                           fill="#04120A" if self.hv > 0.5 else c["text"], font=("Consolas", 11, "bold"), tags="dyn")
        else:
            # séquence d'authentification
            per = self.AUTH_TIME / len(self.LOG)
            for i, line in enumerate(self.LOG):
                start = i * per
                if self.auth_t < start:
                    break
                chars = int((self.auth_t - start) * 70)
                done = chars >= len(line)
                last = i == len(self.LOG) - 1
                cv.create_text(x0 + 30, y0 + 176 + i * 15, anchor="w", text=line[:chars],
                               fill=c["success"] if (last and done) else c["muted"], font=("Consolas", 9), tags="dyn")
            progress = fx_clamp(self.auth_t / self.AUTH_TIME)
            bx1, bx2 = x0 + 30, x0 + card_w - 30
            cv.create_rectangle(bx1, by - 4, bx2, by + 6, outline=fx_mix(c["background"], c["accent"], 0.45), fill=c["background"], tags="dyn")
            cv.create_rectangle(bx1 + 1, by - 3, bx1 + 1 + (bx2 - bx1 - 2) * progress, by + 5, outline="", fill=c["accent"], tags="dyn")
            if self.state == "closing":
                cv.create_text(x0 + card_w / 2.0, y0 + 156, text="BIENVENUE, %s" % self.user.upper()[:24],
                               fill=c["accent"], font=("Consolas", 11, "bold"), tags="dyn")
        cv.create_text(width / 2.0, card_y + card_h + 26, text="Accès de démonstration : tout identifiant et mot de passe non vides sont acceptés.",
                       fill=c["muted"], font=("Consolas", 8), tags="dyn")
        cv.create_text(width / 2.0, height - 22, text="Créé par Gabriel — BTS MOS", fill=c["muted"],
                       font=("Consolas", 8, "italic"), tags="dyn")
        return True


# ---------------------------------------------------------------- graphiques 3D
class FxChart3D(object):
    """Histogramme 3D (barres en relief sur plateau) et anneau 3D, sur le canvas du bilan.
    Glisser = pivoter, molette = zoom, survol = valeur de la barre."""

    def __init__(self, app, canvas):
        self.app = app
        self.engine = app.fx
        self.canvas = canvas
        self.mode = None
        self.active = False
        self.labels, self.series, self.metrics = [], {}, []
        self.yaw, self.pitch, self.zoom = -0.55, 0.52, 1.0
        self.grow = 0.0
        self.t = 0.0
        self.drag = None
        self.vel = 0.0
        self.hover = None
        self.hover_mix = {}
        self.regions = []
        self.mouse = (0, 0)
        self.task = None
        canvas.bind("<ButtonPress-1>", self._press, add="+")
        canvas.bind("<B1-Motion>", self._drag, add="+")
        canvas.bind("<ButtonRelease-1>", self._release, add="+")
        canvas.bind("<MouseWheel>", self._wheel, add="+")
        canvas.bind("<Button-4>", self._wheel, add="+")
        canvas.bind("<Button-5>", self._wheel, add="+")

    # ------------------------------------------------------------ pilotage
    def start(self, mode, labels, series, metrics):
        self.mode = mode
        self.labels, self.series, self.metrics = labels, self._floats(series), metrics
        self.grow = 0.0
        self.hover = None
        self.hover_mix = {}
        if not self.active:
            self.active = True
            self.task = self.engine.add(self._frame, owner=self.canvas)
        if not self.engine.enabled:
            self.grow = 1.0

    @staticmethod
    def _floats(series):
        return {k: [float(v) for v in vals] for k, vals in series.items()}

    def stop(self):
        self.active = False
        if self.task is not None:
            self.task.cancel()
            self.task = None

    # ------------------------------------------------------------ souris
    def _press(self, event):
        if self.active:
            self.drag = (event.x, event.y)
            self.vel = 0.0

    def _drag(self, event):
        if not self.active or self.drag is None:
            return
        dx, dy = event.x - self.drag[0], event.y - self.drag[1]
        self.drag = (event.x, event.y)
        self.yaw += dx * 0.010
        self.pitch = fx_clamp(self.pitch + dy * 0.006, 0.12, 1.20)
        self.vel = self.vel * 0.4 + dx * 0.010 * 25.0 * 0.6

    def _release(self, event):
        self.drag = None

    def _wheel(self, event):
        if not self.active:
            return
        up = getattr(event, "num", None) == 4 or getattr(event, "delta", 0) > 0
        self.zoom = fx_clamp(self.zoom * (1.08 if up else 0.92), 0.55, 2.2)
        return "break"

    def on_motion(self, event):
        self.mouse = (event.x, event.y)

    # ------------------------------------------------------------ rendu
    def _frame(self, dt, now):
        cv = self.canvas
        if not self.active:
            return False
        if not cv.winfo_viewable():
            return True
        width, height = cv.winfo_width(), cv.winfo_height()
        if width < 120 or height < 120:
            return True
        self.t += dt
        self.grow = min(1.0, self.grow + dt / 0.9)
        if self.drag is None:
            self.yaw += self.vel * dt + 0.10 * dt
            self.vel *= max(0.0, 1.0 - dt * 2.0)
        cv.delete("all")
        if self.mode == "ring":
            self._draw_ring(width, height)
        else:
            self._draw_bars(width, height)
        return True

    def _palette_for(self, index):
        c = self.app.colors
        base = [c["accent"], "#2DD4BF", "#38BDF8", c["accent2"], "#A3E635", "#22D3EE", "#A78BFA", "#6EE7B7"]
        return base[index % len(base)]

    def _draw_bars(self, width, height):
        cv, c = self.canvas, self.app.colors
        labels, series, metrics = self.labels, self.series, self.metrics
        if not labels or not metrics:
            return
        count, rows = len(labels), len(metrics)
        gap = 1.5
        span_x = count * gap
        span_z = rows * gap
        maxima = {}
        for metric in metrics:
            group = self.app._axis_group(metric)
            peak = max([abs(v) for v in series[metric]] + [1e-9])
            maxima[group] = max(maxima.get(group, 0.0), peak)
        unit = min(width / (span_x + span_z * 0.9 + 3.2), height / 5.2) * 0.62 * self.zoom
        view = FxView(width * 0.5, height * 0.60, unit, 7.0 + 0.45 * max(count, rows))
        yaw, pitch = self.yaw, self.pitch
        grow = FX_EASE["out_back"](self.grow) if self.grow < 1.0 else 1.0
        ox, oz = -span_x / 2.0, -span_z / 2.0

        def pt(x, y, z):
            px, py, pz = fx_rot_yxz([(x, y, z)], yaw, pitch)[0]
            sx, sy, k = view.project(px, py, pz)
            return sx, sy, pz

        # plateau et grille
        floor_color = fx_mix(c["surface"], c["accent"], 0.07)
        corners = [pt(ox - 0.4, 0, oz - 0.4), pt(ox + span_x + 0.4, 0, oz - 0.4),
                   pt(ox + span_x + 0.4, 0, oz + span_z + 0.4), pt(ox - 0.4, 0, oz + span_z + 0.4)]
        cv.create_polygon([v for p in corners for v in p[:2]], fill=floor_color,
                          outline=fx_mix(c["surface"], c["accent"], 0.45), width=2)
        for i in range(count + 1):
            a, b = pt(ox + i * gap, 0, oz - 0.4), pt(ox + i * gap, 0, oz + span_z + 0.4)
            cv.create_line(a[0], a[1], b[0], b[1], fill=fx_mix(c["surface"], c["accent"], 0.16))
        for j in range(rows + 1):
            a, b = pt(ox - 0.4, 0, oz + j * gap), pt(ox + span_x + 0.4, 0, oz + j * gap)
            cv.create_line(a[0], a[1], b[0], b[1], fill=fx_mix(c["surface"], c["accent"], 0.16))
        # mur du fond avec graduations
        tall = 3.4
        back = [pt(ox - 0.4, 0, oz - 0.4), pt(ox + span_x + 0.4, 0, oz - 0.4),
                pt(ox + span_x + 0.4, -tall, oz - 0.4), pt(ox - 0.4, -tall, oz - 0.4)]
        side = [pt(ox - 0.4, 0, oz - 0.4), pt(ox - 0.4, 0, oz + span_z + 0.4),
                pt(ox - 0.4, -tall, oz + span_z + 0.4), pt(ox - 0.4, -tall, oz - 0.4)]
        for wall in (back, side):
            cv.create_polygon([v for p in wall for v in p[:2]], fill=fx_mix(c["surface"], c["accent"], 0.035), outline="")
        for level in range(1, 5):
            y = -tall * level / 4.0
            a, b, d = pt(ox - 0.4, y, oz - 0.4), pt(ox + span_x + 0.4, y, oz - 0.4), pt(ox - 0.4, y, oz + span_z + 0.4)
            line_color = fx_mix(c["surface"], c["accent"], 0.20)
            cv.create_line(a[0], a[1], b[0], b[1], fill=line_color, dash=(2, 4))
            cv.create_line(a[0], a[1], d[0], d[1], fill=line_color, dash=(2, 4))
        # barres (tri du fond vers l'avant)
        boxes = []
        for j, metric in enumerate(metrics):
            group = self.app._axis_group(metric)
            for i, value in enumerate(series[metric]):
                h = (abs(value) / maxima[group]) * tall * 0.92 * grow
                if value < 0:
                    h = -h
                x0 = ox + i * gap + 0.28
                x1 = ox + (i + 1) * gap - 0.28 - (0.0 if rows == 1 else 0.0)
                z0 = oz + j * gap + 0.28
                z1 = oz + (j + 1) * gap - 0.28
                center = fx_rot_yxz([((x0 + x1) / 2.0, -h / 2.0, (z0 + z1) / 2.0)], yaw, pitch)[0]
                boxes.append((center[2], i, j, metric, value, x0, x1, z0, z1, h))
        boxes.sort(key=lambda b: -b[0])
        self.regions = []
        mx, my = self.mouse
        new_hover = None
        for depth, i, j, metric, value, x0, x1, z0, z1, h in boxes:
            color = self._palette_for(j)
            key = (i, j)
            mixv = self.hover_mix.get(key, 0.0)
            lift = 0.16 * mixv
            top = -h - lift
            verts = [
                (x0, 0, z0), (x1, 0, z0), (x1, 0, z1), (x0, 0, z1),
                (x0, top, z0), (x1, top, z0), (x1, top, z1), (x0, top, z1),
            ]
            rot = fx_rot_yxz(verts, yaw, pitch)
            proj = [view.project(*p) for p in rot]
            faces = [
                ((4, 5, 6, 7), (0, -1, 0), 1.00),   # dessus
                ((0, 1, 5, 4), (0, 0, -1), 0.62),   # face avant (z0)
                ((3, 2, 6, 7), (0, 0, 1), 0.62),    # face arrière
                ((0, 3, 7, 4), (-1, 0, 0), 0.80),   # gauche
                ((1, 2, 6, 5), (1, 0, 0), 0.80),    # droite
            ]
            if h < 0:
                faces[0] = ((0, 1, 2, 3), (0, -1, 0), 1.00)
            normals = fx_rot_yxz([f[1] for f in faces], yaw, pitch)
            for (idx, _, shade), (nx, ny, nz) in zip(faces, normals):
                pts = [rot[k] for k in idx]
                cx = sum(p[0] for p in pts) / 4.0
                cy = sum(p[1] for p in pts) / 4.0
                cz = sum(p[2] for p in pts) / 4.0
                if -nx * cx - ny * cy - nz * (view.dist + cz) <= 1e-6:
                    continue
                lx, ly, lz = FX_LIGHT
                lam = max(0.0, nx * lx + ny * ly + nz * lz)
                tone = fx_mix(c["surface"], color, 0.28 + 0.72 * (0.45 * shade + 0.55 * lam))
                tone = fx_mix(tone, "#FFFFFF", 0.22 * mixv)
                coords = []
                for k in idx:
                    coords.extend((proj[k][0], proj[k][1]))
                cv.create_polygon(coords, fill=tone, outline=fx_mix(tone, color, 0.55 + 0.4 * mixv), width=1)
            xs = [p[0] for p in proj]
            ys = [p[1] for p in proj]
            region = (min(xs), min(ys), max(xs), max(ys))
            self.regions.append((region, key, metric, i, value))
            if region[0] <= mx <= region[2] and region[1] <= my <= region[3]:
                new_hover = (key, metric, i, value, region)
            # valeur flottante au-dessus de la barre
            if count * rows <= 18 and self.grow > 0.85:
                tip = proj[4:8]
                tx = sum(p[0] for p in tip) / 4.0
                ty = min(p[1] for p in tip) - 10
                cv.create_text(tx, ty, text=self.app._chart_value_text(metric, value), fill=c["text"], font=("Consolas", 7, "bold"))
        # libellés sur le bord avant
        near_z = oz + span_z + 0.55
        if pt(ox, 0.0, oz - 0.55)[2] < pt(ox, 0.0, near_z)[2]:
            near_z = oz - 0.55
        for i, label in enumerate(labels):
            lx, ly, _ = pt(ox + (i + 0.5) * gap, 0.0, near_z)
            text = label if len(label) <= 12 else label[:11] + "…"
            cv.create_text(lx, ly + 8, text=text, fill=c["muted"], font=("Consolas", 8))
        # survol : fondu de l'élévation + infobulle
        for key in set(list(self.hover_mix.keys()) + ([new_hover[0]] if new_hover else [])):
            target = 1.0 if (new_hover and new_hover[0] == key) else 0.0
            cur = self.hover_mix.get(key, 0.0)
            self.hover_mix[key] = cur + (target - cur) * 0.25
        if new_hover:
            key, metric, i, value, region = new_hover
            text = "%s\n%s : %s" % (labels[i], metric, self.app._chart_value_text(metric, value))
            self._tooltip(text, mx, my)
        # légende
        x = 24
        for j, metric in enumerate(metrics):
            cv.create_rectangle(x, 16, x + 12, 28, fill=self._palette_for(j), outline="")
            item = cv.create_text(x + 18, 22, anchor="w", text=metric, fill=c["text"], font=("Consolas", 8, "bold"))
            box = cv.bbox(item)
            x = (box[2] if box else x + 150) + 22
        cv.create_text(width - 24, 22, anchor="e", text="3D • glisser : pivoter • molette : zoom",
                       fill=c["muted"], font=("Consolas", 8))

    def _tooltip(self, text, x, y):
        cv, c = self.canvas, self.app.colors
        lines = text.split("\n")
        w = max(len(s) for s in lines) * 7 + 18
        h = len(lines) * 15 + 10
        bx = min(x + 14, cv.winfo_width() - w - 6)
        by = max(6, y - h - 10)
        cv.create_rectangle(bx, by, bx + w, by + h, fill=c["nav"], outline=c["accent"], width=1)
        for k, line in enumerate(lines):
            cv.create_text(bx + 9, by + 7 + k * 15, anchor="nw", text=line,
                           fill="white" if k == 0 else "#CBD5E1", font=("Consolas", 9, "bold" if k == 0 else "normal"))

    def _draw_ring(self, width, height):
        cv, c = self.canvas, self.app.colors
        metric = self.metrics[0] if self.metrics else None
        values = self.series.get(metric, []) if metric else []
        total = sum(v for v in values if v > 0)
        if total <= 0:
            cv.create_text(width / 2, height / 2, text="Aucune valeur positive à représenter.", fill=c["muted"], font=("Consolas", 10))
            return
        unit = min(width * 0.24, height * 0.30) * self.zoom
        view = FxView(width * 0.30, height * 0.54, unit, 6.0)
        yaw, pitch = self.yaw, self.pitch
        grow = FX_EASE["out_cubic"](self.grow)
        outer, inner, thick = 1.5, 0.78, 0.34
        # un anneau complet de socle
        slices = []
        angle = -math.pi / 2.0
        for i, value in enumerate(values):
            if value <= 0:
                continue
            sweep = value / total * 2.0 * math.pi * grow
            slices.append((i, angle, angle + sweep, value))
            angle += sweep
        mx, my = self.mouse
        faces = []
        hover_hit = None
        for i, a0, a1, value in slices:
            color = self._palette_for(i)
            mixv = self.hover_mix.get(i, 0.0)
            mid = (a0 + a1) / 2.0
            push = 0.18 * mixv
            dx, dz = math.cos(mid) * push, math.sin(mid) * push
            segments = max(2, int((a1 - a0) / (2.0 * math.pi) * 64) + 1)
            arc = [a0 + (a1 - a0) * s / segments for s in range(segments + 1)]
            top, bot = -thick, 0.0

            def ring_pts(radius, y):
                return [(math.cos(a) * radius + dx, y, math.sin(a) * radius + dz) for a in arc]

            otop, obot = ring_pts(outer, top), ring_pts(outer, bot)
            itop, ibot = ring_pts(inner, top), ring_pts(inner, bot)
            polys = [(otop + itop[::-1], (0, -1, 0), 1.0, "top")]
            for s in range(segments):
                a_mid = (arc[s] + arc[s + 1]) / 2.0
                polys.append(([otop[s], otop[s + 1], obot[s + 1], obot[s]], (math.cos(a_mid), 0, math.sin(a_mid)), 0.68, "wall"))
                polys.append(([itop[s], itop[s + 1], ibot[s + 1], ibot[s]], (-math.cos(a_mid), 0, -math.sin(a_mid)), 0.58, "wall"))
            polys.append(([otop[0], itop[0], ibot[0], obot[0]], (math.sin(a0), 0, -math.cos(a0)), 0.75, "wall"))
            polys.append(([otop[-1], itop[-1], ibot[-1], obot[-1]], (-math.sin(a1), 0, math.cos(a1)), 0.75, "wall"))
            for pts3, normal, shade, kind in polys:
                faces.append((i, pts3, normal, shade, color, mixv, kind))
        scene = []
        for i, pts3, normal, shade, color, mixv, kind in faces:
            rot = fx_rot_yxz(pts3, yaw, pitch)
            nx, ny, nz = fx_rot_yxz([normal], yaw, pitch)[0]
            n = float(len(rot))
            cx = sum(p[0] for p in rot) / n
            cy = sum(p[1] for p in rot) / n
            cz = sum(p[2] for p in rot) / n
            if -nx * cx - ny * cy - nz * (view.dist + cz) <= 1e-6:
                continue
            lx, ly, lz = FX_LIGHT
            lam = max(0.0, nx * lx + ny * ly + nz * lz)
            tone = fx_mix(c["surface"], color, 0.30 + 0.70 * (0.40 * shade + 0.60 * lam))
            tone = fx_mix(tone, "#FFFFFF", 0.20 * mixv)
            coords = []
            for p in rot:
                sx, sy, _ = view.project(*p)
                coords.extend((sx, sy))
            scene.append((cz + (0.05 if kind == "top" else 0.0), coords, tone, color, i))
        scene.sort(key=lambda s: -s[0])
        new_hover = None
        for _, coords, tone, color, i in scene:
            cv.create_polygon(coords, fill=tone, outline=fx_mix(tone, color, 0.6), width=1)
            xs, ys = coords[0::2], coords[1::2]
            if min(xs) <= mx <= max(xs) and min(ys) <= my <= max(ys) and _fx_point_in_poly(mx, my, coords):
                new_hover = i
        for key in set(list(self.hover_mix.keys()) + ([new_hover] if new_hover is not None else [])):
            target = 1.0 if new_hover == key else 0.0
            cur = self.hover_mix.get(key, 0.0)
            self.hover_mix[key] = cur + (target - cur) * 0.25
        cv.create_text(view.cx, view.cy - unit * 0.22, text="Total", fill=c["muted"], font=("Consolas", 9))
        cv.create_text(view.cx, view.cy - unit * 0.02, text=self.app._chart_value_text(metric, total), fill=c["text"], font=("Consolas", 11, "bold"))
        # légende chiffrée
        lx = width * 0.56
        cv.create_text(28, 20, anchor="w", text="Anneau 3D — %s" % metric, fill=c["text"], font=("Consolas", 10, "bold"))
        for k, (label, value) in enumerate(zip(self.labels, values)):
            y = 52 + k * 24
            if y > height - 30:
                cv.create_text(lx, y, anchor="w", text="… %d autre(s) mission(s)" % (len(self.labels) - k), fill=c["muted"], font=("Consolas", 9))
                break
            active = new_hover == k
            cv.create_rectangle(lx, y, lx + 13, y + 13, fill=self._palette_for(k), outline="")
            cv.create_text(lx + 20, y + 6, anchor="w", text=label if len(label) <= 28 else label[:27] + "…",
                           fill=c["text"] if not active else c["accent"], font=("Consolas", 9, "bold" if active else "normal"))
            share = value / total * 100.0 if value > 0 else 0.0
            cv.create_text(width - 28, y + 6, anchor="e", text="%s  (%.1f%%)" % (self.app._chart_value_text(metric, value), share),
                           fill=c["muted"], font=("Consolas", 9))
        cv.create_text(width - 24, height - 16, anchor="e", text="3D • glisser : pivoter • molette : zoom", fill=c["muted"], font=("Consolas", 8))


def _fx_point_in_poly(x, y, coords):
    inside = False
    n = len(coords) // 2
    j = n - 1
    for i in range(n):
        xi, yi = coords[2 * i], coords[2 * i + 1]
        xj, yj = coords[2 * j], coords[2 * j + 1]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-9) + xi:
            inside = not inside
        j = i
    return inside



FX_LIGHT = (-0.45, -0.60, -0.66)
_fx_len = math.sqrt(sum(v * v for v in FX_LIGHT))
FX_LIGHT = tuple(v / _fx_len for v in FX_LIGHT)

FX_TIPS = [
    "SYSTÈME EN LIGNE  //  SAUVEGARDE AUTO ACTIVE",
    "CTRL+S  //  ENREGISTRER LE DOSSIER",
    "CTRL+N  //  NOUVEAU DOSSIER",
    "ASTUCE  //  GLISSEZ SUR LE BOUCLIER 3D DE L'ACCUEIL",
    "ASTUCE  //  BILAN : ESSAYEZ « BARRES 3D » ET « ANNEAU 3D »",
]


# ---------------------------------------------------------------- cartes
class FxCardMixin(object):
    """Effets des cartes néon : faisceau lumineux qui parcourt le contour au survol,
    et tour d'allumage à l'apparition de la page."""

    fx = None   # moteur d'animation, posé au démarrage de l'application

    def _fx_state(self):
        if not hasattr(self, "_fx_hovering"):
            self._fx_hovering = False
            self._fx_task = None
            self._fx_alpha = 0.0
            self._fx_pos = 0.0
            self._fx_items = None
            self._fx_intro_done = False
            self._fx_intro_task = None

    def _fx_contour(self):
        x1, y1, x2, y2, c = 3, 3, self._width - 4, self._height - 4, self._cut
        pts = [(x1, y1), (x2 - c, y1), (x2, y1 + c), (x2, y2), (x1 + c, y2), (x1, y2 - c), (x1, y1)]
        lens = [math.hypot(b[0] - a[0], b[1] - a[1]) for a, b in zip(pts[:-1], pts[1:])]
        return pts, lens, sum(lens)

    def _fx_beam(self, start, length):
        """Points d'un tronçon de contour (départ `start`, longueur `length`, avec bouclage)."""
        pts, lens, total = self._fx_contour()
        if total < 40:
            return None
        start %= total
        count = len(lens)
        idx = 0
        while start >= lens[idx]:
            start -= lens[idx]
            idx = (idx + 1) % count
        a, b = pts[idx], pts[idx + 1]
        frac = start / lens[idx]
        coords = [a[0] + (b[0] - a[0]) * frac, a[1] + (b[1] - a[1]) * frac]
        left = lens[idx] - start
        remain = min(length, total * 0.9)
        guard = 0
        while remain > 0 and guard < 16:
            if lens[idx] <= 1e-6:
                idx = (idx + 1) % count
                left = lens[idx]
                guard += 1
                continue
            step = min(left, remain)
            a, b = pts[idx], pts[idx + 1]
            frac = (lens[idx] - left + step) / lens[idx]
            coords.extend((a[0] + (b[0] - a[0]) * frac, a[1] + (b[1] - a[1]) * frac))
            remain -= step
            idx = (idx + 1) % count
            left = lens[idx]
            guard += 1
        return coords

    def _fx_draw_beam(self, start, length, alpha):
        coords = self._fx_beam(start, length)
        if coords is None or len(coords) < 4:
            return
        hot = self._hover_border
        halo = fx_mix(self._fill, hot, 0.38 * alpha)
        core = fx_mix(self._fill, fx_mix(hot, "#FFFFFF", 0.45), alpha)
        if self._fx_items is None:
            self._fx_items = (
                self.create_line(coords, fill=halo, width=5, capstyle="round", joinstyle="round"),
                self.create_line(coords, fill=core, width=2, capstyle="round", joinstyle="round"),
            )
        else:
            for item, color in zip(self._fx_items, (halo, core)):
                self.coords(item, *coords)
                self.itemconfigure(item, fill=color)
                self.tag_raise(item)

    def _fx_clear(self):
        if self._fx_items is not None:
            for item in self._fx_items:
                try:
                    self.delete(item)
                except tk.TclError:
                    pass
            self._fx_items = None

    def _fx_hover(self, on):
        engine = self.fx
        if engine is None or not engine.enabled:
            return
        self._fx_state()
        self._fx_hovering = on
        if on and self._fx_task is None:
            if self._fx_intro_task is not None:
                self._fx_intro_task.cancel()
                self._fx_intro_task = None
            self._fx_task = engine.add(self._fx_hover_step, owner=self)

    def _fx_hover_step(self, dt, now):
        target = 1.0 if self._fx_hovering else 0.0
        self._fx_alpha += (target - self._fx_alpha) * min(1.0, dt * 9.0)
        if not self._fx_hovering and self._fx_alpha < 0.03:
            self._fx_clear()
            self._fx_alpha = 0.0
            self._fx_task = None
            return False
        self._fx_pos += dt * 430.0
        pts, lens, total = self._fx_contour()
        self._fx_draw_beam(self._fx_pos, total * 0.22, self._fx_alpha)
        return True

    def _fx_intro(self):
        """Tour d'allumage du contour, décalé d'une carte à l'autre quand la page apparaît."""
        engine = self.fx
        if engine is None or not engine.enabled or engine.quality < 1:
            return
        self._fx_state()
        if self._fx_intro_done:
            return
        self._fx_intro_done = True
        order = engine.stagger()
        if order > 16:
            return
        clock = {"t": -0.05 * order}

        def step(dt, now):
            if engine.holding():
                return True
            if self._fx_hovering or self._fx_task is not None:
                self._fx_intro_task = None
                return False
            clock["t"] += dt
            if clock["t"] < 0:
                return True
            p = clock["t"] / 0.75
            if p >= 1.0 or self._width < 40:
                self._fx_clear()
                self._fx_intro_task = None
                return False
            pts, lens, total = self._fx_contour()
            self._fx_draw_beam(FX_EASE["in_out"](p) * total, total * 0.26, math.sin(p * math.pi))
            return True

        self._fx_intro_task = engine.add(step, owner=self)


# ---------------------------------------------------------------- barre de scan
class FxScanLine(tk.Canvas):
    """Filet sous le logo : un éclat lumineux va et vient."""

    def __init__(self, parent, app, height=4):
        c = app.colors
        tk.Canvas.__init__(self, parent, height=height, bg=c["nav"], highlightthickness=0, bd=0)
        self.app = app
        self.base = self.create_rectangle(0, height // 2 - 1, 1, height // 2 + 1, fill=c["accent2"], outline="")
        self.glow = self.create_rectangle(0, 0, 0, height, fill=c["neon"], outline="")
        self.t = 0.0
        self.bind("<Configure>", self._resize)
        self.width = 1
        app.fx.add(self._step, owner=self, fps=30)

    def _resize(self, event):
        self.width = max(1, event.width)
        self.coords(self.base, 0, int(self.winfo_reqheight()) // 2 - 1, self.width, int(self.winfo_reqheight()) // 2 + 1)

    def _step(self, dt, now):
        if not self.app.fx.enabled:
            return True
        self.t += dt
        phase = (math.sin(self.t * 1.7) + 1.0) / 2.0
        span = 64
        x = phase * (self.width - span)
        self.coords(self.glow, x, 0, x + span, int(self.winfo_reqheight()))
        return True


# ---------------------------------------------------------------- application
class FxAppMixin(object):
    """Méthodes d'animation ajoutées à GergovieApp (préfixe fx_)."""

    # ------------------------------------------------------------ démarrage
    def fx_init(self):
        self.fx = FxEngine(self)
        _FX_STATE["engine"] = self.fx
        FxCardMixin.fx = self.fx
        # Les animations d'interface attendent que l'utilisateur soit connecté.
        self.fx.hold_until = self.fx.clock() + 3600.0
        self.fx_login = None
        self.fx_user = ""
        self._fx_welcome = None
        self._fx_chart3d = None
        self._fx_chart_busy = None
        self._fx_slide_offset = 0
        self._fx_toast = None
        self._fx_nav_active = None
        self._fx_tip = 0
        self._fx_tip_clock = 9.0
        self._fx_dot_colors = {}
        self.fx_button = None

    def fx_login_open(self):
        """Affiche tout de suite l'écran de connexion : la construction de l'interface se fait derrière."""
        try:
            self.fx_login = FxLogin(self, self._fx_logged_in)
            self.update()
        except Exception:
            import traceback
            traceback.print_exc()
            self.fx_login = None
            self.fx.hold_until = 0.0

    def _fx_logged_in(self, user):
        self.fx_user = user
        self.fx.hold_until = 0.0
        FX_TIPS[0] = "SESSION  //  %s  //  SYSTÈME EN LIGNE" % user.upper()[:24]
        self._fx_tip = 0
        self.after(1100, lambda: self.fx_toast("✓  BIENVENUE, " + user.upper()[:24]))

    def fx_start(self):
        try:
            self.fx.install_ttk_hover(self)
        except Exception:
            pass
        self.fx.add(self._fx_ambient, fps=20)
        if self.fx_login is not None:
            self.fx_login.raise_up()
            self.after(200, self.fx_login.raise_up)

    def fx_toggle(self):
        self.fx.enabled = not self.fx.enabled
        if self.fx_button is not None:
            try:
                self.fx_button.configure(text=self._fx_button_text())
            except tk.TclError:
                pass
        self.show_page(self.current_page)
        self.fx_toast("✦  EFFETS 3D : " + ("ACTIVÉS" if self.fx.enabled else "DÉSACTIVÉS"), "info")

    def _fx_button_text(self):
        return "✦  Effets 3D : " + ("ON" if self.fx.enabled else "OFF")

    # ------------------------------------------------------------ pages
    def fx_page_begin(self):
        self.fx.reset_stagger()

    def fx_page_enter(self, title):
        engine = self.fx
        if not engine.enabled:
            return
        engine.decode_text(self.page_title, title, 0.42)
        canvas, window = self.page_canvas, self.page_window

        def update(p):
            self._fx_slide_offset = int(38 * (1.0 - p))
            canvas.coords(window, 26, 24 + self._fx_slide_offset)

        def done():
            self._fx_slide_offset = 0
            canvas.coords(window, 26, 24)

        engine.tween(0.46, update, "out_cubic", owner=canvas, on_done=done)

    def fx_make_hero(self):
        if not self.fx.enabled:
            return None
        hero = FxHero(self, self.page_frame, 270)
        hero.canvas.pack(fill="x", pady=(0, 20))
        return hero

    # ------------------------------------------------------------ barre latérale
    def fx_scan_line(self, parent):
        if not self.fx.enabled:
            return tk.Frame(parent, bg=self.colors["accent2"], height=2)
        return FxScanLine(parent, self)

    def fx_sidebar_enter(self):
        """Entrée en cascade des lignes de navigation."""
        engine = self.fx
        if not engine.enabled:
            return
        rows = []
        for button in self.nav_buttons.values():
            try:
                rows.append(button.master)
            except AttributeError:
                pass
        for index, row in enumerate(rows):
            try:
                info = row.pack_info()
                padx = info.get("padx", 0)
                base = int(str(padx).split()[0]) if padx else 0
            except (tk.TclError, ValueError):
                continue

            def update(p, row=row, base=base):
                row.pack_configure(padx=(base + int(110 * (1.0 - p)), 0))

            engine.tween(0.45, update, "out_cubic", delay=0.04 * index + 0.05, owner=row,
                         on_done=lambda row=row, base=base: row.pack_configure(padx=base))

    def fx_nav_hover(self, button, on):
        engine = self.fx
        if not engine.enabled:
            return
        engine._cancel_attr(button, "_fx_tw_padx")
        engine._cancel_attr(button, "_fx_tw_bg")
        c = self.colors
        start = int(str(button.cget("padx")) or 12)
        end = 20 if on else 12
        if on:
            engine.tween_option(button, "bg", c["nav"], c["nav_hover"], 0.14)

        def update(p):
            button.configure(padx=int(start + (end - start) * p))

        button._fx_tw_padx = engine.tween(0.14, update, "out_cubic", owner=button)

    def fx_nav_selected(self, active):
        """Petit « snap » élastique sur le liseré de l'entrée de menu qui vient d'être activée."""
        if active == self._fx_nav_active:
            return
        self._fx_nav_active = active
        indicator = getattr(self, "nav_indicators", {}).get(active)
        engine = self.fx
        if indicator is None or not engine.enabled:
            return

        def update(p):
            indicator.configure(width=max(3, int(4 + 14 * (1.0 - p))))

        engine.tween(0.55, update, "out_elastic", owner=indicator,
                     on_done=lambda: indicator.configure(width=4))

    # ------------------------------------------------------------ ambiance
    def _fx_ambient(self, dt, now):
        engine = self.fx
        if not engine.enabled:
            return True
        c = self.colors
        try:
            dot = getattr(self, "footer_dot", None)
            if dot is not None and dot.winfo_exists():
                pulse = 0.5 + 0.5 * math.sin(now * 3.2)
                self._fx_set_fg(dot, fx_mix(c["surface_2"], c["success"], 0.25 + 0.75 * pulse))
            save = getattr(self, "save_state_dot", None)
            if save is not None and save.winfo_exists():
                if self.dirty:
                    pulse = 0.5 + 0.5 * math.sin(now * 6.0)
                    self._fx_set_fg(save, fx_mix(c["surface"], c["warning"], 0.35 + 0.65 * pulse))
                else:
                    self._fx_set_fg(save, c["success"])
            status = getattr(self, "footer_status", None)
            if status is not None and status.winfo_exists():
                self._fx_tip_clock -= dt
                if self._fx_tip_clock <= 0:
                    self._fx_tip_clock = 12.0
                    self._fx_tip = (self._fx_tip + 1) % len(FX_TIPS)
                    engine.decode_text(status, FX_TIPS[self._fx_tip], 0.6)
        except tk.TclError:
            pass
        return True

    def _fx_set_fg(self, widget, color):
        key = str(widget)
        if self._fx_dot_colors.get(key) != color:
            self._fx_dot_colors[key] = color
            widget.configure(fg=color)

    def fx_toast(self, text, kind="ok"):
        engine = self.fx
        if not engine.enabled:
            return
        c = self.colors
        color = c["success"] if kind == "ok" else c["accent2"]
        if self._fx_toast is not None:
            try:
                self._fx_toast.destroy()
            except tk.TclError:
                pass
        box = tk.Frame(self, bg=color)
        tk.Label(box, text=text, bg=c["nav"], fg=color, font=("Consolas", 10, "bold"), padx=18, pady=10).pack(padx=1, pady=1)
        box.place(relx=1.0, rely=1.0, x=360, y=-54, anchor="se")
        box.lift()
        self._fx_toast = box

        def slide_in(p):
            box.place_configure(x=int(360 - 384 * p))

        def slide_out(p):
            box.place_configure(x=int(-24 + 384 * p))

        def gone():
            try:
                box.destroy()
            except tk.TclError:
                pass
            if self._fx_toast is box:
                self._fx_toast = None

        engine.tween(0.5, slide_in, "out_back", owner=box)
        engine.tween(0.35, slide_out, "in_cubic", delay=2.4, owner=box, on_done=gone)

    def fx_curtain(self, color, edge):
        """Rideau qui se lève sur la nouvelle interface (changement de thème)."""
        engine = self.fx
        if not engine.enabled:
            return
        try:
            height = max(1, self.winfo_height())
            cv = tk.Canvas(self, bg=color, highlightthickness=0, bd=0)
            cv.place(x=0, y=0, relwidth=1.0, relheight=1.0)
            cv.lift()
            bar = tk.Canvas(self, height=3, bg=edge, highlightthickness=0, bd=0)
            for gy in range(0, height, 44):
                cv.create_line(0, gy, 4000, gy, fill=fx_mix(color, edge, 0.06))
        except tk.TclError:
            return

        def update(p):
            offset = int(-p * height)
            cv.place_configure(y=offset)
            bar.place(x=0, y=offset + height - 2, relwidth=1.0)
            bar.lift()

        def done():
            for widget in (bar, cv):
                try:
                    widget.destroy()
                except tk.TclError:
                    pass

        engine.tween(0.65, update, "in_out", delay=0.08, owner=cv, on_done=done)

    # ------------------------------------------------------------ graphiques
    def _fx_chart_mode(self):
        return {"Barres 3D": "bars", "Anneau 3D": "ring"}.get(self.chart_type_var.get())

    def _fx_get_chart3d(self):
        ctl = self._fx_chart3d
        if ctl is None or ctl.canvas is not self.chart_canvas:
            ctl = FxChart3D(self, self.chart_canvas)
            self._fx_chart3d = ctl
        return ctl

    def _fx_stop_chart3d(self):
        ctl = self._fx_chart3d
        if ctl is not None and ctl.active:
            ctl.stop()

    def draw_result_chart(self, animate=False):
        canvas = self.chart_canvas
        if canvas is None or not canvas.winfo_exists():
            return
        engine = self.fx
        mode = self._fx_chart_mode()
        if mode:
            self._fx_chart_busy = None
            labels, series = self._chart_series()
            self._hide_chart_tooltip()
            self.chart_hitboxes = []
            if not labels or not series:
                self._fx_stop_chart3d()
                self._draw_result_chart_frame(1.0)
                return
            names = list(series.keys())
            if mode == "ring":
                names = names[:1]
            ctl = self._fx_get_chart3d()
            if animate or not ctl.active or ctl.mode != mode:
                ctl.start(mode, labels, series, names)
            else:
                ctl.labels, ctl.series, ctl.metrics = labels, ctl._floats(series), names
            return
        self._fx_stop_chart3d()
        if animate and engine.enabled:
            self._fx_chart_busy = canvas
            engine.tween(
                0.75, lambda p: self._draw_result_chart_frame(p), "out_cubic", owner=canvas,
                on_done=lambda: setattr(self, "_fx_chart_busy", None),
            )
            return
        if self._fx_chart_busy is canvas:
            return   # une animation d'apparition est en cours : elle lit la taille à chaque image
        self._draw_result_chart_frame(1.0)

    # ------------------------------------------------------------ KPI
    def fx_count(self, label, value):
        self.fx.count_up(label, value, 0.9, delay=0.06 * self.fx.stagger())


class RoundedCard(FxCardMixin, tk.Canvas):
    """Carte "néon" aux coins coupés (style cyberpunk), Tkinter pur, sans image.

    Même interface qu'avant : les widgets enfants se placent dans ``self.inner`` ;
    la carte s'adapte à son contenu et se redimensionne avec la fenêtre.
    Le halo est simulé par un second contour plus épais, de couleur atténuée.
    """

    def __init__(self, parent, fill, border, outer_bg, hover_border=None, radius=12):
        tk.Canvas.__init__(self, parent, bg=outer_bg, highlightthickness=0, bd=0, width=1, height=1)
        self._fill = fill
        self._border = border
        self._hover_border = hover_border or border
        self._outer_bg = outer_bg
        self._cut = radius
        self._inset = int(radius * 0.6) + 2
        self._width = 0
        self._height = 0
        self._req_w = 0
        self._req_h = 0
        self._shape = None
        self._glow = None
        self.inner = tk.Frame(self, bg=fill)
        self._window = self.create_window(self._inset, self._inset, window=self.inner, anchor="nw")
        self.bind("<Configure>", self._on_canvas_configure)
        self.inner.bind("<Configure>", self._on_inner_configure)

    @staticmethod
    def _cut_points(x1, y1, x2, y2, c):
        # Coins coupés en haut à droite et en bas à gauche.
        return [x1, y1, x2 - c, y1, x2, y1 + c, x2, y2, x1 + c, y2, x1, y2 - c]

    def _draw(self):
        if self._width < 8 or self._height < 8:
            return
        for item in (self._glow, self._shape):
            if item is not None:
                self.delete(item)
        halo = blend_hex(self._border, self._outer_bg, 0.45)
        self._glow = self.create_polygon(
            self._cut_points(1, 1, self._width - 2, self._height - 2, self._cut),
            fill=self._fill, outline=halo, width=3,
        )
        self._shape = self.create_polygon(
            self._cut_points(3, 3, self._width - 4, self._height - 4, self._cut),
            fill=self._fill, outline=self._border, width=1,
        )
        self.tag_lower(self._shape)
        self.tag_lower(self._glow)

    def _on_canvas_configure(self, event):
        self._width, self._height = event.width, event.height
        self.itemconfigure(self._window, width=max(1, event.width - 2 * self._inset))
        self._draw()

    def _on_inner_configure(self, event=None):
        try:
            need_w = self.inner.winfo_reqwidth() + 2 * self._inset
            need_h = self.inner.winfo_reqheight() + 2 * self._inset
            if need_w != self._req_w or need_h != self._req_h:
                self._req_w, self._req_h = need_w, need_h
                self.configure(width=need_w, height=need_h)
        except tk.TclError:
            pass

    def refresh(self):
        """À appeler quand le contenu de la carte est construit."""
        try:
            self.after_idle(self._on_inner_configure)
            self._fx_intro()
        except tk.TclError:
            pass

    def _set_outline(self, color):
        try:
            if self._shape is not None:
                self.itemconfigure(self._shape, outline=color)
            if self._glow is not None:
                self.itemconfigure(self._glow, outline=blend_hex(color, self._outer_bg, 0.45))
        except tk.TclError:
            pass

    def enable_hover(self):
        """Le contour passe au magenta néon quand la souris survole la carte."""
        def on_enter(event):
            self._set_outline(self._hover_border)
            self._fx_hover(True)

        def on_leave(event):
            try:
                under = self.winfo_containing(event.x_root, event.y_root)
            except (KeyError, tk.TclError):
                under = None
            widget = under
            while widget is not None:
                if widget is self:
                    return
                widget = getattr(widget, "master", None)
            self._set_outline(self._border)
            self._fx_hover(False)

        def walk(widget):
            widget.bind("<Enter>", on_enter, add="+")
            widget.bind("<Leave>", on_leave, add="+")
            for child in widget.winfo_children():
                walk(child)

        walk(self)


# ======================================================================
# GÉNÉRATEUR DE PLANNING — FEUILLE HEBDOMADAIRE PAR AGENT (moteur de calcul)
# ----------------------------------------------------------------------
# Principe : toutes les sommes sont faites en Decimal (aucune erreur de virgule flottante).
#   Pour chaque vacation, la durée RÉELLE est découpée en tranches homogènes (nuit / dimanche /
#   férié constants, changements d'heure inclus) par le même moteur que le chiffrage des missions
#   (_segments). Puis, tranche par tranche :
#       coût  = minutes / 60 × taux de revient × coefficient
#       vente = minutes / 60 × taux de vente   × coefficient
#   Coefficient = produit (mode multiplicatif) ou 1 + somme des taux (mode additif) des
#   majorations applicables : nuit, dimanche, férié, « autre majoration ».
#   Arrondi au centime (ROUND_HALF_UP) UNE SEULE FOIS par jour ; le total de la semaine est la
#   somme exacte des jours arrondis + heures supplémentaires arrondies : ce qui est affiché
#   s'additionne toujours exactement.
# ======================================================================
from decimal import localcontext as _ws_localcontext

WS_DAY_NAMES = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"]
WS_ABSENCES = ["Congé payé", "Maladie", "Absence injustifiée", "Autre absence"]
WS_STATUSES = ["Travail", "Repos"] + WS_ABSENCES
WS_KINDS = ["Auto", "Normal", "Dimanche", "Férié", "Dimanche + férié"]
WS_KIND_FLAGS = {
    "Normal": (False, False),
    "Dimanche": (True, False),
    "Férié": (False, True),
    "Dimanche + férié": (True, True),
}
WS_ZERO = Decimal("0")
WS_EPS = Decimal("0.0000001")


def ws_dec(value):
    """Saisie (« 12,5 », « 20 % », 15.0...) -> Decimal exact (6 décimales max)."""
    return Decimal(str(round(number(value, 0.0), 6)))


def ws_cents(value):
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def ws_normalize_time(text):
    cleaned = str(text or "").strip().lower().replace("h", ":").replace(".", ":")
    if cleaned.endswith(":") and cleaned != ":":
        cleaned += "00"
    return cleaned


def ws_parse_hm(text):
    cleaned = ws_normalize_time(text)
    if not cleaned:
        return None
    try:
        return datetime.strptime(cleaned, "%H:%M").time()
    except ValueError:
        return None


def ws_parse_date(text):
    try:
        return datetime.strptime(str(text).strip(), "%d/%m/%Y").date()
    except ValueError:
        return None


def ws_blank_day():
    return {"statut": "Repos", "debut": "", "fin": "", "pause": "0",
            "type": "Auto", "autre": "0", "prime": "0"}


def ws_make_sheet(agent="", cost="15", sale="20", nuit="10", dim="0", ferie="0"):
    return {
        "agent": agent, "profil": "",
        "rate_cost": cost, "rate_sale": sale,
        "maj_nuit": nuit, "maj_dim": dim, "maj_ferie": ferie,
        "ot_on": False, "ot_threshold": "35", "ot_t1_hours": "8",
        "ot_t1_rate": "25", "ot_t2_rate": "50",
        "days": [ws_blank_day() for _ in range(7)],
    }


def ws_sheet_is_blank(sheet):
    for entry in sheet.get("days") or []:
        if entry.get("statut", "Repos") != "Repos":
            return False
        if ws_normalize_time(entry.get("debut")) or ws_normalize_time(entry.get("fin")):
            return False
        if ws_dec(entry.get("prime")) != 0:
            return False
    return True


def ws_coefficient(mode, night, sunday, holiday, other, rates):
    """Coefficient de majoration (mêmes règles que HRModule.multiplier + « autre majoration »)."""
    factors = []
    if night:
        factors.append(1 + rates["nuit"] / 100)
    if sunday:
        factors.append(1 + rates["dimanche"] / 100)
    if holiday:
        factors.append(1 + rates["ferie"] / 100)
    if other != 0:
        factors.append(1 + other / 100)
    if not factors:
        return Decimal(1)
    if mode == "additive":
        result = 1 + sum((f - 1 for f in factors), WS_ZERO)
    else:
        result = Decimal(1)
        for factor in factors:
            result *= factor
    return max(result, WS_ZERO)


def ws_compute_day(app, day, entry, rates, mode):
    status = str(entry.get("statut") or "Repos")
    res = {
        "date": day, "status": status, "worked": False, "error": False,
        "absent": status in WS_ABSENCES, "rest": status == "Repos",
        "holiday": day in french_holidays(day.year), "alerts": [],
        "minutes": WS_ZERO, "night_min": WS_ZERO, "sunday_min": WS_ZERO, "holiday_min": WS_ZERO,
        "base_cost": WS_ZERO, "base_sale": WS_ZERO, "cost_raw": WS_ZERO, "sale_raw": WS_ZERO,
        "cost_work": WS_ZERO, "prime": WS_ZERO, "cost": WS_ZERO, "sale": WS_ZERO,
        "coef": None, "start": None, "end": None, "pause": WS_ZERO,
        "kind": entry.get("type") or "Auto", "other": WS_ZERO,
    }
    raw_start, raw_end = ws_normalize_time(entry.get("debut")), ws_normalize_time(entry.get("fin"))
    if status != "Travail":
        if raw_start or raw_end:
            res["alerts"].append("ℹ Horaires ignorés (%s)" % status.lower())
        return res

    def fail(message):
        res["error"] = True
        res["alerts"].append("⚠ " + message)
        return res

    if not raw_start and not raw_end:
        return fail("Horaires non saisis")
    t1, t2 = ws_parse_hm(raw_start), ws_parse_hm(raw_end)
    if t1 is None or t2 is None:
        return fail("Horaire invalide (format HH:MM)")
    start, end = datetime.combine(day, t1), datetime.combine(day, t2)
    if end == start:
        return fail("Début = fin (durée nulle)")
    if end < start:
        end += timedelta(days=1)          # vacation de nuit : fin le lendemain
    pause = ws_dec(entry.get("pause"))
    other = ws_dec(entry.get("autre"))
    prime = ws_dec(entry.get("prime"))
    if pause < 0 or prime < 0:
        return fail("Pause ou prime négative")
    segments = app._segments(start, end)
    total_min = sum((ws_dec(s[2]) for s in segments), WS_ZERO)
    if total_min <= 0:
        return fail("Durée réelle nulle")
    if pause >= total_min:
        return fail("Pause supérieure ou égale à la durée")
    scale = (total_min - pause) / total_min       # pause non payée répartie au prorata
    flags = WS_KIND_FLAGS.get(res["kind"])
    for _, _, minutes, night, sunday, holiday in segments:
        m = ws_dec(minutes) * scale
        if flags is not None:
            sunday, holiday = flags
        coef = ws_coefficient(mode, night, sunday, holiday, other, rates)
        res["minutes"] += m
        if night:
            res["night_min"] += m
        if sunday:
            res["sunday_min"] += m
        if holiday:
            res["holiday_min"] += m
        res["base_cost"] += m * rates["cost"] / 60
        res["base_sale"] += m * rates["sale"] / 60
        res["cost_raw"] += m * rates["cost"] * coef / 60
        res["sale_raw"] += m * rates["sale"] * coef / 60
    res.update(worked=True, start=start, end=end, pause=pause, other=other, prime=prime)
    res["cost_work"] = ws_cents(res["cost_raw"])
    res["cost"] = res["cost_work"] + ws_cents(prime)
    res["sale"] = ws_cents(res["sale_raw"])
    if res["base_cost"] > 0:
        res["coef"] = res["cost_raw"] / res["base_cost"]
    elif res["base_sale"] > 0:
        res["coef"] = res["sale_raw"] / res["base_sale"]
    if res["minutes"] > 600:
        res["alerts"].append("⚠ Plus de 10 h de travail effectif (L3121-18)")
    return res


def ws_compute_week(app, monday, sheet, mode=None):
    """Calcule toute la semaine. Retourne un dictionnaire de résultats (Decimal)."""
    with _ws_localcontext() as ctx:
        ctx.prec = 40
        mode = mode or app.project.get("mode", "multiplicative")
        rates = {
            "cost": ws_dec(sheet.get("rate_cost")), "sale": ws_dec(sheet.get("rate_sale")),
            "nuit": ws_dec(sheet.get("maj_nuit")), "dimanche": ws_dec(sheet.get("maj_dim")),
            "ferie": ws_dec(sheet.get("maj_ferie")),
        }
        entries = sheet.get("days") or []
        days = []
        for i in range(7):
            entry = entries[i] if i < len(entries) and isinstance(entries[i], dict) else ws_blank_day()
            days.append(ws_compute_day(app, monday + timedelta(days=i), entry, rates, mode))

        # Repos quotidien (11 h) entre deux jours consécutifs travaillés.
        for i in range(1, 7):
            prev, cur = days[i - 1], days[i]
            if prev["worked"] and cur["worked"]:
                gap = (cur["start"] - prev["end"]).total_seconds() / 3600.0
                if gap < 0:
                    cur["alerts"].append("⚠ Chevauchement avec la vacation de la veille")
                elif gap < 11:
                    cur["alerts"].append("⚠ Repos quotidien de %.1f h (< 11 h, L3131-1)" % gap)

        total_min = sum((d["minutes"] for d in days), WS_ZERO)
        hours = total_min / 60
        worked_days = sum(1 for d in days if d["worked"])
        week_alerts = []
        if hours > 48:
            week_alerts.append("⚠ %.2f h dans la semaine : maximum absolu de 48 h dépassé (L3121-20)" % float(hours))
        if worked_days == 7:
            week_alerts.append("⚠ 7 jours travaillés : aucun repos hebdomadaire (L3132-1)")

        # Heures supplémentaires (option) : majoration hebdomadaire sur le taux de base.
        ot = {"on": bool(sheet.get("ot_on")), "h1": WS_ZERO, "h2": WS_ZERO, "cost": WS_ZERO, "sale": WS_ZERO}
        if ot["on"]:
            threshold = ws_dec(sheet.get("ot_threshold") if str(sheet.get("ot_threshold", "")).strip() else "35")
            tranche1 = ws_dec(sheet.get("ot_t1_hours") if str(sheet.get("ot_t1_hours", "")).strip() else "8")
            r1, r2 = ws_dec(sheet.get("ot_t1_rate")), ws_dec(sheet.get("ot_t2_rate"))
            extra = max(hours - threshold, WS_ZERO)
            ot["h1"] = min(extra, tranche1)
            ot["h2"] = extra - ot["h1"]
            weighted = (ot["h1"] * r1 + ot["h2"] * r2) / 100
            ot["cost"] = ws_cents(weighted * rates["cost"])
            ot["sale"] = ws_cents(weighted * rates["sale"])

        days_cost = sum((d["cost"] for d in days), WS_ZERO)
        days_sale = sum((d["sale"] for d in days), WS_ZERO)
        return {
            "monday": monday, "rates": rates, "mode": mode, "days": days,
            "minutes": total_min, "hours": hours,
            "night_hours": sum((d["night_min"] for d in days), WS_ZERO) / 60,
            "sunday_hours": sum((d["sunday_min"] for d in days), WS_ZERO) / 60,
            "holiday_hours": sum((d["holiday_min"] for d in days), WS_ZERO) / 60,
            "worked_days": worked_days,
            "absent_days": sum(1 for d in days if d["absent"]),
            "rest_days": sum(1 for d in days if d["rest"]),
            "primes": sum((ws_cents(d["prime"]) for d in days), WS_ZERO),
            "days_cost": days_cost, "days_sale": days_sale, "overtime": ot,
            "cost": days_cost + ot["cost"], "sale": days_sale + ot["sale"],
            "alerts": week_alerts,
        }


def ws_minutewise(app, day_result, rates, mode):
    """Contrôle INDÉPENDANT d'une vacation : recalcul minute par minute (sans découpage en tranches).
    Retourne (coût brut, vente brute, minutes payées)."""
    start, end = day_result["start"], day_result["end"]
    holidays = holidays_between(start.date(), end.date())
    flags = WS_KIND_FLAGS.get(day_result["kind"])
    step = timedelta(minutes=1)
    cost = sale = minutes = WS_ZERO
    current = start
    while current < end:
        weight = dst_hour_factor(current, current + step, start, end)
        if weight:
            if flags is not None:
                sunday, holiday = flags
            else:
                sunday, holiday = current.weekday() == 6, current.date() in holidays
            coef = ws_coefficient(mode, app.is_night(current), sunday, holiday, day_result["other"], rates)
            w = Decimal(weight)
            minutes += w
            cost += w * rates["cost"] * coef
            sale += w * rates["sale"] * coef
        current += step
    if minutes <= 0:
        return WS_ZERO, WS_ZERO, WS_ZERO
    scale = (minutes - day_result["pause"]) / minutes
    return cost * scale / 60, sale * scale / 60, minutes - day_result["pause"]


def ws_reference_cases():
    """Cas de référence calculés À LA MAIN (taux : coût 15 €/h, vente 20 €/h, nuit +10 %,
    dimanche +20 %, férié +50 %, plage de nuit 22:00-06:00)."""
    W = lambda start, end, **kw: dict(statut="Travail", debut=start, fin=end, **kw)
    mon = date(2026, 10, 5)
    five = {i: W("08:00", "16:00") for i in range(5)}
    nine = {i: W("08:00", "17:00") for i in range(5)}
    return [
        ("8 h en semaine : 8 × 15", mon, {0: W("08:00", "16:00")}, {}, "120.00", "160.00"),
        ("8 h avec 30 min de pause : 7,5 × 15", mon, {0: W("08:00", "16:00", pause="30")}, {}, "112.50", "150.00"),
        ("20:00-02:00 (4 h de nuit) : 15 × (2 + 4 × 1,10)", mon, {0: W("20:00", "02:00")}, {}, "96.00", "128.00"),
        ("Dimanche 8 h (+20 %) : 8 × 15 × 1,2", mon, {6: W("08:00", "16:00")}, {"maj_dim": "20"}, "144.00", "192.00"),
        ("Samedi 22:00 -> dimanche 06:00 : 15 × (2 × 1,1 + 6 × 1,32)", mon,
         {5: W("22:00", "06:00")}, {"maj_dim": "20"}, "151.80", "202.40"),
        ("Autre majoration +10 % : 8 × 15 × 1,1", mon, {0: W("08:00", "16:00", autre="10")}, {}, "132.00", "176.00"),
        ("40 h + heures sup. (5 h à 25 %) : 600 + 18,75", mon, five,
         {"ot_on": True, "ot_t1_rate": "25", "ot_t2_rate": "50"}, "618.75", "825.00"),
        ("45 h + heures sup. (8 h à 25 %, 2 h à 50 %) : 675 + 45", mon, nine,
         {"ot_on": True, "ot_t1_rate": "25", "ot_t2_rate": "50"}, "720.00", "960.00"),
        ("Toussaint = dimanche + férié, multiplicatif : 8 × 15 × 1,2 × 1,5", date(2026, 10, 26),
         {6: W("08:00", "16:00")}, {"maj_dim": "20", "maj_ferie": "50"}, "216.00", "288.00"),
        ("Toussaint = dimanche + férié, additif : 8 × 15 × 1,7", date(2026, 10, 26),
         {6: W("08:00", "16:00")}, {"maj_dim": "20", "maj_ferie": "50", "_mode": "additive"}, "204.00", "272.00"),
        ("11 novembre (mercredi férié) : 8 × 15 × 1,5", date(2026, 11, 9),
         {2: W("08:00", "16:00")}, {"maj_ferie": "50"}, "180.00", "240.00"),
        ("Dimanche 25/10/2026 00:00-06:00 (heure d'hiver, 7 h réelles) : 15 × 7 × 1,32", date(2026, 10, 19),
         {6: W("00:00", "06:00")}, {"maj_dim": "20"}, "138.60", "184.80"),
        ("Dimanche 29/03/2026 00:00-06:00 (heure d'été, 5 h réelles) : 15 × 5 × 1,32", date(2026, 3, 23),
         {6: W("00:00", "06:00")}, {"maj_dim": "20"}, "99.00", "132.00"),
        ("Congé payé non compté en heures travaillées", mon,
         {0: W("08:00", "16:00"), 1: dict(statut="Congé payé")}, {}, "120.00", "160.00"),
        ("Prime 12,50 € (coût uniquement)", mon, {0: W("08:00", "16:00", prime="12.5")}, {}, "132.50", "160.00"),
        ("Arrondi : 1 h à 14,995 €/h -> 15,00 € (demi-centime vers le haut)", mon,
         {0: W("08:00", "09:00")}, {"rate_cost": "14.995"}, "15.00", "20.00"),
        ("Deux jours liés : 14:00-23:00 puis 06:00-14:00", mon,
         {0: W("14:00", "23:00"), 1: W("06:00", "14:00")}, {}, "256.50", "342.00"),
    ]


def ws_run_reference_cases(engine):
    """Exécute les cas de référence. Retourne une liste (libellé, attendu, obtenu, ok)."""
    results = []
    for label, monday, days, mods, exp_cost, exp_sale in ws_reference_cases():
        sheet = ws_make_sheet()
        for index, entry in days.items():
            sheet["days"][index].update(entry)
        mode = mods.get("_mode")
        for key, value in mods.items():
            if key != "_mode":
                sheet[key] = value
        week = ws_compute_week(engine, monday, sheet, mode=mode)
        got = "%s / %s" % (ws_cents(week["cost"]), ws_cents(week["sale"]))
        want = "%s / %s" % (exp_cost, exp_sale)
        results.append((label, want, got, got == want))
    # Alertes réglementaires
    sheet = ws_make_sheet()
    sheet["days"][0].update(statut="Travail", debut="08:00", fin="20:00")
    week = ws_compute_week(engine, date(2026, 10, 5), sheet)
    flagged = any("10 h" in a for a in week["days"][0]["alerts"])
    results.append(("Alerte > 10 h de travail effectif (12 h saisies)", "alerte", "alerte" if flagged else "aucune", flagged))
    sheet = ws_make_sheet()
    sheet["days"][0].update(statut="Travail", debut="14:00", fin="23:00")
    sheet["days"][1].update(statut="Travail", debut="06:00", fin="14:00")
    week = ws_compute_week(engine, date(2026, 10, 5), sheet)
    flagged = any("11 h" in a for a in week["days"][1]["alerts"])
    results.append(("Alerte repos quotidien < 11 h (7 h entre deux vacations)", "alerte", "alerte" if flagged else "aucune", flagged))
    return results


def ws_verification_report(app, monday, sheet, week):
    """Rapport de contrôle : (tout_ok, lignes). 1) recalcul minute par minute de la feuille affichée,
    2) cohérence des totaux, 3) cas de référence calculés à la main."""
    lines, ok_all = [], True
    with _ws_localcontext() as ctx:
        ctx.prec = 40
        lines.append("1) Recalcul indépendant minute par minute — semaine du %s" % monday.strftime("%d/%m/%Y"))
        checked = 0
        for d in week["days"]:
            if not d["worked"]:
                continue
            cost, sale, minutes = ws_minutewise(app, d, week["rates"], week["mode"])
            good = (abs(cost - d["cost_raw"]) <= WS_EPS and abs(sale - d["sale_raw"]) <= WS_EPS
                    and abs(minutes - d["minutes"]) <= WS_EPS)
            ok_all = ok_all and good
            checked += 1
            lines.append("   %s %s : moteur %s € / contrôle %s € %s" % (
                WS_DAY_NAMES[d["date"].weekday()], d["date"].strftime("%d/%m"),
                ws_cents(d["cost_raw"]), ws_cents(cost), "✔" if good else "✘ ÉCART"))
        if not checked:
            lines.append("   (aucune vacation saisie sur cette semaine)")
        lines.append("2) Cohérence des totaux")
        sum_cost = sum((d["cost"] for d in week["days"]), WS_ZERO) + week["overtime"]["cost"]
        sum_sale = sum((d["sale"] for d in week["days"]), WS_ZERO) + week["overtime"]["sale"]
        sum_min = sum((d["minutes"] for d in week["days"]), WS_ZERO)
        checks = [
            ("Σ coûts journaliers + heures sup. = coût total", sum_cost == week["cost"]),
            ("Σ ventes journalières + heures sup. = vente totale", sum_sale == week["sale"]),
            ("Σ minutes journalières = minutes de la semaine", sum_min == week["minutes"]),
            ("Aucun montant négatif", week["cost"] >= 0 and week["sale"] >= 0),
        ]
        for label, good in checks:
            ok_all = ok_all and good
            lines.append("   %s %s" % ("✔" if good else "✘", label))
        engine = WsEngine({"night_start": "22:00", "night_end": "06:00", "mode": "multiplicative"})
        lines.append("3) Cas de référence calculés à la main")
        for label, want, got, good in ws_run_reference_cases(engine):
            ok_all = ok_all and good
            lines.append("   %s %s  [attendu %s | obtenu %s]" % ("✔" if good else "✘", label, want, got))
    lines.append("")
    lines.append("RÉSULTAT : " + ("TOUS LES CONTRÔLES SONT VALIDÉS ✔" if ok_all else "ÉCART DÉTECTÉ ✘ — ne pas utiliser ces montants"))
    return ok_all, lines


class WsEngine(object):
    """Moteur autonome (sans fenêtre) : emprunte le découpage en tranches de GergovieApp.
    Sert aux cas de référence, qui doivent rester indépendants des réglages du dossier."""

    def __init__(self, project):
        self.project = dict(project)

    def _segments(self, start, end):
        return GergovieApp._segments(self, start, end)

    def _night_window(self):
        return GergovieApp._night_window(self)

    def is_night(self, moment):
        return GergovieApp.is_night(self, moment)


