    def configure_style(self):
        if self.dark_mode:
            # Palette HACKING : noir profond, vert néon et accents lumineux.
            # Le rouge reste réservé aux alertes, erreurs et actions sensibles.
            self.colors = {
                "background": "#090711",
                "surface": "#100D18",
                "surface_2": "#191323",
                "border": "#35223C",
                "text": "#E8FFF0",
                "muted": "#91B7A0",
                "primary": "#21C55D",
                "primary_dark": "#16803B",
                "accent": "#39FF88",
                "accent_dark": "#1BAA56",
                "accent2": "#D946EF",
                "neon": "#39FF88",
                "nav": "#05040A",
                "nav_hover": "#17101D",
                "nav_active": "#281532",
                "success": "#39FF88",
                "warning": "#FCEE0A",
                "danger": "#FF3355",
            }
        else:
            # Variante claire : surfaces claires, accents vert forêt
            self.colors = {
                "background": "#F4EEF6",
                "surface": "#FFFFFF",
                "surface_2": "#E8DFEA",
                "border": "#BBA9C4",
                "text": "#102318",
                "muted": "#526D5A",
                "primary": "#16803B",
                "primary_dark": "#10632D",
                "accent": "#16803B",
                "accent_dark": "#12632F",
                "accent2": "#C026D3",
                "neon": "#21C55D",
                "nav": "#201426",
                "nav_hover": "#34213C",
                "nav_active": "#4A2A53",
                "success": "#0A9B55",
                "warning": "#B77900",
                "danger": "#D4143A",
            }

        self.configure(bg=self.colors["background"])

        style = ttk.Style(self)
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass

        style.configure(
            ".",
            font=("Consolas", 10),
            background=self.colors["background"],
            foreground=self.colors["text"],
        )
        style.configure(
            "TFrame",
            background=self.colors["background"],
        )
        style.configure(
            "Card.TFrame",
            background=self.colors["surface"],
        )
        style.configure(
            "TLabel",
            background=self.colors["background"],
            foreground=self.colors["text"],
        )
        style.configure(
            "Card.TLabel",
            background=self.colors["surface"],
            foreground=self.colors["text"],
        )
        style.configure(
            "Muted.TLabel",
            background=self.colors["background"],
            foreground=self.colors["muted"],
            font=("Consolas", 9),
        )
        style.configure(
            "CardMuted.TLabel",
            background=self.colors["surface"],
            foreground=self.colors["muted"],
            font=("Consolas", 9),
        )
        style.configure(
            "Title.TLabel",
            background=self.colors["background"],
            foreground=self.colors["text"],
            font=("Consolas", 22, "bold"),
        )
        style.configure(
            "Section.TLabel",
            background=self.colors["background"],
            foreground=self.colors["text"],
            font=("Consolas", 14, "bold"),
        )
        style.configure(
            "CardTitle.TLabel",
            background=self.colors["surface"],
            foreground=self.colors["text"],
            font=("Consolas", 11, "bold"),
        )
        style.configure(
            "Kpi.TLabel",
            background=self.colors["surface"],
            foreground=self.colors["text"],
            font=("Consolas", 18, "bold"),
        )
        # --- Boutons (MODERNISATION) : normal / survolé / enfoncé / désactivé ---
        def make_button(name, bg, fg, hover, pressed, border=None, hover_border=None):
            border = border or bg
            hover_border = hover_border or hover
            off = self.colors["surface_2"]
            style.configure(
                name, background=bg, foreground=fg, padding=(14, 9),
                font=("Consolas", 9, "bold"), relief="flat", borderwidth=1,
                bordercolor=border, lightcolor=bg, darkcolor=bg, focuscolor=bg,
            )
            style.map(
                name,
                background=[("disabled", off), ("pressed", pressed), ("active", hover)],
                foreground=[("disabled", self.colors["muted"])],
                bordercolor=[("disabled", self.colors["border"]), ("pressed", pressed), ("active", hover_border)],
                lightcolor=[("disabled", off), ("pressed", pressed), ("active", hover)],
                darkcolor=[("disabled", off), ("pressed", pressed), ("active", hover)],
            )

        make_button(
            "TButton", self.colors["surface_2"], self.colors["accent"],
            blend_hex(self.colors["surface_2"], self.colors["accent"], 0.72),
            blend_hex(self.colors["surface_2"], self.colors["accent"], 0.50),
            border=self.colors["accent_dark"], hover_border=self.colors["accent2"],
        )
        make_button(
            "Primary.TButton", self.colors["primary"], "white",
            blend_hex(self.colors["primary"], "#FFFFFF", 0.86), self.colors["primary_dark"],
        )
        make_button(
            "Accent.TButton", self.colors["accent"], "#04222B",
            blend_hex(self.colors["accent"], "#FFFFFF", 0.82), self.colors["accent_dark"],
        )
        make_button(
            "Danger.TButton", self.colors["danger"], "white",
            blend_hex(self.colors["danger"], "#FFFFFF", 0.85), blend_hex(self.colors["danger"], "#000000", 0.78),
        )
        style.configure(
            "Treeview",
            background=self.colors["surface"],
            fieldbackground=self.colors["surface"],
            foreground=self.colors["text"],
            rowheight=32,
            font=("Consolas", 9),
        )
        style.configure(
            "Treeview.Heading",
            background=self.colors["nav"],
            foreground=self.colors["neon"],
            font=("Consolas", 9, "bold"),
            padding=(10, 10),
            relief="flat",
        )
        style.configure(
            "TEntry",
            padding=6,
            fieldbackground=self.colors["surface_2"],
            foreground=self.colors["text"],
            insertcolor=self.colors["text"],
        )
        style.map(
            "TEntry",
            fieldbackground=[("readonly", self.colors["surface_2"]), ("disabled", self.colors["surface"])],
            foreground=[("disabled", self.colors["muted"])],
        )
        style.configure(
            "TCombobox",
            padding=5,
            fieldbackground=self.colors["surface_2"],
            background=self.colors["surface_2"],
            foreground=self.colors["text"],
            arrowcolor=self.colors["text"],
        )
        style.map(
            "TCombobox",
            fieldbackground=[("readonly", self.colors["surface_2"]), ("disabled", self.colors["surface"])],
            foreground=[("disabled", self.colors["muted"])],
            selectbackground=[("readonly", self.colors["surface_2"])],
            selectforeground=[("readonly", self.colors["text"])],
        )
        style.configure(
            "TSpinbox",
            padding=5,
            fieldbackground=self.colors["surface_2"],
            foreground=self.colors["text"],
            arrowcolor=self.colors["text"],
        )
        # Champs de saisie : bordure discrète, liseré cyan au focus (MODERNISATION)
        for field_style in ("TEntry", "TCombobox", "TSpinbox"):
            style.configure(
                field_style, bordercolor=self.colors["border"],
                lightcolor=self.colors["border"], darkcolor=self.colors["border"],
            )
            style.map(
                field_style, bordercolor=[("focus", self.colors["accent"])],
                lightcolor=[("focus", self.colors["accent"])], darkcolor=[("focus", self.colors["accent"])],
            )
        style.configure(
            "TNotebook",
            background=self.colors["background"],
            borderwidth=0,
        )
        style.configure(
            "TNotebook.Tab",
            background=self.colors["surface_2"],
            foreground=self.colors["text"],
            padding=(16, 10),
            font=("Consolas", 9, "bold"),
        )
        style.map(
            "TNotebook.Tab",
            background=[
                ("selected", self.colors["primary"]),
                ("active", blend_hex(self.colors["surface_2"], self.colors["accent"], 0.80)),
            ],
            foreground=[("selected", "white")],
        )
        style.configure(
            "TCheckbutton",
            background=self.colors["surface"],
            foreground=self.colors["text"],
        )
        style.map(
            "TCheckbutton",
            background=[("active", self.colors["surface"])],
            foreground=[("active", self.colors["text"])],
        )
        style.configure(
            "TRadiobutton",
            background=self.colors["surface"],
            foreground=self.colors["text"],
        )
        style.map(
            "TRadiobutton",
            background=[("active", self.colors["surface"])],
            foreground=[("active", self.colors["text"])],
        )
        style.map(
            "Treeview",
            background=[("selected", self.colors["primary"])],
            foreground=[("selected", "white")],
        )
        style.configure(
            "Vertical.TScrollbar",
            background=self.colors["surface_2"], troughcolor=self.colors["background"],
            bordercolor=self.colors["background"], arrowcolor=self.colors["muted"], arrowsize=13,
        )
        style.configure(
            "Horizontal.TScrollbar",
            background=self.colors["surface_2"], troughcolor=self.colors["background"],
            bordercolor=self.colors["background"], arrowcolor=self.colors["muted"], arrowsize=13,
        )

        # Menus déroulants natifs (listes Combobox) : ils ne sont pas gérés
        # par ttk.Style et doivent être forcés via la base d'options Tk,
        # sinon le texte reste illisible en mode sombre.
        self.option_add("*TCombobox*Listbox.background", self.colors["surface_2"])
        self.option_add("*TCombobox*Listbox.foreground", self.colors["text"])
        self.option_add("*TCombobox*Listbox.selectBackground", self.colors["primary"])
        self.option_add("*TCombobox*Listbox.selectForeground", "white")
        self.option_add("*Menu.background", self.colors["surface"])
        self.option_add("*Menu.foreground", self.colors["text"])
        self.option_add("*Menu.activeBackground", self.colors["primary"])
        self.option_add("*Menu.activeForeground", "white")

    def rebuild_interface(self):
        for child in self.winfo_children():
            child.destroy()

        self.configure_style()
        self.build_interface()
        self.show_page(self.current_page)

    def toggle_theme(self):
        previous = dict(self.colors)
        self.dark_mode = not self.dark_mode
        self.project["theme"] = "dark" if self.dark_mode else "light"
        self.rebuild_interface()
        self.fx_curtain(previous["background"], previous["accent"])

