    def _update_page_scrollregion(self, event=None):
        if hasattr(self, "page_canvas") and self.page_canvas.winfo_exists():
            box = self.page_canvas.bbox("all")
            if box:
                shift = getattr(self, "_fx_slide_offset", 0)   # décalage temporaire de l'animation d'entrée
                box = (box[0], box[1] - shift, box[2], box[3] - shift)
            self.page_canvas.configure(scrollregion=box)

    def _resize_page_content(self, event=None):
        if not hasattr(self, "page_canvas") or not self.page_canvas.winfo_exists():
            return
        width = max(1, self.page_canvas.winfo_width() - 52)
        self.page_canvas.itemconfigure(self.page_window, width=width)
        self._update_page_scrollregion()

    def _pointer_is_over_page(self, event):
        if not hasattr(self, "page_canvas"):
            return False
        widget = self.winfo_containing(event.x_root, event.y_root)
        if widget is None:
            return False
        current = widget
        while current is not None:
            if current == self.page_canvas or current == self.page_frame:
                return True
            try:
                current = current.master
            except AttributeError:
                break
        return False

    def _on_page_mousewheel(self, event):
        if not self._pointer_is_over_page(event):
            return
        if getattr(event, "num", None) == 4:
            delta = -3
        elif getattr(event, "num", None) == 5:
            delta = 3
        else:
            delta = -int(event.delta / 120) if event.delta else 0
        if delta:
            self.page_canvas.yview_scroll(delta, "units")
            return "break"

    def build_sidebar(self):
        sidebar = tk.Frame(
            self,
            bg=self.colors["nav"],
            width=250,
        )
        self.sidebar = sidebar
        sidebar.pack(side="left", fill="y")
        sidebar.pack_propagate(False)
        self.nav_buttons = {}
        self.nav_indicators = {}

        # Logo transparent posé directement sur le fond de la barre latérale.
        brand = tk.Frame(sidebar, bg=self.colors["nav"])
        brand.pack(fill="x", padx=18, pady=(18, 0))
        if self.brand_logo_image is not None:
            tk.Label(brand, image=self.brand_logo_image, bg=self.colors["nav"], bd=0).pack(anchor="center")
        else:
            tk.Label(
                brand, text="GERGOVIE\nLYCÉE DES MÉTIERS", bg=self.colors["nav"],
                fg="#E0E8F1", font=("Segoe UI", 12, "bold"), justify="center",
            ).pack(fill="x", padx=4, pady=8)
        tk.Label(
            brand, text="OUTIL DE GESTION SÉCURITÉ", bg=self.colors["nav"],
            fg="#E8FFF0", font=("Segoe UI", 8, "bold"),
        ).pack(anchor="center", pady=(4, 0))

        tk.Label(
            sidebar,
            text="VOTRE DOSSIER",
            bg=self.colors["nav"],
            fg="#94A3B8",
            font=("Consolas", 8, "bold"),
        ).pack(anchor="w", padx=22, pady=(20, 8))

        self.category_buttons = {}
        self.tool_buttons = {}
        self.bloc_frames = {}

        def nav_button(parent, key, icon, label, command, indent=10, size=10, pady=9):
            # Ligne = liseré d'état (cyan quand actif) + bouton d'origine (même commande).
            row = tk.Frame(parent, bg=self.colors["nav"])
            row.pack(fill="x", padx=indent, pady=1)
            indicator = tk.Frame(row, bg=self.colors["nav"], width=4)
            indicator.pack(side="left", fill="y")
            button = tk.Button(
                row, text=f"  {icon}   {label}", anchor="w", justify="left", wraplength=200,
                relief="flat", bd=0, padx=12, pady=pady, cursor="hand2",
                bg=self.colors["nav"], fg="#CBD5E1",
                activebackground=self.colors["nav_hover"], activeforeground="white",
                font=("Consolas", size, "bold" if size >= 10 else "normal"), command=command,
            )
            button.pack(side="left", fill="x", expand=True)

            def on_enter(event, name=key, widget=button):
                if name != self._active_nav_key():
                    if self.fx.enabled:
                        self.fx_nav_hover(widget, True)
                    else:
                        widget.configure(bg=self.colors["nav_hover"])

            def on_leave(event, widget=button):
                if self.fx.enabled:
                    self.fx_nav_hover(widget, False)
                self._highlight_nav()

            button.bind("<Enter>", on_enter, add="+")
            button.bind("<Leave>", on_leave, add="+")
            self.nav_buttons[key] = button
            self.nav_indicators[key] = indicator
            return button

        nav_button(sidebar, "home", "⌂", "Accueil", lambda: self.show_page("home"))

        blocs = [
            ("I", "BLOC I — Préparation et mise en œuvre d'une prestation de sécurité", [
                ("project", "📖", "Informations", lambda: self.show_page("project")),
                ("tariffs", "💵", "Tarifs", lambda: self.show_page("tariffs")),
                ("planning", "🕓", "Planning des missions", lambda: self.show_page("planning")),
                ("safety_dossier", "🛡", "Dossier de sécurité", lambda: self.show_page("safety_dossier")),
                ("planning_generator", "🗓", "Créateur de planning", self.open_planning_generator),
                ("veille", "🔎", "Veille réglementaire et technologique", self.open_veille),
                ("summary", "📊", "Résultat, bilan et graphique", lambda: self.show_page("summary")),
            ]),
            ("II", "BLOC II — Management des ressources humaines", [
                ("mgmt0", "👥", "Effectif & habilitations", self.open_integrated_bloc2),
                ("recruitment", "🧑‍💼", "Recrutement & intégration", lambda: self.show_page("recruitment")),
            ]),
            ("III", "BLOC III — Gestion de la relation client", [
                ("calculator", "🧮", "Calculateur prix / TVA & convertisseurs", self.open_commercial_calculator),
                ("crm", "🤝", "Clients & opportunités", lambda: self.show_page("crm")),
            ]),
        ]
        for key, title, entries in blocs:
            header = tk.Button(
                sidebar, text="", anchor="w", justify="left", wraplength=210, relief="flat", bd=0,
                padx=14, pady=8, cursor="hand2", bg=self.colors["nav"], fg=self.colors["neon"],
                activebackground=self.colors["nav_hover"], activeforeground="white",
                font=("Consolas", 8, "bold"), command=lambda k=key: self._toggle_bloc(k),
            )
            header.pack(fill="x", padx=10, pady=(14, 2))
            header.bind("<Enter>", lambda event, item=header: item.configure(bg=self.colors["nav_hover"]), add="+")
            header.bind("<Leave>", lambda event, item=header: item.configure(bg=self.colors["nav"]), add="+")
            self.category_buttons[key] = (header, title)
            frame = tk.Frame(sidebar, bg=self.colors["nav"])
            self.bloc_frames[key] = frame
            for page_key, icon, label, command in entries:
                button = nav_button(frame, page_key, icon, label, command, indent=6, size=9, pady=6)
                self.tool_buttons[page_key] = button
            self._set_bloc(key, self.bloc_open.get(key, False))

        tk.Frame(sidebar, bg=self.colors["nav"]).pack(fill="both", expand=True)

        tk.Frame(sidebar, bg=self.colors["border"], height=1).pack(fill="x", padx=18, pady=(4, 6))

        theme_button = tk.Button(
            sidebar,
            text="☾  Mode sombre" if not self.dark_mode else "☀  Mode clair",
            anchor="w",
            relief="flat",
            bd=0,
            padx=14,
            pady=10,
            cursor="hand2",
            bg=self.colors["nav"],
            fg="#CBD5E1",
            activebackground=self.colors["nav_hover"],
            activeforeground="white",
            font=("Consolas", 9),
            command=self.toggle_theme,
        )
