    PAGE_BLOC = {
        "project": "I", "tariffs": "I", "planning": "I", "planning_generator": "I", "veille": "I", "summary": "I",
        "safety_dossier": "I", "prevention_plan": "I",
        "management": "II", "schedule": "II", "recruitment": "II",
        "calculator": "III", "crm": "III", "client_followup": "III",
    }

    def _set_bloc(self, key, opened):
        header, title = self.category_buttons[key]
        frame = self.bloc_frames[key]
        self.bloc_open[key] = opened
        header.configure(text=("▾  " if opened else "▸  ") + title)
        if opened:
            frame.pack(fill="x", after=header)
        else:
            frame.pack_forget()

    def _toggle_bloc(self, key):
        self._set_bloc(key, not self.bloc_open.get(key, False))

    def _ensure_bloc_open(self, page):
        key = self.PAGE_BLOC.get(page)
        if key and not self.bloc_open.get(key) and key in self.category_buttons:
            self._set_bloc(key, True)

    def _active_nav_key(self):
        page = self.current_page
        if page == "management":
            return "mgmt%d" % min(getattr(self, "mgmt_tab", 0), 2)
        return page

    def _highlight_nav(self):
        active = self._active_nav_key()
        indicators = getattr(self, "nav_indicators", {})
        for name, button in self.nav_buttons.items():
            try:
                selected = name == active
                button.configure(
                    bg=self.colors["nav_active"] if selected else self.colors["nav"],
                    fg="white" if selected else "#CBD5E1",
                    activebackground=self.colors["nav_active"] if selected else self.colors["nav_hover"],
                    activeforeground="white",
                )
                indicator = indicators.get(name)
                if indicator is not None:
                    indicator.configure(bg=self.colors["neon"] if selected else self.colors["nav"])
            except tk.TclError:
                pass
        self.fx_nav_selected(active)

    def _update_section_chip(self, page):
        """Affiche le bloc (I / II / III) de la page active à côté du titre."""
        chip = getattr(self, "section_chip", None)
        if chip is None:
            return
        labels = {"I": "BLOC I", "II": "BLOC II", "III": "BLOC III"}
        key = self.PAGE_BLOC.get(page)
        try:
            if key:
                chip.configure(text=labels[key])
                chip.pack(side="left", after=self.page_title)
            else:
                chip.pack_forget()
        except tk.TclError:
            pass

