    def _animate_page_transition(self):
        """Balaye un fin repère coloré sous la barre de titre lors d'un changement de page."""
        canvas = getattr(self, "page_transition", None)
        if canvas is None or not canvas.winfo_exists():
            return
        if self._page_transition_job is not None:
            try:
                self.after_cancel(self._page_transition_job)
            except tk.TclError:
                pass
            self._page_transition_job = None
        canvas.delete("page-sweep")
        width = max(1, canvas.winfo_width())
        accent = canvas.create_rectangle(0, 0, 0, 3, fill=self.colors["accent"], outline="", tags="page-sweep")
        step = max(16, width // 28)

        def advance(position=0):
            if not canvas.winfo_exists():
                return
            next_position = min(width, position + step)
            canvas.coords(accent, 0, 0, next_position, 3)
            if next_position < width:
                self._page_transition_job = self.after(12, lambda: advance(next_position))
            else:
                self._page_transition_job = self.after(260, lambda: canvas.delete("page-sweep"))

        advance()

