    def build_veille(self):
        """Intègre l'application de veille dans le conteneur de page courant."""
        self.add_section_heading(
            self.page_frame,
            "Veille réglementaire et technologique",
            "Suivez les évolutions réglementaires, technologiques et les équipements depuis le dashboard.",
        )
        container = tk.Frame(self.page_frame, bg=self.colors["background"])
        container.pack(fill="both", expand=True)
        try:
            if not hasattr(self, "_veille_namespace"):
                import base64
                self._veille_namespace = {"__name__": "gergovie_embedded_veille"}
                source = base64.b64decode(VEILLE_RT_SOURCE_B64).decode("utf-8")
                source = source.replace(
                    '        root.title(NOM_APP + " - EduPython")\n', ""
                ).replace(
                    '        root.geometry("1150x760")\n', ""
                )
                exec(compile(source, "OUTIL BLOC 1 VEILLE RT.py", "exec"),
                     self._veille_namespace)
            self.veille_app = self._veille_namespace["VeilleApp"](container)
        except Exception as exc:
            container.destroy()
            messagebox.showerror("Ouverture de la veille impossible", str(exc), parent=self)

    def open_planning_generator(self):
        self.show_page("planning_generator")

    def _parse_pg_date(self, value):
        return datetime.strptime(value.strip(), "%d/%m/%Y").date()

    def _parse_pg_time(self, value):
        return datetime.strptime(value.strip(), "%H:%M").time()

    def _pg_interval(self, day, start_time, end_time):
        start = datetime.combine(day, start_time)
        end = datetime.combine(day, end_time)
        if end <= start:
            end += timedelta(days=1)
        return start, end

    def load_planning_generator_example(self):
        self.pg_start_var.set(date.today().strftime("%d/%m/%Y"))
        self.pg_end_var.set((date.today() + timedelta(days=2)).strftime("%d/%m/%Y"))
        self.pg_start_time_var.set("18:00")
        self.pg_end_time_var.set("06:00")
        self.pg_agents_var.set("4")
        self.pg_posts_var.set("2")
        self.pg_amp_var.set("12")
        self.generate_planning_template()

    def clear_planning_generator(self):
        if hasattr(self, "pg_tree"):
            self.pg_tree.delete(*self.pg_tree.get_children())
        self.generator_rows = []
        if hasattr(self, "pg_status"):
            self.pg_status.configure(
                text="Planning effacé. Renseignez les paramètres puis générez une nouvelle trame.",
                fg=self.colors["muted"],
            )

    def _refresh_pg_qualification_choices(self):
        found = set()
        for emp in self.employees:
            found.update(emp.get("qualifications") or [])
        choices = ["Toutes"] + sorted(found or set(self.QUALIFICATIONS_DISPONIBLES))
        current = self.pg_qualification_var.get()
        self.pg_qualification_combo.configure(values=choices)
        if current not in choices:
            self.pg_qualification_var.set("Toutes")

    def generate_planning_template(self):
        if not hasattr(self, "pg_tree"):
            return

        try:
            start_date = self._parse_pg_date(self.pg_start_var.get())
            end_date = self._parse_pg_date(self.pg_end_var.get())
            start_time = self._parse_pg_time(self.pg_start_time_var.get())
            end_time = self._parse_pg_time(self.pg_end_time_var.get())
            agent_count = int(self.pg_agents_var.get())
            post_count = int(self.pg_posts_var.get())
            max_amplitude = float(self.pg_amp_var.get())
        except (ValueError, TypeError):
            messagebox.showerror(
                "Paramètres invalides",
                "Vérifiez les dates (JJ/MM/AAAA), horaires (HH:MM), nombres d'agents/postes et l'amplitude maximale.",
            )
            return

        if end_date < start_date:
            messagebox.showerror("Dates invalides", "La date de fin doit être postérieure ou égale à la date de début.")
            return
        if agent_count < 1 or post_count < 1 or max_amplitude <= 0:
            messagebox.showerror("Paramètres invalides", "Les agents, postes et l'amplitude doivent être supérieurs à zéro.")
            return

        total_days = (end_date - start_date).days + 1
        if total_days > 366:
            messagebox.showerror("Période trop longue", "La génération est limitée à 366 jours.")
            return

        # Une trame par poste et par jour. Si moins d'agents que de postes,
        # la réutilisation d'un agent sur des postes simultanés est volontairement
        # conservée et signalée comme conflit.
        generated = []
        required_qualification = getattr(self, "pg_qualification_var", None)
        required_qualification = required_qualification.get() if required_qualification else "Toutes"
        qualification_shortfall = 0
        if required_qualification and required_qualification != "Toutes":
            qualified_employees = [
                e.get("nom", "") for e in self.employees
                if required_qualification in (e.get("qualifications") or []) and e.get("nom")
            ]
            if qualified_employees:
                agent_names = []
                for i in range(agent_count):
                    if i < len(qualified_employees):
                        agent_names.append(qualified_employees[i])
                    else:
                        agent_names.append(f"Agent {i + 1} (⚠ sans « {required_qualification} »)")
                        qualification_shortfall += 1
            else:
                agent_names = [f"Agent {i} (⚠ sans « {required_qualification} »)" for i in range(1, agent_count + 1)]
                qualification_shortfall = agent_count
        else:
            agent_names = [f"Agent {i}" for i in range(1, agent_count + 1)]

        current = start_date
        day_index = 0
        while current <= end_date:
            start_dt, end_dt = self._pg_interval(current, start_time, end_time)
            duration = self._real_hours(start_dt, end_dt)

            for post_idx in range(post_count):
                agent = agent_names[(day_index * post_count + post_idx) % agent_count]
                generated.append({
                    "date": current,
                    "poste": f"Poste {post_idx + 1}",
                    "start": start_dt,
                    "end": end_dt,
                    "agent": agent,
                    "duration": duration,
                    "alerts": [],
                })
            current += timedelta(days=1)
            day_index += 1

        # Détection agent affecté deux fois sur des créneaux qui se chevauchent.
        for i, row in enumerate(generated):
            for j in range(i + 1, len(generated)):
                other = generated[j]
                if row["agent"] != other["agent"]:
                    continue
                if row["start"] < other["end"] and other["start"] < row["end"]:
                    row["alerts"].append("⚠ Agent affecté deux fois")
                    other["alerts"].append("⚠ Agent affecté deux fois")
                    # Deux postes simultanés avec le même agent impliquent
                    # qu'au moins un des postes ne peut pas être physiquement couvert.
                    other["alerts"].append("⚠ Poste non couvert")

        # Détection des postes simultanément non couverts / sur-affectés.
        # La génération crée une ligne par poste, donc un poste est couvert
        # sauf si aucun agent n'est disponible. On signale ici le manque
        # structurel d'agents par rapport aux postes.
        structural_warning = agent_count < post_count
        if structural_warning:
            for row in generated:
                row["alerts"].append("⚠ Nombre d'agents insuffisant pour tous les postes")

        # Détection d'amplitude importante.
        for row in generated:
            if row["duration"] > max_amplitude:
                row["alerts"].append(
                    f"⚠ Amplitude importante ({row['duration']:.1f} h)"
                )

        # Détection de poste non couvert par date : chaque date doit avoir
        # exactement un créneau pour chaque poste.
        expected = {(r["date"], r["poste"]) for r in generated}
        actual = {(r["date"], r["poste"]) for r in generated}
        missing = expected - actual
        if missing:
            for row in generated:
                if (row["date"], row["poste"]) in missing:
                    row["alerts"].append("⚠ Poste non couvert")

        # Si une affectation est en conflit, le poste concerné est également
        # considéré comme à vérifier pour la couverture opérationnelle.
        for row in generated:
            if not row["alerts"]:
                row["alerts"].append("✓ OK")

        self.generator_rows = generated
        self.pg_tree.delete(*self.pg_tree.get_children())

        conflict_count = 0
        amplitude_count = 0
        for row in generated:
            alerts = " • ".join(row["alerts"])
            if any("⚠" in alert for alert in row["alerts"]):
                if any("Amplitude" in alert or "insuffisant" in alert for alert in row["alerts"]):
                    tag = "warning"
                else:
                    tag = "danger"
                conflict_count += 1
                if any("Amplitude" in alert for alert in row["alerts"]):
                    amplitude_count += 1
            else:
                tag = "ok"

            self.pg_tree.insert(
                "",
                "end",
                values=(
                    row["date"].strftime("%d/%m/%Y"),
                    row["poste"],
                    row["start"].strftime("%d/%m/%Y %H:%M"),
                    row["end"].strftime("%d/%m/%Y %H:%M"),
                    row["agent"],
                    f"{row['duration']:.2f} h",
                    alerts,
                ),
                tags=(tag,),
            )

        summary = (
            f"{len(generated)} affectations générées • "
            f"{total_days} jour(s) • {post_count} poste(s) • {agent_count} agent(s) • "
            f"{conflict_count} ligne(s) à vérifier"
        )
        if structural_warning:
            summary += " • ⚠ effectif inférieur au nombre de postes"
        if amplitude_count:
            summary += f" • ⚠ {amplitude_count} amplitude(s) importante(s)"
        if qualification_shortfall:
            summary += f" • ⚠ {qualification_shortfall} agent(s) sans la qualification « {required_qualification} »"

        self.pg_status.configure(
            text=summary,
            fg=self.colors["danger"] if conflict_count else self.colors["success"],
        )

    # ------------------------------------------------------------------
    # Charges d'exploitation / management V9
    # ------------------------------------------------------------------

    def _safe_float(self, value, default=0.0):
        return number(value, default)

    def get_operating_total(self, rows_cost=None):
        """Charges d'exploitation réellement ajoutées au coût de revient.

        Le coût RH du planning estime la même main-d'œuvre que les missions : dès que les missions
        portent déjà un coût de personnel, il n'est PAS ajouté une seconde fois. Seuls le matériel et
        les autres charges s'ajoutent. (Anciens dossiers : montant unique conservé tel quel.)
        """
        stored = self.project.get("planning_operating_cost", 0.0)
        if not isinstance(stored, dict):
            return euro(number(stored, 0.0))
        if rows_cost is None:
            rows_cost = sum(self.calculate_row(row)["cost"] for row in self.rows)
        extra = number(stored.get("autres"), 0.0)
        rh = number(stored.get("rh"), 0.0)
        return euro(extra + (rh if rows_cost <= 0 else 0.0))

    def calculate_planning_operating_costs(self):
        """Calcule RH + matériel + autres charges à partir du planning généré."""
        rh = 0.0
        profile_map = {a.get("nom"): a for a in self.agents}
        selected_profile = getattr(self, "pg_profile_var", tk.StringVar(value="APS Jour")).get()
        profile = profile_map.get(selected_profile) or (self.agents[0] if self.agents else AGENTS_DEFAULT[0])

        for row in getattr(self, "generator_rows", []):
            start, end = row.get("start"), row.get("end")
            if not start or not end or end <= start:
                continue
            # Mêmes règles (nuit, dimanche, férié, mode de majoration) que le chiffrage principal.
            rh += self._price_interval(profile, start, end, 1)["cost"]

        # Feuilles hebdomadaires saisies agent par agent (coût réel des horaires saisis).
        rh += float(self._weekly_sheets_total()[0])

        def line_total(item):
            if "quantite" in item or "cout_unitaire" in item:
                return number(item.get("quantite"), 0.0) * number(item.get("cout_unitaire"), 0.0)
            return number(item.get("total"), 0.0)

        material = sum(line_total(x) for x in self.equipment)
        other = sum(number(x.get("total"), 0.0) for x in self.operating_costs if x.get("category") != "Matériel")
        return euro(rh), euro(material), euro(other)

    def _refresh_operating_summary(self):
        if not hasattr(self, "ops_total_var"):
            return
        rh, material, other = self.calculate_planning_operating_costs()
        total = rh + material + other
        self.ops_rh_var.set(f"{rh:,.2f} €".replace(",", "X").replace(".", ",").replace("X", " "))
        self.ops_material_var.set(f"{material:,.2f} €".replace(",", "X").replace(".", ",").replace("X", " "))
        self.ops_other_var.set(f"{other:,.2f} €".replace(",", "X").replace(".", ",").replace("X", " "))
        self.ops_total_var.set(f"{total:,.2f} €".replace(",", "X").replace(".", ",").replace("X", " "))
        return total

    def add_planning_cost_to_prestation(self):
        total = self._refresh_operating_summary()
        if total <= 0:
            messagebox.showwarning("Aucune charge", "Aucune charge d'exploitation calculée à ajouter.")
            return
        rh, material, other = self.calculate_planning_operating_costs()
        # On remplace le montant précédemment intégré : pas de double comptabilisation.
        self.project["planning_operating_cost"] = {
            "rh": euro(rh), "autres": euro(material + other), "total": euro(rh + material + other),
        }
        self.mark_dirty()
        added = self.get_operating_total()
        message = f"{added:,.2f} € de charges d'exploitation ont été intégrés au coût de revient de la prestation."
        if rh > 0 and added < euro(rh + material + other) - 0.005:
            message += (
                f"\n\nLe coût RH du planning ({rh:,.2f} €) n'a pas été ajouté : "
                "il est déjà compris dans le coût des missions."
            )
        messagebox.showinfo(
            "Coût ajouté",
            message.replace(",", "X").replace(".", ",").replace("X", " "),
        )
        self.show_page("summary")

    def build_operating_cost_panel(self, parent):
        box = self.card(parent)
        box.pack(fill="x", pady=(12, 12))
        tk.Label(box, text="Charges d'exploitation", bg=self.colors["surface"], fg=self.colors["text"],
                 font=("Consolas", 12, "bold")).pack(anchor="w", padx=16, pady=(14, 4))
        tk.Label(box, text="RH + matériel + autres charges. Les majorations RH reprennent les règles du chiffrage ; le RH inclut les feuilles hebdomadaires par agent.",
                 bg=self.colors["surface"], fg=self.colors["muted"], font=("Consolas", 9)).pack(anchor="w", padx=16, pady=(0, 10))

        grid = tk.Frame(box, bg=self.colors["surface"]); grid.pack(fill="x", padx=16, pady=(0, 14))
        self.ops_rh_var = tk.StringVar(value="0,00 €")
        self.ops_material_var = tk.StringVar(value="0,00 €")
        self.ops_other_var = tk.StringVar(value="0,00 €")
        self.ops_total_var = tk.StringVar(value="0,00 €")
        vals = [("Charges RH", self.ops_rh_var), ("Matériel", self.ops_material_var), ("Autres", self.ops_other_var), ("TOTAL", self.ops_total_var)]
        for i, (lab, var) in enumerate(vals):
            f = tk.Frame(grid, bg=self.colors["surface"]); f.grid(row=0, column=i, sticky="ew", padx=(0, 8)); grid.columnconfigure(i, weight=1)
            tk.Label(f, text=lab, bg=self.colors["surface"], fg=self.colors["muted"], font=("Consolas", 8, "bold")).pack(anchor="w")
            tk.Label(f, textvariable=var, bg=self.colors["surface"], fg=self.colors["primary"] if lab != "TOTAL" else self.colors["success"], font=("Consolas", 14, "bold")).pack(anchor="w", pady=(2, 0))

        actions = tk.Frame(box, bg=self.colors["surface"]); actions.pack(fill="x", padx=16, pady=(0, 14))
        ttk.Button(actions, text="↻ Recalculer", command=self._refresh_operating_summary).pack(side="left")
