    def _ws_sheets(self):
        store = self.project.get("agent_weekly_sheets")
        if not isinstance(store, dict):
            store = {}
            self.project["agent_weekly_sheets"] = store
        return store

    @staticmethod
    def _ws_key(agent, monday):
        return "%s|%s" % (str(agent).strip(), monday.isoformat())

    @staticmethod
    def _ws_split_key(key):
        agent, _, iso = str(key).rpartition("|")
        try:
            return agent, date.fromisoformat(iso)
        except ValueError:
            return agent, None

    def _weekly_sheets_total(self):
        """Cumul de toutes les feuilles hebdomadaires enregistrées : (coût, vente, heures, nombre)."""
        cost = sale = hours = WS_ZERO
        count = 0
        for key, sheet in list(self._ws_sheets().items()):
            _, monday = self._ws_split_key(key)
            if monday is None or not isinstance(sheet, dict):
                continue
            try:
                week = ws_compute_week(self, monday, sheet)
            except Exception:
                continue
            cost += week["cost"]
            sale += week["sale"]
            hours += week["hours"]
            count += 1
        return cost, sale, hours, count

    @staticmethod
    def _ws_fmt_h(minutes):
        return ("%.2f" % float(minutes / 60)).replace(".", ",")

    @staticmethod
    def _ws_fmt_hm(minutes):
        total = int((minutes).to_integral_value(rounding=ROUND_HALF_UP))
        return "%dh%02d" % (total // 60, total % 60)

