    # -- chargement / navigation ---------------------------------------------------------

    def _ws_apply_profile(self, event=None, recalc=True):
        profile = self.get_profile(self.ws_profile_var.get())
        values = {"rate_cost": profile.get("revient"), "rate_sale": profile.get("vente"), "maj_nuit": profile.get("nuit"),
                  "maj_dim": profile.get("dimanche"), "maj_ferie": profile.get("ferie")}
        self._ws_loading = True
        for key, value in values.items():
            self.ws_rate_vars[key].set(("%g" % number(value, 0.0)))
        self._ws_loading = False
        if recalc is True:
            self._ws_recalc()

    def _ws_collect_sheet(self):
        sheet = {k: v.get() for k, v in self.ws_rate_vars.items()}
        sheet.update({
            "agent": self._ws_agent, "profil": self.ws_profile_var.get(), "ot_on": bool(self.ws_ot_on.get()),
            "days": [{k: v.get() for k, v in dv.items()} for dv in self.ws_day_vars],
        })
        return sheet

    def _ws_fill_sheet(self, sheet):
        self._ws_loading = True
        if sheet:
            for key, var in self.ws_rate_vars.items():
                if key in sheet:
                    var.set(str(sheet[key]))
            self.ws_ot_on.set(bool(sheet.get("ot_on")))
            if sheet.get("profil"):
                self.ws_profile_var.set(sheet["profil"])
        entries = (sheet or {}).get("days") or []
        for i, dv in enumerate(self.ws_day_vars):
            entry = dict(ws_blank_day())
            if i < len(entries) and isinstance(entries[i], dict):
                entry.update({k: str(v) for k, v in entries[i].items() if k in entry})
            for key, var in dv.items():
                var.set(entry[key])
        self._ws_loading = False

    def _ws_load_current(self, event=None):
        agent = self.ws_agent_var.get().strip()
        typed = ws_parse_date(self.ws_week_var.get())
        if typed is None:
            self.ws_week_var.set(self._ws_monday.strftime("%d/%m/%Y"))
            messagebox.showwarning("Date invalide", "Saisissez la semaine au format JJ/MM/AAAA.")
            return
        monday = typed - timedelta(days=typed.weekday())
        self.ws_week_var.set(monday.strftime("%d/%m/%Y"))
        if agent == self._ws_agent and monday == self._ws_monday:
            return
        stored = self._ws_sheets().get(self._ws_key(agent, monday)) if agent else None
        # Une saisie faite avant d'avoir nommé l'agent est rattachée à cet agent (rien n'est perdu).
        keep_current = (not self._ws_agent) and stored is None and monday == self._ws_monday
        old_rates = self._ws_collect_sheet() if stored is None else None
        self._ws_agent, self._ws_monday = agent, monday
        if not keep_current:
            self._ws_fill_sheet(stored)
            if old_rates is not None:
                self._ws_loading = True
                for key, var in self.ws_rate_vars.items():
                    var.set(str(old_rates[key]))
                self.ws_ot_on.set(bool(old_rates["ot_on"]))
                self._ws_loading = False
        self._ws_recalc()

    def _ws_shift_week(self, delta):
        base = self._ws_monday
        if delta is None:
            today = date.today()
            target = today - timedelta(days=today.weekday())
        else:
            target = base + timedelta(days=delta)
        self.ws_week_var.set(target.strftime("%d/%m/%Y"))
        self._ws_load_current()

    def _ws_copy_monday(self):
        source = self.ws_day_vars[0]
        for dv in self.ws_day_vars[1:5]:
            for key in ("statut", "debut", "fin", "pause", "type", "autre", "prime"):
                dv[key].set(source[key].get())

    def _ws_clear_week(self):
        if not messagebox.askyesno("Vider la semaine", "Effacer tous les horaires de cette semaine ?"):
            return
        self._ws_loading = True
        for dv in self.ws_day_vars:
            for key, value in ws_blank_day().items():
                dv[key].set(value)
        self._ws_loading = False
        self._ws_recalc()

    # -- calcul et affichage ----------------------------------------------------------------

    def _ws_recalc(self, *args):
        if getattr(self, "_ws_loading", True) or not hasattr(self, "ws_total_vars"):
            return
        try:
            sheet = self._ws_collect_sheet()
            week = ws_compute_week(self, self._ws_monday, sheet)
        except Exception as error:  # le calcul ne doit jamais bloquer la saisie
            self.ws_status.configure(text="Calcul impossible : %s" % error, fg=self.colors["danger"])
            return
        c = self.colors
        for i, d in enumerate(week["days"]):
            rv = self.ws_res_vars[i]
            tag = ""
            if d["holiday"]:
                tag = " férié"
            elif d["date"].weekday() == 6:
                tag = " dim."
            rv["date"].set(d["date"].strftime("%d/%m") + tag)
            if d["worked"]:
                rv["hours"].set(self._ws_fmt_h(d["minutes"]))
                rv["night"].set(self._ws_fmt_h(d["night_min"]))
                rv["coef"].set("×%.4f" % float(d["coef"]) if d["coef"] is not None else "—")
                rv["cost"].set(money(d["cost"]))
                rv["sale"].set(money(d["sale"]))
            else:
                for key in ("hours", "night", "coef", "cost", "sale"):
                    rv[key].set("—")
            rv["alerts"].set(" • ".join(d["alerts"]) if d["alerts"] else ("✓" if d["worked"] else d["status"]))
            date_label, alert_label = self.ws_res_labels[i]
            date_label.configure(fg=c["warning"] if (d["holiday"] or d["date"].weekday() == 6) else c["text"])
            if d["error"]:
                alert_label.configure(fg=c["danger"])
            elif any("⚠" in a for a in d["alerts"]):
                alert_label.configure(fg=c["warning"])
            elif d["worked"]:
                alert_label.configure(fg=c["success"])
            else:
                alert_label.configure(fg=c["muted"])
        tv = self.ws_total_vars
        tv["hours"].set("%s h (%s)" % (self._ws_fmt_h(week["minutes"]), self._ws_fmt_hm(week["minutes"])))
        tv["days"].set("%d travaillé(s) • %d absence(s) • %d repos" % (week["worked_days"], week["absent_days"], week["rest_days"]))
        tv["cost"].set(money(week["cost"]) + " €")
        tv["sale"].set(money(week["sale"]) + " €")
        ot = week["overtime"]
        parts = ["Nuit : %s h • Dimanche : %s h • Férié : %s h" % (
            self._ws_fmt_h(week["night_hours"] * 60), self._ws_fmt_h(week["sunday_hours"] * 60), self._ws_fmt_h(week["holiday_hours"] * 60))]
        if ot["on"]:
            parts.append("Heures sup. : %s h à tranche 1 + %s h à tranche 2 = %s € de coût (incluses)" % (
                self._ws_fmt_h(ot["h1"] * 60), self._ws_fmt_h(ot["h2"] * 60), money(ot["cost"])))
        if week["primes"] > 0:
            parts.append("Primes : %s € (incluses dans le coût)" % money(week["primes"]))
        tv["ot"].set("   |   ".join(parts))
        self.ws_week_alerts.configure(text="\n".join(week["alerts"]))

        # Enregistrement automatique : seule une feuille non vide, avec un agent nommé, est comptée.
        if self._ws_agent:
            store = self._ws_sheets()
            key = self._ws_key(self._ws_agent, self._ws_monday)
            changed = False
            if ws_sheet_is_blank(sheet):
                if key in store:
                    del store[key]
                    changed = True
            elif store.get(key) != sheet:
                store[key] = sheet
                changed = True
            if changed:
                self.mark_dirty()
            self.ws_status.configure(text="Feuille enregistrée et comptée dans les charges RH." if key in store else "",
                                     fg=c["success"])
        else:
            self.ws_status.configure(text="Saisissez un nom d'agent pour enregistrer la feuille.", fg=c["warning"])
        self._ws_refresh_saved_list()
        self._refresh_operating_summary()

    def _ws_refresh_saved_list(self):
        tree = getattr(self, "ws_saved_tree", None)
        if tree is None:
            return
        tree.delete(*tree.get_children())
        rows = []
        for key, sheet in self._ws_sheets().items():
            agent, monday = self._ws_split_key(key)
            if monday is None or not isinstance(sheet, dict):
                continue
            try:
                week = ws_compute_week(self, monday, sheet)
            except Exception:
                continue
            rows.append((monday, agent, week, key))
        for monday, agent, week, key in sorted(rows, key=lambda r: (r[1].casefold(), r[0])):
            tree.insert("", "end", iid=key, values=(agent, monday.strftime("%d/%m/%Y"), self._ws_fmt_h(week["minutes"]) + " h",
                                                    money(week["cost"]), money(week["sale"])))
        cost, sale, hours, count = self._weekly_sheets_total()
        self.ws_total_vars["cumul"].set("Cumul : %d feuille(s) • %s h • coût %s € • vente %s €" % (
            count, self._ws_fmt_h(hours * 60), money(cost), money(sale)))

    def _ws_open_saved(self, event=None):
        selection = self.ws_saved_tree.selection()
        if not selection:
            return
        agent, monday = self._ws_split_key(selection[0])
        if monday is None:
            return
        self.ws_agent_var.set(agent)
        self.ws_week_var.set(monday.strftime("%d/%m/%Y"))
        self._ws_load_current()

    def _ws_delete_saved(self):
        selection = self.ws_saved_tree.selection()
        if not selection:
            return
        if not messagebox.askyesno("Supprimer", "Supprimer cette feuille hebdomadaire ?"):
            return
        key = selection[0]
        agent, monday = self._ws_split_key(key)
        self._ws_sheets().pop(key, None)
        self.mark_dirty()
        if agent == self._ws_agent and monday == self._ws_monday:
            self._ws_clear_week_silent()
        self._ws_refresh_saved_list()
        self._refresh_operating_summary()

    def _ws_clear_week_silent(self):
        self._ws_loading = True
        for dv in self.ws_day_vars:
            for key, value in ws_blank_day().items():
                dv[key].set(value)
        self._ws_loading = False
        self._ws_recalc()

    def _ws_run_verification(self):
        sheet = self._ws_collect_sheet()
        week = ws_compute_week(self, self._ws_monday, sheet)
        ok, lines = ws_verification_report(self, self._ws_monday, sheet, week)
        win = tk.Toplevel(self)
        win.title("Contrôle mathématique — feuille hebdomadaire")
        win.geometry("900x600")
        win.configure(bg=self.colors["background"])
        text = tk.Text(win, wrap="none", font=("Consolas", 9), bg=self.colors["surface"], fg=self.colors["text"], relief="flat")
        ys = ttk.Scrollbar(win, orient="vertical", command=text.yview)
        xs = ttk.Scrollbar(win, orient="horizontal", command=text.xview)
        text.configure(yscrollcommand=ys.set, xscrollcommand=xs.set)
        xs.pack(side="bottom", fill="x")
        ys.pack(side="right", fill="y")
        text.pack(side="left", fill="both", expand=True)
        text.insert("1.0", "\n".join(lines))
        text.tag_configure("good", foreground=self.colors["success"])
        text.tag_configure("bad", foreground=self.colors["danger"])
        last = int(text.index("end-1c").split(".")[0])
        text.tag_add("good" if ok else "bad", "%d.0" % last, "%d.end" % last)
        text.configure(state="disabled")

    def build_calculator(self):
        """Affiche le calculateur commercial directement dans la zone de page."""
        container = tk.Frame(self.page_frame, bg=self.colors["background"])
        container.pack(fill="both", expand=True)

        self.calculator_frame = ExcelCalculateur(container)
        self.calculator_frame.pack(fill="both", expand=True)

    # ------------------------------------------------------------------
    # Composants visuels
    # ------------------------------------------------------------------

    def card(self, parent, **kwargs):
        return tk.Frame(
            parent,
            bg=self.colors["surface"],
            highlightbackground=self.colors["border"],
            highlightthickness=1,
            **kwargs,
        )

    def rounded_card(self, parent):
        """Carte aux coins arrondis. Retourne (carte à placer, zone interne pour les widgets)."""
        try:
            outer_bg = parent.cget("bg")
        except tk.TclError:
            outer_bg = self.colors["background"]
        card = RoundedCard(
            parent,
            fill=self.colors["surface"],
            border=blend_hex(self.colors["accent"], self.colors["surface"], 0.50),
            outer_bg=outer_bg,
            hover_border=self.colors["accent2"],
            radius=12,
        )
        return card, card.inner

    def finish_card(self, card):
        """Active le survol et ajuste la taille une fois le contenu construit."""
        card.enable_hover()
        card.refresh()

    def _bind_card_click(self, widget, command):
        """Rend toute la carte cliquable (les boutons gardent leur propre commande)."""
        if isinstance(widget, (ttk.Button, tk.Button)):
            return
        widget.bind("<Button-1>", lambda event: command(), add="+")
        try:
            widget.configure(cursor="hand2")
        except tk.TclError:
            pass
        for child in widget.winfo_children():
            self._bind_card_click(child, command)

    def create_kpi(self, parent, title, value, color):
        frame, body = self.rounded_card(parent)
        tk.Frame(body, bg=color, width=5).pack(side="left", fill="y")

        content = tk.Frame(body, bg=self.colors["surface"])
        content.pack(side="left", fill="both", expand=True, padx=15, pady=12)

        tk.Label(
            content,
            text=title,
            bg=self.colors["surface"],
            fg=self.colors["muted"],
            font=("Consolas", 9),
        ).pack(anchor="w")

        label = tk.Label(
            content,
            text=value,
            bg=self.colors["surface"],
            fg=self.colors["text"],
            font=("Consolas", 17, "bold"),
        )
        label.pack(anchor="w", pady=(5, 0))
        frame.refresh()
        self.fx_count(label, value)
        return frame, label

    def add_section_heading(self, parent, title, description=""):
        ttk.Label(parent, text=title, style="Section.TLabel").pack(anchor="w")
        if description:
            ttk.Label(parent, text=description, style="Muted.TLabel").pack(
                anchor="w", pady=(3, 15)
            )

    def update_top_status(self):
        total = sum(self.calculate_row(row)["total"] for row in self.rows)
        marker = " • MODIFIÉ" if self.dirty else ""
        self.topbar_status.config(
            text=f"{len(self.rows)} mission(s)  •  Total HT : {money(total)} €{marker}"
        )
        if hasattr(self, "save_state_dot"):
            self.save_state_dot.config(
                fg=self.colors["warning"] if self.dirty else self.colors["success"],
                text="●" if self.dirty else "✓",
            )

