    def apply_discount(self):
        if not hasattr(self, "remise_var"):
            return

        remise = number(self.remise_var.get(), -1)
        if remise < 0 or remise > 100:
            messagebox.showwarning(
                "Remise incorrecte",
                "La remise doit être comprise entre 0 et 100 %."
            )
            return

        self.project["remise"] = remise
        self.mark_dirty()
        self.show_page("summary")

