    def _selected_chart_metrics(self):
        primary = self.chart_metric_var.get() or "Chiffre d’affaires (HT)"
        selected = [primary]
        for name, var in self.chart_metric_vars.items():
            if name != primary and var.get():
                selected.append(name)
        return selected

    def _chart_series(self):
        labels = [row.get("mission") or f"Mission {i}" for i, row in enumerate(self.rows, start=1)]
        selected = self._selected_chart_metrics()
        metrics = [self.calculate_row(row) for row in self.rows]
        margins = self.mission_margins() if "Marge nette" in selected else []
        series = {}
        for metric in selected:
            values = []
            for i, m in enumerate(metrics):
                if metric == "Chiffre d’affaires (HT)":
                    value = m["total"]
                elif metric == "Coût de revient":
                    value = m["cost"]
                elif metric == "Marge nette":
                    value = margins[i]
                elif metric == "Heures":
                    value = m["quantity"]
                else:
                    value = m["agents"]
                values.append(value)
            series[metric] = values
        return labels, series

    @staticmethod
    def _chart_value_text(metric, value):
        if metric in ("Chiffre d’affaires (HT)", "Coût de revient", "Marge nette"):
            return f"{money(value)} €"
        if metric == "Heures":
            return f"{value:.2f} h"
        return f"{value:.0f}"

    def _hide_chart_tooltip(self, event=None):
        ctl = getattr(self, "_fx_chart3d", None)
        if event is not None and ctl is not None and ctl.active:
            ctl.mouse = (-9999, -9999)
        if self.chart_tooltip is not None:
            try:
                self.chart_tooltip.destroy()
            except tk.TclError:
                pass
            self.chart_tooltip = None

    def _chart_hover(self, event):
        ctl = getattr(self, "_fx_chart3d", None)
        if ctl is not None and ctl.active and ctl.canvas is self.chart_canvas:
            ctl.on_motion(event)
            return
        self._hide_chart_tooltip()
        for x1, y1, x2, y2, label, metric, value in self.chart_hitboxes:
            if x1 <= event.x <= x2 and y1 <= event.y <= y2:
                canvas = self.chart_canvas
                self.chart_tooltip = tk.Toplevel(canvas)
                self.chart_tooltip.overrideredirect(True)
                self.chart_tooltip.attributes("-topmost", True)
                frame = tk.Frame(
                    self.chart_tooltip, bg=self.colors["nav"],
                    highlightbackground=self.colors["border"], highlightthickness=1
                )
                frame.pack()
                tk.Label(
                    frame, text=label, bg=self.colors["nav"], fg="white",
                    font=("Consolas", 9, "bold")
                ).pack(anchor="w", padx=9, pady=(6, 1))
                tk.Label(
                    frame, text=f"{metric} : {self._chart_value_text(metric, value)}",
                    bg=self.colors["nav"], fg="#CBD5E1",
                    font=("Consolas", 9)
                ).pack(anchor="w", padx=9, pady=(0, 6))
                self.chart_tooltip.geometry(f"+{event.x_root + 14}+{event.y_root + 14}")
                break

    @staticmethod
    def _nice_scale(vmin, vmax, ticks=5):
        """Bornes et pas « propres » (1, 2, 2,5, 5 × 10ⁿ) pour un axe lisible."""
        if vmax <= vmin:
            vmax = vmin + 1.0
        raw = (vmax - vmin) / float(ticks)
        mag = 10 ** math.floor(math.log10(raw))
        step = mag
        for factor in (1, 2, 2.5, 5, 10):
            step = factor * mag
            if step >= raw - 1e-12:
                break
        low = math.floor(vmin / step + 1e-9) * step
        high = math.ceil(vmax / step - 1e-9) * step
        if high <= low:
            high = low + step
        return low, high, step

    @staticmethod
    def _axis_group(metric):
        return "eur" if metric in ("Chiffre d’affaires (HT)", "Coût de revient", "Marge nette") else "qty"

    @staticmethod
    def _tick_text(group, value, step):
        digits = 0 if step >= 1 else (1 if step >= 0.1 else 2)
        text = f"{value:,.{digits}f}".replace(",", " ").replace(".", ",")
        return text + " €" if group == "eur" else text

    @staticmethod
    def _mix_color(color_a, color_b, ratio):
        """Mélange deux couleurs #RRGGBB (ratio = part de color_a)."""
        try:
            a = [int(color_a[i:i + 2], 16) for i in (1, 3, 5)]
            b = [int(color_b[i:i + 2], 16) for i in (1, 3, 5)]
            mixed = [int(x * ratio + y * (1 - ratio)) for x, y in zip(a, b)]
            return "#%02X%02X%02X" % tuple(mixed)
        except (ValueError, IndexError):
            return color_a

    def _draw_result_chart_frame(self, p=1.0):
        canvas = self.chart_canvas
        if canvas is None or not canvas.winfo_exists():
            return
        self._hide_chart_tooltip()
        canvas.delete("all")
        self.chart_hitboxes = []
        width = max(canvas.winfo_width(), 700)
        height = max(canvas.winfo_height(), 380)
        labels, series = self._chart_series()
        surface, muted, text_color = self.colors["surface"], self.colors["muted"], self.colors["text"]
        if not labels:
            canvas.create_text(
                width / 2, height / 2, text="Ajoutez des missions pour afficher le graphique.",
                fill=muted, font=("Consolas", 11)
            )
            return

        chart_type = self.chart_type_var.get()
        metric_names = list(series.keys())
        if chart_type == "Répartition" and len(metric_names) > 1:
            metric_names = metric_names[:1]
            series = {metric_names[0]: series[metric_names[0]]}

        # Palette homogène : verts dominants, turquoise et magenta pour distinguer les séries.
        palette = [
            self.colors["accent"], "#2DD4BF", "#38BDF8", self.colors["accent2"],
            "#A3E635", "#22D3EE", "#A78BFA", "#6EE7B7",
        ]

        def short_label(label, limit):
            limit = max(limit, 4)
            return label if len(label) <= limit else label[:limit - 1] + "…"

        # ------------------------------------------------------------------
        # Répartition : anneau + légende chiffrée
        # ------------------------------------------------------------------
        if chart_type == "Répartition":
            metric = metric_names[0]
            values = series[metric]
            if any(v < 0 for v in values):
                canvas.create_text(
                    width / 2, height / 2, text="La répartition n'est disponible que pour des valeurs positives.",
                    fill=muted, font=("Consolas", 10)
                )
                return
            total = sum(values)
            if total <= 0:
                canvas.create_text(width / 2, height / 2, text="Aucune valeur positive à représenter.", fill=muted)
                return
            cx, cy = width * 0.30, height * 0.52
            radius = min(width * 0.26, height * 0.40)
            hole = radius * 0.55
            angle = 90.0
            for i, value in enumerate(values):
                extent = value / total * 360.0 * p
                color = palette[i % len(palette)]
                if extent >= 359.9:
                    canvas.create_oval(cx - radius, cy - radius, cx + radius, cy + radius, fill=color, outline=surface, width=2)
                elif extent > 0:
                    canvas.create_arc(
                        cx - radius, cy - radius, cx + radius, cy + radius,
                        start=angle, extent=-extent, fill=color, outline=surface, width=2, style="pieslice"
                    )
                    if extent >= 22:
                        mid = math.radians(angle - extent / 2.0)
                        rr = (radius + hole) / 2.0
                        canvas.create_text(
                            cx + rr * math.cos(mid), cy - rr * math.sin(mid), text=f"{value / total * 100:.0f}%",
                            fill="white", font=("Consolas", 9, "bold")
                        )
                angle -= extent
            canvas.create_oval(cx - hole, cy - hole, cx + hole, cy + hole, fill=surface, outline=surface)
            canvas.create_text(cx, cy - 9, text="Total", fill=muted, font=("Consolas", 9))
            canvas.create_text(cx, cy + 9, text=self._chart_value_text(metric, total), fill=text_color, font=("Consolas", 11, "bold"))
            canvas.create_text(28, 20, anchor="w", text=f"Répartition — {metric}", fill=text_color, font=("Consolas", 10, "bold"))
            lx = width * 0.56
            row_h = 24
            for i, (label, value) in enumerate(zip(labels, values)):
                y = 52 + i * row_h
                if y > height - 30:
                    canvas.create_text(lx, y, anchor="w", text="… %d autre(s) mission(s)" % (len(labels) - i), fill=muted, font=("Consolas", 9))
                    break
                canvas.create_rectangle(lx, y, lx + 13, y + 13, fill=palette[i % len(palette)], outline="")
                canvas.create_text(lx + 20, y + 6, anchor="w", text=short_label(label, 28), fill=text_color, font=("Consolas", 9))
                canvas.create_text(
                    width - 28, y + 6, anchor="e",
                    text=f"{self._chart_value_text(metric, value)}  ({value / total * 100:.1f}%)",
                    fill=muted, font=("Consolas", 9)
                )
                self.chart_hitboxes.append((lx, y - 3, width - 15, y + 18, label, metric, value))
            return

        # ------------------------------------------------------------------
        # Barres / courbes : axes indépendants € et quantités
        # ------------------------------------------------------------------
        groups = []
        for metric in metric_names:
            grp = self._axis_group(metric)
            if grp not in groups:
                groups.append(grp)
        left_group = groups[0]
        right_group = groups[1] if len(groups) > 1 else None
        left, top, bottom = 84, 62, 62
        right = 84 if right_group else 30
        plot_w, plot_h = width - left - right, height - top - bottom

        scales = {}
        for grp in groups:
            vals = [v for m in metric_names if self._axis_group(m) == grp for v in series[m]]
            scales[grp] = self._nice_scale(min(vals + [0.0]), max(vals + [0.0]))

        def y_for(grp, value):
            low, high, _ = scales[grp]
            return top + (high - value) / (high - low) * plot_h

        # Grille et axe gauche
        low, high, step = scales[left_group]
        value = low
        while value <= high + step * 0.001:
            y = y_for(left_group, value)
            zero = abs(value) < step * 1e-6
            canvas.create_line(left, y, width - right, y, fill=text_color if zero else self.colors["border"], width=1.5 if zero else 1,
                               dash=() if zero else (2, 4))
            canvas.create_text(left - 8, y, anchor="e", text=self._tick_text(left_group, value, step), fill=muted, font=("Consolas", 8))
            value += step
        # Axe droit
        if right_group:
            rlow, rhigh, rstep = scales[right_group]
            value = rlow
            while value <= rhigh + rstep * 0.001:
                y = y_for(right_group, value)
                canvas.create_line(width - right, y, width - right + 5, y, fill=muted)
                canvas.create_text(width - right + 9, y, anchor="w", text=self._tick_text(right_group, value, rstep), fill=muted, font=("Consolas", 8))
                value += rstep
        canvas.create_line(left, top, left, top + plot_h, fill=muted)
        if right_group:
            canvas.create_line(width - right, top, width - right, top + plot_h, fill=muted)

        step_x = plot_w / float(len(labels))
        centers = [left + step_x * (i + 0.5) for i in range(len(labels))]
        label_limit = int(step_x / 6.5)
        skip = 1 if step_x >= 46 else int(math.ceil(46.0 / step_x))
        show_values = len(labels) * len(metric_names) <= 24

        def put_value_label(x, y, metric, value, above=True):
            item = canvas.create_text(x, y, text=self._chart_value_text(metric, value), fill=text_color, font=("Consolas", 7, "bold"))
            bbox = canvas.bbox(item)
            if bbox:
                back = canvas.create_rectangle(bbox[0] - 2, bbox[1] - 1, bbox[2] + 2, bbox[3] + 1, fill=surface, outline="")
                canvas.tag_lower(back, item)

        if chart_type in ("Barres", "Combiné"):
            bar_metrics = metric_names if chart_type == "Barres" else metric_names[:1]
            group_w = min(step_x * 0.80, 40.0 * len(bar_metrics) + 10)
            bar_w = max(6.0, group_w / len(bar_metrics) - 4)
            for i, label in enumerate(labels):
                group_left = centers[i] - (bar_w * len(bar_metrics) + 4 * (len(bar_metrics) - 1)) / 2.0
                for j, metric in enumerate(bar_metrics):
                    grp = self._axis_group(metric)
                    val = series[metric][i]
                    x = group_left + j * (bar_w + 4)
                    y, base = y_for(grp, val), y_for(grp, 0.0)
                    y = base + (y - base) * p
                    canvas.create_rectangle(x, min(y, base), x + bar_w, max(y, base), fill=palette[j % len(palette)], outline="")
                    self.chart_hitboxes.append((x, min(y, base) - 2, x + bar_w, max(y, base) + 2, label, metric, val))
                    if show_values:
                        put_value_label(x + bar_w / 2, (y - 9) if val >= 0 else (y + 10), metric, val)
        else:
            # Repères verticaux : chaque point se place à l'intersection de sa catégorie et de sa valeur.
            for x in centers:
                canvas.create_line(x, top, x, top + plot_h, fill=self.colors["border"], dash=(1, 5))
            if len(labels) == 1:
                canvas.create_text(width / 2, top + 14, text="Ajoutez une deuxième mission pour visualiser une évolution.", fill=muted, font=("Consolas", 9))
            for j, metric in enumerate(metric_names):
                grp = self._axis_group(metric)
                color = palette[j % len(palette)]
                pts = [(centers[i], y_for(grp, 0.0) + (y_for(grp, series[metric][i]) - y_for(grp, 0.0)) * p) for i in range(len(labels))]
                if len(metric_names) == 1 and len(pts) > 1:
                    base = y_for(grp, 0.0)
                    poly = [pts[0][0], base]
                    for px, py in pts:
                        poly += [px, py]
                    poly += [pts[-1][0], base]
                    canvas.create_polygon(*poly, fill=self._mix_color(color, surface, 0.16), outline="")
                if len(pts) > 1:
                    # Segments droits (smooth désactivé) : la ligne passe exactement par chaque point.
                    canvas.create_line(*[c for pt in pts for c in pt], fill=color, width=3, smooth=False, joinstyle="round", capstyle="round")
                for i, (px, py) in enumerate(pts):
                    val = series[metric][i]
                    canvas.create_oval(px - 6, py - 6, px + 6, py + 6, fill=surface, outline=color, width=3)
                    canvas.create_oval(px - 2, py - 2, px + 2, py + 2, fill=color, outline=color)
                    self.chart_hitboxes.append((px - 10, py - 10, px + 10, py + 10, labels[i], metric, val))
                    if show_values:
                        put_value_label(px, py - 17 if val >= 0 else py + 17, metric, val)

        if chart_type == "Combiné":
            # Indicateur principal en barres, comparaisons en courbes.
            curve_metrics = metric_names[1:] or metric_names[:1]
            for metric in curve_metrics:
                grp = self._axis_group(metric)
                color = (self.colors["accent2"] if len(metric_names) == 1
                         else palette[metric_names.index(metric) % len(palette)])
                pts = [(centers[i], y_for(grp, 0.0) + (y_for(grp, series[metric][i]) - y_for(grp, 0.0)) * p) for i in range(len(labels))]
                if len(pts) > 1:
                    canvas.create_line(*[coord for point in pts for coord in point],
                                       fill=color, width=3, smooth=False,
                                       joinstyle="round", capstyle="round")
                for i, (px, py) in enumerate(pts):
                    val = series[metric][i]
                    canvas.create_oval(px - 6, py - 6, px + 6, py + 6,
                                       fill=surface, outline=color, width=3)
                    canvas.create_oval(px - 2, py - 2, px + 2, py + 2,
                                       fill=color, outline=color)
                    self.chart_hitboxes.append((px - 10, py - 10, px + 10, py + 10,
                                                labels[i], metric, val))
                    if show_values:
                        put_value_label(px, py - 17 if val >= 0 else py + 17, metric, val)
        # Libellés de l'axe horizontal
        for i, label in enumerate(labels):
            if i % skip:
                continue
            canvas.create_text(centers[i], top + plot_h + 16, text=short_label(label, label_limit), fill=text_color, font=("Consolas", 8))
        canvas.create_line(left, top + plot_h, width - right, top + plot_h, fill=muted)

        # Légende
        x = left
        for j, metric in enumerate(metric_names):
            color = palette[j % len(palette)]
            unit = "€" if self._axis_group(metric) == "eur" else ("h" if metric == "Heures" else "nb")
            side = "" if not right_group else (" ◀" if self._axis_group(metric) == left_group else " ▶")
            if chart_type == "Combiné" and len(metric_names) == 1:
                canvas.create_rectangle(x, 17, x + 12, 29, fill=palette[0], outline="")
                canvas.create_line(x, 23, x + 12, 23, fill=self.colors["accent2"], width=2)
                color = self.colors["accent2"]
            elif chart_type == "Combiné" and metric != metric_names[0]:
                canvas.create_line(x, 23, x + 12, 23, fill=color, width=3)
            else:
                canvas.create_rectangle(x, 17, x + 12, 29, fill=color, outline="")
            item = canvas.create_text(x + 18, 23, anchor="w", text=f"{metric} [{unit}]{side}", fill=text_color, font=("Consolas", 8, "bold"))
            bbox = canvas.bbox(item)
            x = (bbox[2] if bbox else x + 150) + 22
        canvas.create_text(
            width - right, 23, anchor="e", text=f"{len(labels)} mission(s) • survolez un point ou une barre",
            fill=muted, font=("Consolas", 8)
        )

