    def _build_security_dossier_workspace(self, parent, widgets):
        """Outils de préparation opérationnelle propres à un site, distincts de la veille."""
        self._security_dossier_selected_index = None
        self._security_dossier_last_geocode = 0.0
        colors = self.colors
        card = self.card(parent)
        card.pack(fill="both", expand=False, pady=(0, 10))
        tk.Label(card, text="REPÉRAGE DU SITE ET ENVIRONNEMENT", bg=colors["surface"],
                 fg=colors["neon"], font=("Consolas", 10, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 3))
        tk.Label(card, text="Préparez cette prestation : accès, secours, transports et points utiles autour du site. Ces données cartographiques ne remplacent pas une reconnaissance terrain.",
                 bg=colors["surface"], fg=colors["muted"], anchor="w", justify="left", wraplength=1100).pack(fill="x", padx=14, pady=(0, 7))
        row = tk.Frame(card, bg=colors["surface"])
        row.pack(fill="x", padx=12, pady=(0, 5))
        self._security_dossier_address = ttk.Entry(row)
        self._security_dossier_address.pack(side="left", fill="x", expand=True, padx=(0, 7))
        self._security_dossier_address.insert(0, "Adresse complète du site (rue, code postal, ville)")
        self._security_dossier_radius = ttk.Combobox(row, values=("500 m", "1 km", "2 km"), state="readonly", width=8)
        self._security_dossier_radius.set("1 km")
        self._security_dossier_radius.pack(side="left", padx=(0, 7))
