        try:
            self._write_report_pdf_file(path)
            messagebox.showinfo('PDF créé', f'Le rapport PDF a été créé avec succès.\n\nFichier :\n{path}')
        except Exception as error:
            messagebox.showerror('Erreur PDF', str(error))

