    # ========================================================
    # OUTILS DECIMAL
    # ========================================================

    @staticmethod
    def decimal(texte):
        """
        Conversion sûre d'une saisie utilisateur vers Decimal.
        """
        if texte is None:
            return None

        texte = str(texte).strip()

        if not texte:
            return None

        texte = (
            texte
            .replace("€", "")
            .replace("%", "")
            .replace(" ", "")
            .replace(",", ".")
            .strip()
        )

        try:
            return Decimal(texte)
        except (InvalidOperation, ValueError):
            return None

    @staticmethod
    def format_decimal(valeur, decimales=2):
        """
        Format d'affichage uniquement.
        Le calcul interne reste en Decimal non arrondi.
        """
        if valeur is None:
            return ""

        quantite = Decimal("1").scaleb(-decimales)

        valeur = valeur.quantize(
            quantite,
            rounding=ROUND_HALF_UP
        )

        return f"{valeur:.{decimales}f}"

    @staticmethod
    def proche_zero(valeur):
        return valeur is not None and valeur == ZERO

