    def _bind_button_hover(self, button, normal, hover):
        """Ajoute un retour visuel discret aux commandes classiques Tk."""
        button.bind("<Enter>", lambda event: button.configure(bg=hover), add="+")
        button.bind("<Leave>", lambda event: button.configure(bg=normal), add="+")

    def copier_resultats(self):
        """Copie les valeurs visibles du calculateur dans un format facile à coller."""
        lignes = []
        for nom, libelle, unite in self.elements:
            valeur = self.champs[nom].get().strip()
            if valeur:
                suffixe = (" " + unite) if unite else ""
                lignes.append(f"{libelle} : {valeur}{suffixe}")

        if not lignes:
            self.message.configure(text="Aucune valeur à copier pour le moment.", fg="#B45309")
            return "break"

        self.clipboard_clear()
        self.clipboard_append("\n".join(lignes))
        self.update_idletasks()
        self.message.configure(
            text=f"✓ {len(lignes)} valeur(s) copiée(s) dans le presse-papiers.",
            fg=self.VERT,
        )
        return "break"

    # ========================================================
    # OUTILS TVA / PRIX HT — INDEPENDANTS DU TABLEAU
    # ========================================================

    @staticmethod
    def arrondir_monnaie(valeur):
        """Arrondi commercial : 2 décimales, moitié vers le haut."""
        if valeur is None:
            return None
        return valeur.quantize(CENT, rounding=ROUND_HALF_UP)

